INSERT INTO "public"."case_explanation_searches" VALUES ('fc86581b-ee87-412b-8907-6f945eb3ab4e', '民间借贷纠纷', '[{''id'': ''loan_1'', ''title'': ''赵某与钱某民间借贷纠纷一案'', ''case_number'': ''(2024)京0101民初4567号'', ''court'': ''北京市东城区人民法院'', ''date'': ''2024-06-30'', ''summary'': ''原告赵某起诉被告钱某要求偿还借款本金10万元及利息。法院经审理支持原告诉讼请求。'', ''similarity'': 94.0, ''source'': ''中国裁判文书网'', ''url'': ''https://wenshu.court.gov.cn/xxxx''}, {''id'': ''loan_2'', ''title'': ''孙某与李某民间借贷纠纷一案'', ''case_number'': ''(2024)沪0101民初8901号'', ''court'': ''上海市黄浦区人民法院'', ''date'': ''2024-08-05'', ''summary'': ''原告孙某起诉被告李某要求偿还借款本金5万元及利息。法院经审理支持原告诉讼请求。'', ''similarity'': 91.0, ''source'': ''中国裁判文书网'', ''url'': ''https://wenshu.court.gov.cn/xxxx''}, {''id'': ''loan_3'', ''title'': ''周某与吴某民间借贷纠纷一案'', ''case_number'': ''(2024)粤0101民初3012号'', ''court'': ''广州市越秀区人民法院'', ''date'': ''2024-08-25'', ''summary'': ''原告周某起诉被告吴某要求偿还借款本金15万元及利息。法院经审理支持原告诉讼请求。'', ''similarity'': 88.0, ''source'': ''中国裁判文书网'', ''url'': ''https://wenshu.court.gov.cn/xxxx''}]', '[{"id": "loan_1", "title": "\u8d75\u67d0\u4e0e\u94b1\u67d0\u6c11\u95f4\u501f\u8d37\u7ea0\u7eb7\u4e00\u6848", "case_number": "(2024)\u4eac0101\u6c11\u521d4567\u53f7", "court": "\u5317\u4eac\u5e02\u4e1c\u57ce\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2024-06-30", "summary": "\u539f\u544a\u8d75\u67d0\u8d77\u8bc9\u88ab\u544a\u94b1\u67d0\u8981\u6c42\u507f\u8fd8\u501f\u6b3e\u672c\u91d110\u4e07\u5143\u53ca\u5229\u606f\u3002\u6cd5\u9662\u7ecf\u5ba1\u7406\u652f\u6301\u539f\u544a\u8bc9\u8bbc\u8bf7\u6c42\u3002", "similarity": 94.0, "source": "\u4e2d\u56fd\u88c1\u5224\u6587\u4e66\u7f51", "url": "https://wenshu.court.gov.cn/xxxx"}, {"id": "loan_2", "title": "\u5b59\u67d0\u4e0e\u674e\u67d0\u6c11\u95f4\u501f\u8d37\u7ea0\u7eb7\u4e00\u6848", "case_number": "(2024)\u6caa0101\u6c11\u521d8901\u53f7", "court": "\u4e0a\u6d77\u5e02\u9ec4\u6d66\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2024-08-05", "summary": "\u539f\u544a\u5b59\u67d0\u8d77\u8bc9\u88ab\u544a\u674e\u67d0\u8981\u6c42\u507f\u8fd8\u501f\u6b