INSERT INTO "public"."case_explanation_searches" VALUES ('22f42942-32b6-4c06-9c1e-92d7f6cf0dfe', '房产继承纠纷', '[{''id'': ''property_1'', ''title'': ''李某与王某房产继承纠纷一案'', ''case_number'': ''(2024)京0101民初3456号'', ''court'': ''北京市东城区人民法院'', ''date'': ''2024-06-25'', ''summary'': ''原告李某与被告王某因父亲遗留房产继承问题产生纠纷，法院根据继承法判决按法定继承分割房产。'', ''similarity'': 94.5, ''source'': ''中国裁判文书网'', ''url'': ''https://wenshu.court.gov.cn/xxxx''}, {''id'': ''property_2'', ''title'': ''张某与刘某房屋买卖合同纠纷一案'', ''case_number'': ''(2024)沪0101民初7890号'', ''court'': ''上海市黄浦区人民法院'', ''date'': ''2024-07-30'', ''summary'': ''原告张某因被告刘某未按约定交付房屋提起诉讼，要求解除合同并返还购房款100万元。法院经审理支持原告诉讼请求。'', ''similarity'': 91.5, ''source'': ''中国裁判文书网'', ''url'': ''https://wenshu.court.gov.cn/xxxx''}, {''id'': ''property_3'', ''title'': ''王某与李某房屋产权纠纷一案'', ''case_number'': ''(2024)粤0101民初2012号'', ''court'': ''广州市越秀区人民法院'', ''date'': ''2024-08-20'', ''summary'': ''原告王某因被告李某侵犯房屋产权提起诉讼，要求确认产权并赔偿损失。法院经审理确认原告为房屋所有权人，判决被告赔偿损失5万元。'', ''similarity'': 88.5, ''source'': ''中国裁判文书网'', ''url'': ''https://wenshu.court.gov.cn/xxxx''}]', '[{"id": "property_1", "title": "\u674e\u67d0\u4e0e\u738b\u67d0\u623f\u4ea7\u7ee7\u627f\u7ea0\u7eb7\u4e00\u6848", "case_number": "(2024)\u4eac0101\u6c11\u521d3456\u53f7", "court": "\u5317\u4eac\u5e02\u4e1c\u57ce\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2024-06-25", "summary": "\u539f\u544a\u674e\u67d0\u4e0e\u88ab\u544a\u738b\u67d0\u56e0\u7236\u4eb2\u9057\u7559\u623f\u4ea7\u7ee7\u627f\u95ee\u9898\u4ea7\u751f\u7ea0\u7eb7\uff0c\u6cd5\u9662\u6839\u636e\u7ee7\u627f\u6cd5\u5224\u51b3\u6309\u6cd5\u5b9a\u7ee7\u627f\u5206\u5272\u623f\u4ea7\u3002", "similarity": 94.5, "source": "\u4e2d\u56fd\u88c1\u5224\u6587\u4e66\u7f51", "url": "https://wenshu.court.gov.cn/xxxx"}, {"id": "property_2", "title": "\u5f20\u67d0\u4e0e\u5218\u67d0\u623f\u5c4b\u4e70\u5356\u5408\u540c\u7ea0\u7eb7\u4e00\u6848", "case_number": "(2024)\u6caa0101\u6c11\u521d7890\u53f7", "court": "\u4e0a\u6d77\u5e02\u9ec4\u6d66\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2024-07-30", "summary": "\u539f\u544a\u5f20\u67d0\u56e0\u88ab\u544a\u5218\u67d0\u672a\u6309\u7ea6\u5b9a\u4ea4\u4ed8\u623f\u5c4b\u63d0\u8d77\u8bc9\u8bbc\uff0c\u8981\u6c42\u89e3\u9664\u5408\u540c\u5e76\u8fd4\u8fd8\u8d2d\u623f\u6b3e100\u4e07\u5143\u3002\u6cd5\u9662\u7ecf\u5ba1\u7406\u652f\u6301\u539f\u544a\u8bc9\u8bbc\u8bf7\u6c42\u3002", "similarity": 91.5, "source": "\u4e2d\u56fd\u88c1\u5224\u6587\u4e66\u7f51", "url": "https://wenshu.court.gov.cn/xxxx"}, {"id": "property_3", "title": "\u738b\u67d0\u4e0e\u674e\u67d0\u623f\u5c4b\u4ea7\u6743\u7ea0\u7eb7\u4e00\u6848", "case_number": "(2024)\u7ca40101\u6c11\u521d2012\u53f7", "court": "\u5e7f\u5dde\u5e02\u8d8a\u79c0\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2024-08-20", "summary": "\u539f\u544a\u738b\u67d0\u56e0\u88ab\u544a\u674e\u67d0\u4fb5\u72af\u623f\u5c4b\u4ea7\u6743\u63d0\u8d77\u8bc9\u8bbc\uff0c\u8981\u6c42\u786e\u8ba4\u4ea7\u6743\u5e76\u8d54\u507f\u635f\u5931\u3002\u6cd5\u9662\u7ecf\u5ba1\u7406\u786e\u8ba4\u539f\u544a\u4e3a\u623f\u5c4b\u6240\u6709\u6743\u4eba\uff0c\u5224\u51b3\u88ab\u544a\u8d54\u507f\u635f\u59315\u4e07\u5143\u3002", "similarity": 88.5, "source": "\u4e2d\u56fd\u88c1\u5224\u6587\u4e66\u7f51", "url": "https://wenshu.court.gov.cn/xxxx"}]', '2026-03-31 15:03:28.236452+08', '2026-03-31 15:03:28.236452+08');

-- ----------------------------
-- Table structure for case_predictions
-- ----------------------------
DROP TABLE IF EXISTS "public"."case_predictions";
CREATE TABLE "public"."case_predictions" (
  "id" varchar COLLATE "pg_catalog"."default" NOT NULL,
  "dispute_id" varchar COLLATE "pg_catalog"."default",
  "similar_cases" json,
  "win_probability" int4,
  "predicted_amount" varchar COLLATE "pg_catalog"."default",
  "court_tendency" text COLLATE "pg_catalog"."default",
  "optimization_suggestions" text COLLATE "pg_catalog"."default",
  "risk_analysis" text COLLATE "pg_catalog"."default",
  "created_at" timestamptz(6) DEFAULT now(),
  "updated_at" timestamptz(6) DEFAULT now()
)
;

