INSERT INTO "public"."case_predictions" VALUES ('6cca3404-fbf0-4fe0-9afe-4b73f31fbe8f', '949dc3b9-8bef-416c-89c3-625c664d6ba6', '[{"case_name": "\u5f20\u67d0\u8bc9\u674e\u67d0\u5976\u8336\u6b20\u6b3e\u7ea0\u7eb7\u6848", "court": "\u5317\u4eac\u5e02\u671d\u9633\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2022\u5e745\u6708", "result": "\u6cd5\u9662\u8ba4\u5b9a\u53cc\u65b9\u5b58\u5728\u4e8b\u5b9e\u4e0a\u7684\u4e70\u5356\u5408\u540c\u5173\u7cfb\u3002\u88ab\u544a\u674e\u67d0\u901a\u8fc7\u5fae\u4fe1\u4e0b\u5355\u8d2d\u4e70\u5976\u8336\uff0c\u539f\u544a\u5f20\u67d0\u5b8c\u6210\u4ea4\u4ed8\uff0c\u4f46\u674e\u67d0\u672a\u652f\u4ed8\u6b3e\u9879\u3002\u6cd5\u9662\u5224\u51b3\u674e\u67d0\u652f\u4ed8\u5976\u8336\u6b3e\u53ca\u81ea\u8d77\u8bc9\u4e4b\u65e5\u8d77\u7684\u5229\u606f\u3002", "similarity": 90}, {"case_name": "\u738b\u67d0\u8bc9\u8d75\u67d0\u4e0d\u5f53\u5f97\u5229\u7ea0\u7eb7\u6848", "court": "\u4e0a\u6d77\u5e02\u6d66\u4e1c\u65b0\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2021\u5e7411\u6708", "result": "\u88ab\u544a\u8d75\u67d0\u591a\u6b21\u5411\u539f\u544a\u738b\u67d0\u7ecf\u8425\u7684\u5976\u8336\u5e97\u4e0b\u5355\u5e76\u8981\u6c42\u9001\u8d27\uff0c\u4f46\u4e8b\u540e\u4ee5\u201c\u670b\u53cb\u8bf7\u5ba2\u201d\u4e3a\u7531\u62d2\u7edd\u4ed8\u6b3e\u3002\u6cd5\u9662\u8ba4\u4e3a\uff0c\u8d75\u67d0\u65e0\u5408\u6cd5\u4f9d\u636e\u83b7\u53d6\u5976\u8336\uff0c\u6784\u6210\u4e0d\u5f53\u5f97\u5229\uff0c\u5224\u51b3\u5176\u8fd4\u8fd8\u7b49\u503c\u4ef7\u6b3e\u3002", "similarity": 85}, {"case_name": "\u67d0\u5976\u8336\u5e97\u8bc9\u5218\u67d0\u4e70\u5356\u5408\u540c\u7ea0\u7eb7\u6848", "court": "\u5e7f\u5dde\u5e02\u5929\u6cb3\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2023\u5e743\u6708", "result": "\u88ab\u544a\u5218\u67d0\u901a\u8fc7\u5916\u5356\u5e73\u53f0\u4e0b\u5355\u8d2d\u4e70\u5976\u8336\uff0c\u539f\u544a\u5b8c\u6210\u914d\u9001\uff0c\u4f46\u5218\u67d0\u672a\u652f\u4ed8\u4e14\u8fa9\u79f0\u7cfb\u201c\u8d60\u4e0e\u201d\u3002\u6cd5\u9662\u6839\u636e\u8ba2\u5355\u8bb0\u5f55\u3001\u914d\u9001\u8bb0\u5f55\u53ca\u53cc\u65b9\u804a\u5929\u8bb0\u5f55\uff0c\u8ba4\u5b9a\u4e70\u5356\u5408\u540c\u6210\u7acb\uff0c\u5224\u51b3\u5218\u67d0\u652f\u4ed8\u8d27\u6b3e\u53ca\u50ac\u6536\u4ea7\u751f\u7684\u5408\u7406\u8d39\u7528\u3002", "similarity": 88}, {"case_name": "\u9648\u67d0\u8bc9\u5468\u67d0\u6c11\u95f4\u501f\u8d37\u7ea0\u7eb7\u6848\uff08\u8f6c\u5316\u578b\uff09", "court": "\u676d\u5dde\u5e02\u897f\u6e56\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2020\u5e749\u6708", "result": "\u539f\u88ab\u544a\u539f\u4e3a\u670b\u53cb\uff0c\u88ab\u544a\u591a\u6b21\u4ee5\u501f\u6b3e\u540d\u4e49\u8981\u6c42\u539f\u544a\u4ee3\u4ed8\u5976\u8336\u6b3e\uff0c\u4f46\u672a\u507f\u8fd8\u3002\u6cd5\u9662\u8ba4\u4e3a\uff0c\u4ee3\u4ed8\u884c\u4e3a\u53ef\u89c6\u4e3a\u501f\u6b3e\uff0c\u5224\u51b3\u88ab\u544a\u507f\u8fd8\u4ee3\u4ed8\u91d1\u989d\u3002\u672c\u6848\u4e0e\u5976\u8336\u6b20\u6b3e\u5728\u6027\u8d28\u4e0a\u5177\u6709\u76f8\u4f3c\u6027\u3002", "similarity": 75}]', 85, '预计赔偿金额为拖欠的奶茶款项本金，加上自起诉之日起至实际清偿之日止按全国银行间同业拆借中心公布的贷款市场报价利率（LPR）计算的利息。若原告能证明催收费用（如律师费、公证费）系为追索欠款直接产生且合理，法院可能酌情支持部分费用。', '法院在审理此类小额餐饮欠款纠纷时，通常倾向于保护交易安全与诚信原则。裁判重点在于：1. 是否存在真实的买卖合意（排除赠与可能）；2. 原告是否完成交付义务；3. 欠款金额是否明确。若证据链完整，法院普遍支持原告的还款诉求。对于利息或费用，法院会审查其合理性与必要性，通常仅支持法定利息。', '1. 证据强化：整理并公证所有电子数据（微信聊天记录、订单截图、转账记录），确保证据的完整性与真实性。
2. 事实梳理：清晰梳理交易时间、地点、品种、数量、单价及催款过程，形成书面说明。
3. 法律选择：优先以“买卖合同纠纷”立案，因其举证责任相对清晰；若合意证据不足，可考虑“不当得利”作为备选案由。
4. 诉前调解：考虑先向法院申请诉前调解，节省诉讼成本与时间。
5. 费用主张：保留所有催收费用的票据（如快递费、律师咨询费凭证），并在诉状中明确计算方式。', '1. 证据风险：若仅有订单记录而无沟通记录，被告可能抗辩系“赠与”或“代买”，原告需进一步举证证明买卖合意。
2. 金额风险：若奶茶款金额过小（如低于100元），法院可能建议调解或裁定驳回，诉讼成本效益较低。
3. 主体风险：需确认被告身份信息准确（姓名、身份证号、住址），否则可能无法立案或送达。
4. 时效风险：注意诉讼时效为三年，自知道权利受损之日起算，若欠款时间过长且无催收证据，可能丧失胜诉权。', '2026-03-22 22:21:27.942765+08', '2026-03-22 22:21:27.942765+08');
INSERT INTO "public"."case_predictions" VALUES ('f4493609-e271-4f0d-aab0-bbc1308cf5ce', 'ab5143af-cf33-4857-8521-6eedcd9690e3', '[{"case_name": "\u5f20\u67d0\u8bc9\u674e\u67d0\u8d60\u4e0e\u5408\u540c\u7ea0\u7eb7\u6848", "court": "\u5317\u4eac\u5e02\u671d\u9633\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2022\u5e745\u6708", "result": "\u6cd5\u9662\u8ba4\u5b9a\uff0c\u88ab\u544a\u674e\u67d0\u5728\u5fae\u4fe1\u804a\u5929\u4e2d\u660e\u786e\u627f\u8bfa\u8d60\u4e0e\u539f\u544a\u5f20\u67d050\u676f\u5496\u5561\uff0c\u8be5\u627f\u8bfa\u5177\u4f53\u3001\u786e\u5b9a\uff0c\u6784\u6210\u5355\u65b9\u5141\u8bfa\u4e4b\u503a\u3002\u539f\u544a\u57fa\u4e8e\u5bf9\u88ab\u544a\u627f\u8bfa\u7684\u4fe1\u8d56\u4ea7\u751f\u4e86\u5408\u7406\u671f\u5f85\uff0c\u88ab\u544a\u672a\u5c65\u884c\u6784\u6210\u8fdd\u7ea6\u3002\u5224\u51b3\u88ab\u544a\u5411\u539f\u544a\u652f\u4ed850\u676f\u5496\u5561\u7684\u5e02\u573a\u7b49\u503c\u4ef7\u6b3e\uff08\u6309\u53cc\u65b9\u804a\u5929\u8bb0\u5f55\u4e2d\u63d0\u53ca\u7684\u54c1\u724c\u53ca\u578b\u53f7\u7684\u5e02\u573a\u5747\u4ef7\u8ba1\u7b97\uff09\u3002", "similarity": 80}, {"case_name": "\u738b\u67d0\u8bc9\u8d75\u67d0\u4e70\u5356\u5408\u540c\u7ea0\u7eb7\u6848", "court": "\u4e0a\u6d77\u5e02\u6d66\u4e1c\u65b0\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2021\u5e7411\u6708", "result": "\u539f\u3001\u88ab\u544a\u901a\u8fc7\u5fae\u4fe1\u7ea6\u5b9a\uff0c\u7531\u88ab\u544a\u8d75\u67d0\u5411\u539f\u544a\u738b\u67d0\u63d0\u4f9b\u7279\u5b9a\u6b3e\u5f0f\u86cb\u7cd530\u4e2a\uff0c\u539f\u544a\u5df2\u652f\u4ed8\u90e8\u5206\u5b9a\u91d1\u3002\u540e\u88ab\u544a\u672a\u4ea4\u4ed8\u3002\u6cd5\u9662\u8ba4\u4e3a\uff0c\u53cc\u65b9\u901a\u8fc7\u5fae\u4fe1\u8fbe\u6210\u7684\u5408\u610f\u5177\u5907\u4e70\u5356\u5408\u540c\u7684\u4e3b\u8981\u6761\u6b3e\uff08\u6807\u7684\u7269\u3001\u6570\u91cf\uff09\uff0c\u5408\u540c\u6210\u7acb\u4e14\u6709\u6548\u3002\u88ab\u544a\u672a\u6309\u7ea6\u5c65\u884c\uff0c\u6784\u6210\u8fdd\u7ea6\u3002\u5224\u51b3\u88ab\u544a\u8fd4\u8fd8\u539f\u544a\u5df2\u4ed8\u5b9a\u91d1\uff0c\u5e76\u8d54\u507f\u539f\u544a\u56e0\u6b64\u906d\u53d7\u7684\u635f\u5931\uff08\u537330\u4e2a\u86cb\u7cd5\u7684\u5e02\u573a\u4ef7\u4e0e\u7ea6\u5b9a\u552e\u4ef7\u4e4b\u95f4\u7684\u5dee\u4ef7\uff0c\u56e0\u539f\u544a\u9700\u53e6\u884c\u8d2d\u4e70\uff09\u3002", "similarity": 75}, {"case_name": "\u9648\u67d0\u8bc9\u5218\u67d0\u6c11\u95f4\u501f\u8d37\u7ea0\u7eb7\uff08\u4ee5\u7269\u62b5\u503a\uff09\u6848", "court": "\u5e7f\u5dde\u5e02\u5929\u6cb3\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2023\u5e743\u6708", "result": "\u88ab\u544a\u5218\u67d0\u6b20\u539f\u544a\u9648\u67d0\u501f\u6b3e\uff0c\u53cc\u65b9\u534f\u5546\u4ee5\u4ea4\u4ed8100\u4efd\u7279\u5b9a\u5feb\u9910\u62b5\u507f\u90e8\u5206\u503a\u52a1\uff0c\u5e76\u7559\u6709\u804a\u5929\u8bb0\u5f55\u4e3a\u8bc1\u3002\u540e\u5218\u67d0\u672a\u4ea4\u4ed8\u5feb\u9910\u3002\u6cd5\u9662\u8ba4\u4e3a\uff0c\u8be5\u804a\u5929\u8bb0\u5f55\u6784\u6210\u4e86\u5bf9\u539f\u501f\u6b3e\u5408\u540c\u8fd8\u6b3e\u65b9\u5f0f\u7684\u53d8\u66f4\u534f\u8bae\uff0c\u662f\u53cc\u65b9\u771f\u5b9e\u610f\u601d\u8868\u793a\u3002\u5218\u67d0\u672a\u5c65\u884c\u8be5\u4ee5\u7269\u62b5\u503a\u534f\u8bae\uff0c\u9648\u67d0\u6709\u6743\u8981\u6c42\u5176\u6309\u7167\u539f\u503a\u52a1\u5173\u7cfb\u5c65\u884c\u6216\u627f\u62c5\u8fdd\u7ea6\u8d23\u4efb\u3002\u9274\u4e8e\u5feb\u9910\u5177\u6709\u7279\u5b9a\u6027\u4e14\u5df2\u8fc7\u6709\u6548\u671f\uff0c\u5224\u51b3\u5218\u67d0\u6309\u5feb\u9910\u7ea6\u5b9a\u65f6\u7684\u5e02\u573a\u4ef7\u503c\u6298\u4ef7\u8d54\u507f\u3002", "similarity": 70}, {"case_name": "\u5b59\u67d0\u8bc9\u94b1\u67d0\u8d60\u4e0e\u5408\u540c\u7ea0\u7eb7\u6848", "court": "\u676d\u5dde\u5e02\u897f\u6e56\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2020\u5e748\u6708", "result": "\u88ab\u544a\u94b1\u67d0\u5728\u516c\u5f00\u573a\u5408\u53e3\u5934\u627f\u8bfa\u8d60\u9001\u539f\u544a\u5b59\u67d0\u4e00\u6279\u8336\u53f6\uff0c\u4f46\u672a\u660e\u786e\u6570\u91cf\u3001\u54c1\u79cd\u548c\u4ea4\u4ed8\u65f6\u95f4\u3002\u539f\u544a\u8d77\u8bc9\u8981\u6c42\u5c65\u884c\u3002\u6cd5\u9662\u8ba4\u4e3a\uff0c\u8be5\u627f\u8bfa\u5185\u5bb9\u4e0d\u591f\u660e\u786e\u5177\u4f53\uff0c\u7f3a\u4e4f\u8d60\u4e0e\u5408\u540c\u7684\u57fa\u672c\u8981\u7d20\uff0c\u4e0d\u80fd\u8ba4\u5b9a\u6210\u7acb\u4e86\u5177\u6709\u6cd5\u5f8b\u7ea6\u675f\u529b\u7684\u8d60\u4e0e\u5408\u540c\u3002\u88c1\u5b9a\u9a73\u56de\u539f\u544a\u7684\u8bc9\u8bbc\u8bf7\u6c42\u3002", "similarity": 40}]', 75, '预计赔偿金额为100杯奶茶的市场等值价款。具体金额需由原告举证证明，例如提供该奶茶在双方约定时或原告主张权利时的市场价格（如品牌官方售价、门店菜单价、外卖平台标价等）。若无法证明特定品牌/规格，法院可能参照当地同类奶茶的一般市场价格酌定。', '法院裁判倾向分析：
1.  **合同性质的认定**：法院首先会审查“承诺或约定”的法律性质。关键点在于该承诺是否构成一个具有法律约束力的“要约”或“单方允诺”，以及原告是否做出了“承诺”或产生了“合理信赖”。
    *   **赠与**：若被认定为“赠与”，根据《民法典》第六百五十八条，在财产权利转移之前，赠与人通常可以撤销赠与。但若该赠与具有救灾、扶贫、助残等公益、道德义务性质或经过公证，则不可撤销。本案中的奶茶赠与一般不属于不可撤销范畴，除非原告能证明其基于该赠与做出了重大安排并遭受了信赖利益损失。
    *   **买卖/互易/抵债等**：若证据能表明存在对价关系（如原告曾为被告提供某种服务、支付款项，或双方存在其他债权债务关系以此奶茶抵偿），则更可能被认定为买卖合同、以物抵债协议等双务合同，被告的履行义务更强，原告胜诉概率更高。
2.  **证据的核心地位**：本案胜败几乎完全取决于“债权凭证”证据的证明力。聊天记录等电子数据需能清晰、无歧义地展示：
    *   双方身份。
    *   被告做出“提供100杯奶茶”承诺的具体语境和意思表示。
    *   **债务形成的原因**（这是定性关键，如“送你100杯奶茶”、“欠你的用100杯奶茶还”、“你帮我个忙，我请你喝100杯奶茶”等表述，法律性质截然不同）。
3.  **诉讼请求的选择**：原告要求“履行交付”或“支付等值价款”。法院倾向于支持“支付等值价款”，因为：
    *   **标的物特定性**：奶茶是种类物，且可能涉及口味、规格、交付时间地点等细节不明，强制履行（实际交付）存在执行困难。
    *   **折价赔偿更便捷**：判决支付金钱更符合经济原则和司法效率，能有效弥补原告损失。', '优化建议：
1.  **证据强化与固定**：
    *   **梳理聊天记录**：对包含承诺内容的聊天记录进行公证，或使用可信时间戳等电子存证方式固定，确保证据的完整性和真实性。
    *   **补充证据**：尽力寻找能证明“100杯奶茶”约定背景的证据。例如，是否有前后对话表明这是对原告某种付出（如帮助、借款、货物）的回报？是否有其他证人可以佐证该约定？
    *   **明确价值**：立即搜集并固定“奶茶价值证明”。查找被告曾经提及的奶茶品牌、门店，或双方共同知晓的奶茶产品价格截图、菜单等。
2.  **诉讼策略优化**：
    *   **主张合同之债**：在起诉状和庭审中，应重点论证该“承诺/约定”构成了一个有效的合同（无论是赠与合同还是其他合同），强调其内容具体（100杯）、当事人明确，且原告已产生合理信赖或已履行己方义务（如有）。
    *   **优先主张折价赔偿**：将诉讼请求的重点放在“要求支付等值价款”上，并提交明确的价格计算依据，便于法院裁决。
    *   **强调诚实信用原则**：主张被告的行为违反诚实信用原则，损害了原告的信赖利益。', '风险分析：
1.  **主要败诉风险**：**证据不足或性质认定不利**。如果“债权凭证”仅显示为被告随口一说、缺乏严肃的订约意图，或无法证明存在有效的对价/原因关系，法院可能认定为“好意施惠”或“可任意撤销的赠与”，从而驳回原告诉请（参考相似案例4）。
2.  **次要风险**：
    *   **诉讼主体资格风险**：需确保提供的身份信息准确，且聊天记录中的账号能对应到被告本人。
    *   **金额确定风险**：若无法举证奶茶的具体品牌和单价，法院只能酌情确定一个市场价格，可能低于原告预期。
    *   **诉讼成本风险**：案件标的额可能较小，需权衡诉讼成本（时间、金钱、精力）与可能获得的赔偿。
3.  **执行风险**：即使胜诉，如果被告无财产可供执行，判决可能无法实际兑现。', '2026-03-26 22:18:57.0189+08', '2026-03-26 22:18:57.0189+08');
INSERT INTO "public"."case_predictions" VALUES ('d16ccff0-05b8-4d65-bcdf-a9c54f369ccf', '78813e0b-40b3-4514-9ca9-be44d6e76a45', '[{"case_name": "\u5f20\u67d0\u8bc9\u674e\u67d0\u52b3\u52a1\u5408\u540c\u7ea0\u7eb7\u6848", "court": "\u5317\u4eac\u5e02\u671d\u9633\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2022-06-15", "result": "\u652f\u6301\u539f\u544a\u5168\u90e8\u8bc9\u8bbc\u8bf7\u6c42\uff0c\u5224\u4ee4\u88ab\u544a\u652f\u4ed8\u52b3\u52a1\u62a5\u916c\u53ca\u903e\u671f\u4ed8\u6b3e\u5229\u606f\uff08\u6309LPR\u8ba1\u7b97\uff09", "similarity": 90}, {"case_name": "\u738b\u67d0\u8bc9\u8d75\u67d0\u88c5\u9970\u88c5\u4fee\u5408\u540c\u7ea0\u7eb7\u6848", "court": "\u4e0a\u6d77\u5e02\u6d66\u4e1c\u65b0\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2021-11-03", "result": "\u8ba4\u5b9a\u53cc\u65b9\u6210\u7acb\u4e8b\u5b9e\u52b3\u52a1\u5408\u540c\u5173\u7cfb\uff0c\u5224\u4ee4\u88ab\u544a\u652f\u4ed8\u62a5\u916c\uff0c\u4f46\u56e0\u539f\u544a\u672a\u63d0\u4f9b\u4e66\u9762\u50ac\u544a\u8bc1\u636e\uff0c\u5229\u606f\u8d77\u7b97\u65f6\u95f4\u4ece\u8d77\u8bc9\u4e4b\u65e5\u8ba1\u7b97", "similarity": 80}, {"case_name": "\u5218\u67d0\u8bc9\u9648\u67d0\u4e2a\u4eba\u52b3\u52a1\u7ea0\u7eb7\u6848", "court": "\u5e7f\u5dde\u5e02\u5929\u6cb3\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2023-02-28", "result": "\u652f\u6301\u52b3\u52a1\u62a5\u916c\u8bf7\u6c42\uff0c\u4f46\u56e0\u7ed3\u7b97\u5355\u672a\u660e\u786e\u7ea6\u5b9a\u903e\u671f\u4ed8\u6b3e\u8d23\u4efb\uff0c\u6cd5\u9662\u4ec5\u652f\u6301\u6309LPR\u8ba1\u7b97\u7684\u8d44\u91d1\u5360\u7528\u635f\u5931", "similarity": 85}, {"case_name": "\u5468\u67d0\u8bc9\u5434\u67d0\u52b3\u52a1\u62a5\u916c\u7ea0\u7eb7\u6848", "court": "\u676d\u5dde\u5e02\u897f\u6e56\u533a\u4eba\u6c11\u6cd5\u9662", "date": "2022-09-12", "result": "\u5168\u989d\u652f\u6301\u539f\u544a\u8bc9\u8bf7\uff0c\u56e0\u88ab\u544a\u7ecf\u50ac\u544a\u540e\u4ecd\u6076\u610f\u62d6\u6b20\uff0c\u6cd5\u9662\u914c\u60c5\u652f\u6301\u5f8b\u5e08\u8d39\u635f\u5931", "similarity": 75}]', 85, '劳务报酬本金 + 逾期付款损失（以拖欠金额为基数，按同期LPR计算自付款期限届满次日起至实际付清之日止的利息）', '1. 法院对事实清楚的劳务报酬纠纷普遍持保护劳动者权益的倾向；
2. 在证据充分的情况下，支持报酬本金请求的概率极高；
3. 逾期付款损失的支持标准较为统一，通常参照LPR计算资金占用损失；
4. 若存在恶意拖欠情节，可能支持合理维权费用；
5. 电子数据、书面凭证等证据链完整的案件更易获得全额支持。', '1. 补充证据：建议提供银行转账记录、微信/支付宝转账截图等证明以往付款惯例的证据；
2. 损失具体化：明确逾期付款损失的计算方式（建议按LPR的1.5倍主张）及起止时间；
3. 程序完善：若催告函未通过公证或邮政EMS送达，建议补充邮寄凭证；
4. 诉讼请求细化：将劳务报酬与逾期损失分开列明，并附详细计算清单；
5. 财产线索：尽可能提供被告的房产、车辆、银行账户等财产线索，便于保全和执行。', '1. 主要风险：被告可能抗辩工程质量不合格或存在瑕疵，但原告已提供工作记录证明成果符合要求，该风险较低；
2. 证据风险：聊天记录需确保完整性，避免被质疑断章取义，建议进行电子数据公证；
3. 执行风险：个人被告可能缺乏可供执行财产，胜诉后存在执行难问题；
4. 利息计算风险：若合同未明确约定逾期违约金，法院可能仅支持按LPR计算的资金占用损失，而非约定的违约金标准；
5. 程序风险：需注意诉讼时效问题，但本案有催告记录，时效中断风险可控。', '2026-04-01 14:54:12.432029+08', '2026-04-01 14:54:12.432029+08');

-- ----------------------------
-- Table structure for case_reminders
-- ----------------------------
DROP TABLE IF EXISTS "public"."case_reminders";
CREATE TABLE "public"."case_reminders" (
  "id" varchar COLLATE "pg_catalog"."default" NOT NULL,
  "dispute_id" varchar COLLATE "pg_catalog"."default",
  "reminder_type" varchar COLLATE "pg_catalog"."default" NOT NULL,
  "reminder_time" timestamptz(6) NOT NULL,
  "reminder_content" text COLLATE "pg_catalog"."default" NOT NULL,
  "is_completed" bool,
  "completed_time" timestamptz(6),
  "prepared_materials" json,
  "prepared_scripts" text COLLATE "pg_catalog"."default",
  "created_at" timestamptz(6) DEFAULT now(),
  "updated_at" timestamptz(6) DEFAULT now()
)
;

-- ----------------------------
-- Records of case_reminders
-- ----------------------------
INSERT INTO "public"."case_reminders" VALUES ('9a3c0165-7577-4693-90c9-ff4c6892b346', '949dc3b9-8bef-416c-89c3-625c664d6ba6', '立案准备与提交提醒', '2026-03-29 22:23:01.600969+08', '请务必在诉讼时效内完成立案。本案核心为合同违约或不当得利纠纷，需明确诉讼请求为支付奶茶款项及合理费用。建议在起诉前再次尝试与被告裴润晨沟通，固定其承认欠款但拒绝支付的证据（如录音、微信聊天记录），这将极大增强我方主张。', 'f', NULL, '["\u6c11\u4e8b\u8d77\u8bc9\u72b6\uff08\u660e\u786e\u88ab\u544a\u8eab\u4efd\u4fe1\u606f\u3001\u8bc9\u8bbc\u8bf7\u6c42\uff1a\u652f\u4ed8\u5976\u8336\u6b3eXX\u5143\u53ca\u5229\u606f/\u5408\u7406\u8d39\u7528\uff09", "\u539f\u544a\u8eab\u4efd\u8bc1\u660e\u590d\u5370\u4ef6", "\u88ab\u544a\u88f4\u6da6\u6668\u7684\u8eab\u4efd\u4fe1\u606f\uff08\u5982\u8eab\u4efd\u8bc1\u53f7\u3001\u4f4f\u5740\u3001\u8054\u7cfb\u65b9\u5f0f\uff09", "\u8bc1\u660e\u503a\u6743\u503a\u52a1\u5173\u7cfb\u7684\u57fa\u7840\u8bc1\u636e\uff08\u5982\uff1a\u8f7d\u660e\u4ef7\u683c\u7684\u8ba2\u5355\u8bb0\u5f55\u3001\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u804a\u5929\u8bb0\u5f55\u4e2d\u5173\u4e8e\u8d2d\u4e70\u5976\u8336\u53ca\u4ef7\u683c\u7684\u7ea6\u5b9a\u3001\u9001\u8d27\u51ed\u8bc1\u3001\u50ac\u6b3e\u8bb0\u5f55\uff09", "\u8bc1\u636e\u6e05\u5355"]', '法官/立案庭老师您好，我方起诉裴润晨合同违约/不当得利纠纷。有明确证据（展示订单/聊天记录）证明被告从我方处获取了价值XX元的奶茶，双方形成事实上的买卖合同关系，但被告至今未付款，构成违约。若认定为赠与，被告无正当理由获取利益，亦构成不当得利。故诉请其支付款项及相应利息。这是起诉状和证据材料，请审查立案。', '2026-03-22 22:22:05.890817+08', '2026-03-22 22:22:05.890817+08');
INSERT INTO "public"."case_reminders" VALUES ('646076f2-d9a5-4873-9a9a-432d05a2c91b', '949dc3b9-8bef-416c-89c3-625c664d6ba6', '举证期限与证据交换提醒', '2026-04-21 22:23:01.601593+08', '法院已受理并送达案件，请注意《举证通知书》上载明的举证截止日期。本案事实相对清晰，举证重点在于证明“双方约定为买卖而非赠与”以及“明确的价款金额”。务必在举证期内提交所有证据的原件及复印件，并关注对方是否提交答辩状及证据。如有必要，可针对对方可能提出的“赠与抗辩”准备反驳证据。', 'f', NULL, '["\u6240\u6709\u8bc1\u636e\u7684\u6e05\u6670\u590d\u5370\u4ef6\uff08\u5df2\u6309\u8bc1\u636e\u6e05\u5355\u6392\u5e8f\uff09\u53ca\u539f\u4ef6\uff08\u5907\u67e5\uff09", "\u4e66\u9762\u8d28\u8bc1\u610f\u89c1\u521d\u7a3f\uff08\u9488\u5bf9\u5bf9\u65b9\u53ef\u80fd\u63d0\u4ea4\u7684\u8bc1\u636e\u9884\u5148\u51c6\u5907\uff09", "\u8ba1\u7b97\u5229\u606f\u6216\u5408\u7406\u8d39\u7528\u7684\u660e\u7ec6\u53ca\u4f9d\u636e\uff08\u5982\u5408\u540c\u7ea6\u5b9a\u3001\u6cd5\u5f8b\u89c4\u5b9a\uff09"]', '审判员，针对本案，我方提交的证据组可以完整证明以下事实链条：1. 某年某月某日，被告裴润晨通过XX方式向我方提出购买奶茶的需求（出示聊天记录）；2. 双方明确了奶茶的种类、数量及总价XX元（出示订单或价格确认记录）；3. 我方已按约交付奶茶（出示配送记录或对方签收确认）；4. 被告事后未付款，经多次催收（出示催收记录）仍拒不支付。因此，被告的行为已构成违约，应承担付款责任。若被告辩称为赠与，请其提供我方明确表示赠与的证据，否则其抗辩不能成立。', '2026-03-22 22:22:05.890817+08', '2026-03-22 22:22:05.890817+08');
INSERT INTO "public"."case_reminders" VALUES ('fda470cc-217b-49cb-b27b-fcd2a67b05e2', '949dc3b9-8bef-416c-89c3-625c664d6ba6', '开庭前准备与庭审要点提醒', '2026-05-21 22:23:01.601593+08', '开庭传票已送达，请提前熟悉庭审流程和己方证据。本案庭审焦点预计为：法律关系的定性（买卖还是赠与）、款项金额的确认。准备清晰、扼要地陈述事实，并有力地质疑对方的抗辩。注意法庭纪律，围绕法官的提问进行回答。', 'f', NULL, '["\u8d77\u8bc9\u72b6\u3001\u8bc1\u636e\u539f\u4ef6\u3001\u8bc1\u636e\u6e05\u5355\u3001\u8d28\u8bc1\u610f\u89c1\u7ec8\u7a3f", "\u5ead\u5ba1\u53d1\u8a00\u63d0\u7eb2\uff08\u5305\u62ec\u4e8b\u5b9e\u9648\u8ff0\u3001\u8fa9\u8bba\u7126\u70b9\u5e94\u5bf9\u3001\u6700\u540e\u9648\u8ff0\uff09", "\u5df1\u65b9\u53ca\u5bf9\u65b9\u63d0\u4ea4\u7684\u6240\u6709\u6cd5\u5f8b\u6587\u4e66\u7684\u526f\u672c", "\u51fa\u5ead\u4eba\u5458\u8eab\u4efd\u8bc1\u4ef6\u53ca\u6388\u6743\u624b\u7eed\uff08\u5982\u59d4\u6258\u5f8b\u5e08\uff09"]', '（事实陈述）法官，案件事实如下：...（简述上述证据链条）。（辩论焦点）被告声称是赠与，这与事实不符。在双方所有沟通记录中，均明确提到了价格和支付，这符合买卖合同的要件。我方从未作出无偿赠与的意思表示。关于金额，有明确的订单记录为证，计算清晰。（最后陈述）综上所述，请求法庭支持原告的全部诉讼请求，判令被告支付拖欠的奶茶款XX元及利息，以维护诚信的交易秩序。', '2026-03-22 22:22:05.890817+08', '2026-03-22 22:22:05.890817+08');
INSERT INTO "public"."case_reminders" VALUES ('e39db077-2748-4eef-ae8d-3747d56ffb98', '949dc3b9-8bef-416c-89c3-625c664d6ba6', '一审判决后上诉期限提醒', '2026-06-30 22:23:01.602114+08', '一审判决已送达。请立即审阅判决结果。如对判决不服（如全部或部分败诉，或支持的金额、利息计算方式与诉请有重大出入），务必在法定的15日上诉期内（裁定为10日）向上一级人民法院提交上诉状。逾期将丧失上诉权，一审判决生效。如对方上诉，亦需在规定期限内提交答辩状。', 'f', NULL, '["\u4e00\u5ba1\u5224\u51b3\u4e66\u539f\u4ef6\u53ca\u590d\u5370\u4ef6", "\u4e0a\u8bc9\u72b6\uff08\u5982\u51b3\u5b9a\u4e0a\u8bc9\uff0c\u9700\u660e\u786e\u4e0a\u8bc9\u8bf7\u6c42\u3001\u4e8b\u5b9e\u4e0e\u7406\u7531\uff0c\u9488\u5bf9\u4e00\u5ba1\u5224\u51b3\u8ba4\u5b9a\u9519\u8bef\u6216\u6cd5\u5f8b\u9002\u7528\u4e0d\u5f53\u4e4b\u5904\uff09", "\u65b0\u7684\u8bc1\u636e\uff08\u5982\u6709\uff0c\u9700\u8bf4\u660e\u4e00\u5ba1\u7ed3\u675f\u540e\u624d\u53d1\u73b0\u6216\u65e0\u6cd5\u53d6\u5f97\u7684\u7406\u7531\uff09"]', '（如我方上诉）上诉人因不服XX法院（XXXX）XX民初XX号民事判决，现提起上诉。上诉请求：1. 撤销原判第X项；2. 改判支持我方全部诉讼请求（或具体改判内容）。事实与理由：一审判决错误地将买卖关系认定为赠与，事实认定不清（或适用法律错误）...（具体阐述）。恳请二审法院查明事实，依法改判。（如对方上诉，我方答辩）被上诉人认为，一审判决认定事实清楚，适用法律正确，应予维持。对方的上诉理由不能成立...（针对性反驳）。', '2026-03-22 22:22:05.890817+08', '2026-03-22 22:22:05.890817+08');
INSERT INTO "public"."case_reminders" VALUES ('5c43bb17-3587-42b8-8290-fc72c61e0180', 'ab5143af-cf33-4857-8521-6eedcd9690e3', '二审程序或执行程序跟进提醒', '2026-07-24 22:20:48.448584+08', '如提起上诉，提醒关注二审开庭或书面审理通知，并准备二审陈述。如已申请执行，提醒与执行法官保持沟通，提供财产线索，跟进执行进展。', 'f', NULL, '["\u4e8c\u5ba1\u9636\u6bb5\u7684\u8865\u5145\u610f\u89c1\u6216\u4ee3\u7406\u8bcd\uff08\u9488\u5bf9\u4e00\u5ba1\u4e89\u8bae\u7126\u70b9\u548c\u65b0\u60c5\u51b5\uff09", "\u4e0e\u6267\u884c\u6cd5\u5b98\u7684\u6c9f\u901a\u8bb0\u5f55", "\u65b0\u53d1\u73b0\u7684\u88ab\u544a\u8d22\u4ea7\u7ebf\u7d22\u4fe1\u606f", "\u6536\u6b3e\u8d26\u6237\u4fe1\u606f\uff08\u7528\u4e8e\u63a5\u6536\u6267\u884c\u6b3e\uff09"]', '（二审中）审判长、审判员：针对一审争议焦点，我方补充意见如下...（强调债务事实、法律适用）。恳请二审法院查明事实，依法改判。

（执行沟通中）执行法官您好，我是申请人姚元顺的代理人，想了解一下案件执行进展。我们最近了解到被告可能有一笔收入/某处财产，线索是...，供您参考。我们积极配合法院的一切执行措施。', '2026-03-26 22:20:00.315508+08', '2026-03-26 22:20:00.315508+08');
INSERT INTO "public"."case_reminders" VALUES ('3dc8e16a-e4af-41f7-8dd1-0bb42b151051', '949dc3b9-8bef-416c-89c3-625c664d6ba6', '生效判决履行与执行申请提醒', '2026-08-19 22:23:01.602114+08', '二审判决（或一审判决未上诉）已生效。请关注判决书确定的履行期限。如被告裴润晨在履行期满后仍未主动支付款项，您应在法定的2年申请执行时效内，向一审法院或同级被执行人财产所在地法院申请强制执行。申请前可尝试了解对方财产线索（如银行账户、房产、车辆信息）。', 'f', NULL, '["\u5f3a\u5236\u6267\u884c\u7533\u8bf7\u4e66", "\u751f\u6548\u5224\u51b3\u4e66\u539f\u4ef6\u53ca\u590d\u5370\u4ef6", "\u7533\u8bf7\u4eba\u8eab\u4efd\u8bc1\u660e\u590d\u5370\u4ef6", "\u88ab\u7533\u8bf7\u4eba\u8d22\u4ea7\u7ebf\u7d22\uff08\u5982\u6709\uff0c\u975e\u5fc5\u9700\u4f46\u5f3a\u70c8\u5efa\u8bae\u63d0\u4f9b\uff09", "\u6cd5\u5f8b\u6587\u4e66\u751f\u6548\u8bc1\u660e\uff08\u901a\u5e38\u7531\u4e00\u5ba1\u6cd5\u9662\u51fa\u5177\uff09"]', '执行法官您好，我方申请执行（XXXX）XX民终XX号（或初字）民事判决。判决已生效，但被执行人裴润晨至今未履行判决确定的支付奶茶款及利息的义务，总计XX元。为维护法律权威和申请人合法权益，现根据《民事诉讼法》规定，申请强制执行。这是生效判决书和执行申请书。我们了解到被执行人可能在XX银行有账户（或提供其他线索），请法院依法查询并执行其财产。', '2026-03-22 22:22:05.890817+08', '2026-03-22 22:22:05.890817+08');
INSERT INTO "public"."case_reminders" VALUES ('8234324f-e689-433b-aae6-6961489cf154', 'ab5143af-cf33-4857-8521-6eedcd9690e3', '立案准备与提交提醒', '2026-04-02 22:20:48.448074+08', '提醒原告姚元顺准备并向有管辖权的人民法院（通常是被告住所地或合同履行地法院）提交起诉状及相关证据材料，正式启动诉讼程序。', 'f', NULL, '["\u6c11\u4e8b\u8d77\u8bc9\u72b6\uff08\u660e\u786e\u8bc9\u8bbc\u8bf7\u6c42\uff1a\u8981\u6c42\u88ab\u544a\u88f4\u6da6\u6668\u4ea4\u4ed8100\u676f\u5976\u8336\u6216\u652f\u4ed8\u7b49\u503c\u4ef7\u6b3e\uff09", "\u539f\u544a\u59da\u5143\u987a\u8eab\u4efd\u8bc1\u660e\u590d\u5370\u4ef6", "\u88ab\u544a\u88f4\u6da6\u6668\u8eab\u4efd\u4fe1\u606f\uff08\u59d3\u540d\u3001\u4f4f\u5740\u3001\u8054\u7cfb\u65b9\u5f0f\u7b49\uff09", "\u8bc1\u660e\u503a\u52a1\u5b58\u5728\u7684\u5173\u952e\u8bc1\u636e\uff08\u5982\u4e66\u9762\u627f\u8bfa\u3001\u804a\u5929\u8bb0\u5f55\u3001\u5f55\u97f3\u5f55\u50cf\u3001\u8bc1\u4eba\u8bc1\u8a00\u7b49\uff09", "\u8bc1\u636e\u6750\u6599\u6e05\u5355"]', '法官/立案庭工作人员您好，我方当事人姚元顺因与裴润晨之间的奶茶交付债务纠纷，现依法提起诉讼。这是我们的起诉状和初步证据，证明被告曾承诺提供100杯奶茶但未履行。我方请求法院立案审理，判令被告履行债务或支付相应价款。', '2026-03-26 22:20:00.315508+08', '2026-03-26 22:20:00.315508+08');
INSERT INTO "public"."case_reminders" VALUES ('361ba685-c638-4e35-92a7-038299a09783', 'ab5143af-cf33-4857-8521-6eedcd9690e3', '举证期限与证据交换提醒', '2026-04-25 22:20:48.448584+08', '提醒原告姚元顺注意法院指定的举证期限，并按时提交全部证据副本给法院和被告。同时，关注并查阅被告提交的证据，准备质证意见。', 'f', NULL, '["\u6240\u6709\u8bc1\u636e\u7684\u5b8c\u6574\u526f\u672c\u53ca\u6e05\u5355\uff08\u6574\u7406\u6210\u518c\uff09", "\u9488\u5bf9\u88ab\u544a\u53ef\u80fd\u63d0\u51fa\u7684\u6297\u8fa9\uff08\u5982\u5df2\u5c65\u884c\u3001\u503a\u52a1\u4e0d\u5b58\u5728\u3001\u6761\u4ef6\u672a\u6210\u5c31\u7b49\uff09\u7684\u8865\u5145\u8bc1\u636e\u6216\u53cd\u9a73\u8bc1\u636e", "\u4e66\u9762\u7684\u8bc1\u636e\u8bf4\u660e\u6216\u8d28\u8bc1\u610f\u89c1\u63d0\u7eb2", "\u5411\u6cd5\u9662\u63d0\u4ea4\u8bc1\u636e\u7684\u9001\u8fbe\u56de\u8bc1"]', '审判员/书记员您好，我方已在举证期限内提交了全部证据，证明债务关系清晰。对于被告提交的证据，我方初步质证意见如下：（根据对方证据具体内容陈述，例如：对真实性无异议，但对关联性和证明目的有异议，该证据不能否定其承诺交付的事实...）。我方坚持诉讼请求。', '2026-03-26 22:20:00.315508+08', '2026-03-26 22:20:00.315508+08');
INSERT INTO "public"."case_reminders" VALUES ('8a0e0ab0-1b94-4b1a-9c0c-22359fa3ab66', 'ab5143af-cf33-4857-8521-6eedcd9690e3', '开庭审理准备与出席提醒', '2026-05-25 22:20:48.448584+08', '提醒原告姚元顺或其委托诉讼代理人准时出席庭审。提前梳理案件事实、法律依据和辩论焦点，准备法庭陈述、举证、质证和辩论。', 'f', NULL, '["\u8d77\u8bc9\u72b6\u3001\u8bc1\u636e\u539f\u4ef6\u53ca\u526f\u672c", "\u4ee3\u7406\u8bcd\u6216\u8fa9\u8bba\u63d0\u7eb2\uff08\u91cd\u70b9\u9610\u8ff0\uff1a1.\u503a\u52a1\u6210\u7acb\u7684\u4e8b\u5b9e\u4e0e\u8bc1\u636e\uff1b2.\u88ab\u544a\u672a\u5c65\u884c\u7684\u8fdd\u7ea6\u884c\u4e3a\uff1b3.\u8981\u6c42\u7ee7\u7eed\u5c65\u884c\u6216\u8d54\u507f\u7684\u6cd5\u5f8b\u4f9d\u636e\uff09", "\u76f8\u5173\u6cd5\u5f8b\u6cd5\u89c4\u6761\u6587\uff08\u5982\u300a\u6c11\u6cd5\u5178\u300b\u5408\u540c\u7f16\u5173\u4e8e\u5c65\u884c\u3001\u8fdd\u7ea6\u7684\u89c4\u5b9a\uff09", "\u8eab\u4efd\u8bc1\u660e\u3001\u6388\u6743\u59d4\u6258\u4e66\uff08\u5982\u6709\u4ee3\u7406\u4eba\uff09", "\u6cd5\u5ead\u8bb0\u5f55\u672c\u548c\u7b14"]', '审判长、审判员：原告姚元顺诉被告裴润晨债务纠纷一案，现就本案事实和法律问题陈述如下：首先，通过我方提交的XX证据，可以清晰证明被告于X年X月X日作出了交付100杯奶茶的承诺，该承诺合法有效，构成债务。其次，被告至今未履行，已构成违约。根据《民法典》第五百七十七条等规定，债务人应当继续履行或采取补救措施、赔偿损失。我方诉讼请求明确，证据充分，请求法庭支持我方全部诉求。对于被告的辩解，我方认为...（进行针对性反驳）。', '2026-03-26 22:20:00.315508+08', '2026-03-26 22:20:00.315508+08');
INSERT INTO "public"."case_reminders" VALUES ('f0f06112-edfe-4929-8a31-85dafa10debc', 'ab5143af-cf33-4857-8521-6eedcd9690e3', '一审判决后行动提醒（上诉或申请执行）', '2026-06-24 22:20:48.448584+08', '提醒原告姚元顺查收一审判决书。如胜诉，关注被告是否自动履行；如被告未履行，应在法定期限内（判决生效后两年内）向一审法院申请强制执行。如对判决不服，应在收到判决书之日起十五日内向上一级法院提起上诉。', 'f', NULL, '["\u4e00\u5ba1\u5224\u51b3\u4e66\u539f\u4ef6\u53ca\u590d\u5370\u4ef6", "\u5f3a\u5236\u6267\u884c\u7533\u8bf7\u4e66\uff08\u5982\u80dc\u8bc9\u4e14\u88ab\u544a\u672a\u5c65\u884c\uff09\u6216\u4e0a\u8bc9\u72b6\uff08\u5982\u4e0d\u670d\u5224\u51b3\uff09", "\u7533\u8bf7\u4eba\u8eab\u4efd\u8bc1\u660e", "\u88ab\u544a\u7684\u8d22\u4ea7\u7ebf\u7d22\uff08\u5982\u6709\uff0c\u7528\u4e8e\u6267\u884c\uff09", "\u4e0a\u8bc9\u8d39\uff08\u5982\u9700\u4e0a\u8bc9\uff09"]', '（申请执行时）执行法官您好，我方是（XX）号案件的原告姚元顺。该案判决已生效，判令被告裴润晨向我方交付100杯奶茶或支付等值价款XX元，但被告至今未履行。现依法申请强制执行，这是我们的强制执行申请书和判决书。

（提起上诉时）上诉法院立案庭您好，我方不服（XX法院XX号）一审民事判决，现依法提起上诉。上诉请求是：撤销原判，改判支持我方全部诉讼请求（或发回重审）。上诉理由是：原审认定事实错误/适用法律不当...（具体阐述）。', '2026-03-26 22:20:00.315508+08', '2026-03-26 22:20:00.315508+08');
INSERT INTO "public"."case_reminders" VALUES ('21694773-c1dc-49b5-94f2-a59e3dc6d629', '78813e0b-40b3-4514-9ca9-be44d6e76a45', '立案准备与起诉提醒', '2026-04-08 14:55:35.845945+08', '请务必在诉讼时效内（通常为三年，自付款期限届满之日起算）启动诉讼程序。建议立即着手准备起诉材料，前往有管辖权的人民法院（通常是被告住所地或合同履行地法院）立案。', 'f', NULL, '["\u6c11\u4e8b\u8d77\u8bc9\u72b6\uff08\u539f\u4ef6\uff0c\u6309\u88ab\u544a\u4eba\u6570+1\u4efd\u51c6\u5907\uff09", "\u539f\u544a\u5b59\u67d0\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6", "\u88ab\u544a\u5434\u67d0\u7684\u8eab\u4efd\u4fe1\u606f\uff08\u5982\u8eab\u4efd\u8bc1\u53f7\u3001\u4f4f\u5740\uff0c\u5c3d\u53ef\u80fd\u51c6\u786e\uff09", "\u8bc1\u660e\u52b3\u52a1\u5408\u540c\u5173\u7cfb\u53ca\u62a5\u916c\u7ea6\u5b9a\u7684\u8bc1\u636e\uff08\u5982\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u3001\u5f55\u97f3\u3001\u4e66\u9762\u534f\u8bae\u7b49\uff09", "\u8bc1\u660e\u539f\u544a\u5df2\u5b8c\u6210\u5de5\u4f5c\u7684\u8bc1\u636e\uff08\u5982\u5b8c\u5de5\u7167\u7247\u3001\u89c6\u9891\u3001\u88ab\u544a\u786e\u8ba4\u7684\u9a8c\u6536\u8bb0\u5f55\u7b49\uff09", "\u8bc1\u660e\u4ed8\u6b3e\u671f\u9650\u5df2\u5c4a\u6ee1\u53ca\u88ab\u544a\u8fdd\u7ea6\u7684\u8bc1\u636e\uff08\u5982\u7ea6\u5b9a\u7684\u4ed8\u6b3e\u65e5\u671f\u8bc1\u660e\u3001\u50ac\u544a\u51fd\u53ca\u9001\u8fbe\u51ed\u8bc1\u3001\u50ac\u6536\u5f55\u97f3\u7b49\uff09", "\u8ba1\u7b97\u62d6\u6b20\u62a5\u916c\u53ca\u903e\u671f\u635f\u5931\uff08\u53ef\u53c2\u7167\u540c\u671f\u8d37\u6b3e\u5e02\u573a\u62a5\u4ef7\u5229\u7387LPR\u8ba1\u7b97\uff09\u7684\u8be6\u7ec6\u6e05\u5355"]', '法官/立案庭工作人员您好，我（孙某）因劳务报酬纠纷起诉吴某。我们已经约定了明确的报酬和付款时间，我已完成全部工作，但吴某至今未付。这是我们的起诉状和证据材料，请审查立案。本案事实清楚、证据充分，被告违约事实明确。', '2026-04-01 14:54:47.997084+08', '2026-04-01 14:54:47.997084+08');
INSERT INTO "public"."case_reminders" VALUES ('86b6ccb6-77b8-4532-aefb-310f2c221375', '78813e0b-40b3-4514-9ca9-be44d6e76a45', '举证期限与证据交换提醒', '2026-05-01 14:55:35.846786+08', '法院立案并送达后，会指定举证期限（通常为15-30天）。请密切关注法院送达的《举证通知书》，务必在举证期限届满前提交全部证据的副本给法院，并准备好在证据交换时对证据进行说明。逾期举证可能面临证据不被采纳的风险。', 'f', NULL, '["\u5df2\u5411\u6cd5\u9662\u63d0\u4ea4\u7684\u6240\u6709\u8bc1\u636e\u6750\u6599\u7684\u6e05\u6670\u590d\u5370\u4ef6/\u626b\u63cf\u4ef6\uff08\u6309\u88ab\u544a\u4eba\u6570\u51c6\u5907\u526f\u672c\uff09", "\u8bc1\u636e\u76ee\u5f55\u6e05\u5355\uff08\u5217\u660e\u8bc1\u636e\u540d\u79f0\u3001\u6765\u6e90\u3001\u8bc1\u660e\u76ee\u7684\uff09", "\u9488\u5bf9\u88ab\u544a\u53ef\u80fd\u63d0\u51fa\u7684\u6297\u8fa9\uff08\u5982\u8d28\u91cf\u4e0d\u5408\u683c\u3001\u5df2\u4ed8\u6b3e\u7b49\uff09\u51c6\u5907\u7684\u8865\u5145\u53cd\u9a73\u8bc1\u636e\uff08\u5982\u6709\uff09", "\u8ba1\u7b97\u903e\u671f\u4ed8\u6b3e\u635f\u5931\u7684\u8be6\u7ec6\u4f9d\u636e\u548c\u8ba1\u7b97\u8fc7\u7a0b\u8bf4\u660e"]', '审判员/对方当事人，我方提交的证据组旨在证明：1. 原被告间存在合法劳务合同关系（证据X）；2. 原告已依约完成合格工作（证据Y）；3. 付款条件已成就且被告经催告后违约（证据Z）。关于损失计算，是依据《民法典》及相关司法解释，按LPR标准计算至实际付清之日。被告如对工作量或质量有异议，应承担举证责任。', '2026-04-01 14:54:47.997084+08', '2026-04-01 14:54:47.997084+08');
INSERT INTO "public"."case_reminders" VALUES ('05096431-8368-4cde-bc20-1c41cdd74382', '78813e0b-40b3-4514-9ca9-be44d6e76a45', '开庭前准备与庭审提醒', '2026-06-15 14:55:35.846786+08', '法院已排期开庭。请提前熟悉庭审流程，梳理案件事实脉络和法律依据，预判对方辩论观点并准备应对。准时出庭，如无正当理由拒不到庭，可能按撤诉处理。', 'f', NULL, '["\u5f00\u5ead\u4f20\u7968\u3001\u8eab\u4efd\u8bc1\u539f\u4ef6", "\u8d77\u8bc9\u72b6\u3001\u8bc1\u636e\u539f\u4ef6\u53ca\u6240\u6709\u5df2\u63d0\u4ea4\u6750\u6599\u7684\u526f\u672c", "\u4e66\u9762\u4ee3\u7406\u610f\u89c1\u6216\u7b54\u8fa9\u8981\u70b9\u63d0\u7eb2", "\u5173\u952e\u4e8b\u5b9e\u7684\u65f6\u95f4\u7ebf\u56fe\u8868", "\u76f8\u5173\u6cd5\u5f8b\u6761\u6587\u6458\u5f55\uff08\u300a\u6c11\u6cd5\u5178\u300b\u7b2c579\u6761\u3001\u7b2c577\u6761\u7b49\uff09", "\u8ba1\u7b97\u5668\uff08\u7528\u4e8e\u5f53\u5ead\u6838\u5bf9\u91d1\u989d\uff09"]', '审判长、审判员：原告孙某诉被告吴某劳务合同纠纷一案，事实清楚。核心在于：合同已履行完毕，付款条件已成就。被告无正当理由拒付，构成根本违约。我方诉求有明确合同依据和法律依据。请求法庭支持原告全部诉讼请求，以维护劳动者合法权益和市场诚信。针对被告可能提出的‘质量有问题’等抗辩，我方已完成举证，且被告在催告期间从未提出，依法不应采纳。', '2026-04-01 14:54:47.997084+08', '2026-04-01 14:54:47.997084+08');
INSERT INTO "public"."case_reminders" VALUES ('9c4701cf-668a-43d0-baa8-9816b1d02258', '78813e0b-40b3-4514-9ca9-be44d6e76a45', '一审判决后上诉期限提醒', '2026-07-15 14:55:35.846786+08', '收到一审判决书后，请立即仔细阅读。如对判决结果不服（包括全部或部分不支持诉求），务必注意上诉期限为15天，自判决书送达之日起算。逾期未上诉，一审判决即发生法律效力。决定上诉需谨慎评估胜诉可能及成本。', 'f', NULL, '["\u4e00\u5ba1\u5224\u51b3\u4e66\u539f\u4ef6\u53ca\u590d\u5370\u4ef6", "\u4e0a\u8bc9\u72b6\uff08\u9700\u660e\u786e\u4e0a\u8bc9\u8bf7\u6c42\u3001\u4e8b\u5b9e\u4e0e\u7406\u7531\uff0c\u6309\u5bf9\u65b9\u5f53\u4e8b\u4eba\u4eba\u6570+1\u4efd\u51c6\u5907\uff09", "\u65b0\u53d1\u73b0\u7684\u3001\u5bf9\u6848\u4ef6\u6709\u91cd\u5927\u5f71\u54cd\u7684\u8bc1\u636e\uff08\u5982\u6709\uff09", "\u4e00\u5ba1\u5ead\u5ba1\u7b14\u5f55\u4e2d\u6709\u5229\u4e8e\u5df1\u65b9\u7684\u90e8\u5206\uff08\u5982\u6709\u9700\u8981\uff09"]', '（如决定上诉）上诉人（原审原告）孙某因不服XX法院（案号）民事判决书第X项，现提起上诉。上诉理由如下：一审法院在认定……事实时存在错误/适用法律不当，……（具体指出）。故请求二审法院依法撤销原判第X项，改判支持上诉人一审全部诉讼请求。（上诉状中需详细、专业地论述）', '2026-04-01 14:54:47.997084+08', '2026-04-01 14:54:47.997084+08');
INSERT INTO "public"."case_reminders" VALUES ('fa6f6e20-b75d-4539-9740-ff07876c3ebe', '78813e0b-40b3-4514-9ca9-be44d6e76a45', '生效判决履行与执行申请提醒', '2026-08-29 14:55:35.846786+08', '如果获得胜诉生效判决（包括一审后未上诉或二审终审判决），而被告吴某在判决规定的履行期内仍未支付款项，请务必在法定的申请执行时效期间（两年）内，向一审法院或同级被执行人财产所在地法院申请强制执行。', 'f', NULL, '["\u5f3a\u5236\u6267\u884c\u7533\u8bf7\u4e66\uff08\u539f\u4ef6\uff09", "\u751f\u6548\u5224\u51b3\u4e66\u539f\u4ef6\u53ca\u590d\u5370\u4ef6", "\u5224\u51b3\u751f\u6548\u8bc1\u660e\uff08\u53ef\u5411\u539f\u5ba1\u6cd5\u9662\u7533\u8bf7\u5f00\u5177\uff09", "\u88ab\u544a\u5434\u67d0\u7684\u8d22\u4ea7\u7ebf\u7d22\uff08\u5982\u94f6\u884c\u8d26\u6237\u3001\u623f\u4ea7\u3001\u8f66\u8f86\u4fe1\u606f\u7b49\uff0c\u5c3d\u53ef\u80fd\u63d0\u4f9b\uff09", "\u7533\u8bf7\u4eba\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6"]', '执行法官您好，我（孙某）与吴某劳务合同纠纷一案，生效判决（文号）已确定吴某应向我支付报酬及损失共计XX元。履行期已于X年X月X日届满，吴某至今未履行。现申请强制执行。我们了解到吴某可能的财产线索有……（如有），请法院依法查控其财产，维护法律文书权威和我的合法权益。', '2026-04-01 14:54:47.997084+08', '2026-04-01 14:54:47.997084+08');

-- ----------------------------
-- Table structure for cases
-- ----------------------------
DROP TABLE IF EXISTS "public"."cases";
CREATE TABLE "public"."cases" (
  "id" varchar COLLATE "pg_catalog"."default" NOT NULL,
  "title" varchar COLLATE "pg_catalog"."default" NOT NULL,
  "case_type" varchar COLLATE "pg_catalog"."default" NOT NULL,
  "case_description" text COLLATE "pg_catalog"."default" NOT NULL,
  "plaintiff_claims" json,
  "defendant_defenses" json,
  "created_at" timestamptz(6) DEFAULT now(),
  "updated_at" timestamptz(6) DEFAULT now()
)
;

