INSERT INTO "public"."debate_turns" VALUES ('1a9e080f-e547-440a-9173-24e1c3516885', '10af80a4-bd82-4c32-8939-b4edecd41a20', 'opening', 'plaintiff', '代理律师', '**开庭陈述**

