INSERT INTO "public"."dispute_infos" VALUES ('949dc3b9-8bef-416c-89c3-625c664d6ba6', '裴润晨拖欠奶茶款项纠纷', '[{"name": "\u88f4\u6da6\u6668", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}, {"name": "\u4fe1\u606f\u7f3a\u5931", "role": "\u539f\u544a\uff08\u5976\u8336\u63d0\u4f9b\u65b9\uff09", "contact": "\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}]', '信息缺失，需补充具体日期', '被告裴润晨从原告处获取奶茶，但未支付相应款项。根据现有信息，双方可能就奶茶的购买或赠与存在约定，但裴润晨未履行付款义务，构成违约或不当得利。', '原告要求裴润晨支付拖欠的奶茶款项及可能产生的合理费用（如利息、催收费用等）。', '[{"name": "\u8d2d\u4e70/\u8ba2\u5355\u8bb0\u5f55", "type": "\u4e66\u8bc1\u3001\u7535\u5b50\u6570\u636e", "description": "\u80fd\u8bc1\u660e\u5976\u8336\u79cd\u7c7b\u3001\u6570\u91cf\u3001\u5355\u4ef7\u3001\u603b\u91d1\u989d\u53ca\u4e0b\u5355\u65f6\u95f4\u7684\u8bb0\u5f55\uff08\u5982\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u8f6c\u8d26\u622a\u56fe\u3001\u8ba2\u5355\u622a\u56fe\u3001\u6536\u636e\u7b49\uff09\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e\u3001\u89c6\u542c\u8d44\u6599", "description": "\u80fd\u8bc1\u660e\u53cc\u65b9\u5c31\u8d2d\u4e70\u5976\u8336\u8fbe\u6210\u5408\u610f\uff0c\u4ee5\u53ca\u539f\u544a\u50ac\u6b3e\u3001\u88ab\u544a\u627f\u8ba4\u6b20\u6b3e\u6216\u627f\u8bfa\u8fd8\u6b3e\u7684\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\uff09\u3001\u90ae\u4ef6\u6216\u901a\u8bdd\u5f55\u97f3\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u73b0\u573a\u76ee\u51fb\u4ea4\u6613\u8fc7\u7a0b\u6216\u77e5\u6089\u6b20\u6b3e\u4e8b\u5b9e\u7684\u7b2c\u4e09\u65b9\u8bc1\u4eba\u9648\u8ff0\u3002"}, {"name": "\u652f\u4ed8\u51ed\u8bc1", "type": "\u4e66\u8bc1\u3001\u7535\u5b50\u6570\u636e", "description": "\u82e5\u66fe\u90e8\u5206\u652f\u4ed8\uff0c\u9700\u63d0\u4f9b\u76f8\u5e94\u7684\u8f6c\u8d26\u8bb0\u5f55\u6216\u6536\u6761\u3002"}]', 'text', '裴润晨欠奶茶不还', '2026-03-22 22:17:47.971848+08', '2026-03-22 22:17:47.971848+08');
INSERT INTO "public"."dispute_infos" VALUES ('be9c5de9-8685-4227-be5f-bddad876b86b', '房屋租赁合同纠纷', '[{"name": "\u5f20\u4e09", "role": "\u539f\u544a", "contact": "13800138000"}, {"name": "\u674e\u56db", "role": "\u88ab\u544a", "contact": "13900139000"}]', '2024年6月15日', '原告张三与被告李四于2024年6月15日签订了一份为期一年的房屋租赁合同。合同约定，张三将位于某市某区某路某号的一套房屋出租给李四居住，月租金为人民币3000元，押一付三。李四在支付了首期租金及押金后入住。但在合同履行期间，李四自2024年9月起开始拖欠租金，经张三多次催告，李四至今仍未支付2024年9月至11月的租金共计人民币9000元，且拒绝搬离房屋。张三认为李四的行为已构成根本违约，严重损害了其合法权益。', '1. 请求判令解除原告张三与被告李四于2024年6月15日签订的《房屋租赁合同》；2. 请求判令被告李四立即腾退并返还涉案房屋；3. 请求判令被告李四支付拖欠的2024年9月至11月租金共计人民币9000元及逾期付款利息（以9000元为基数，按全国银行间同业拆借中心公布的贷款市场报价利率，自2024年9月16日起计算至实际付清之日止）；4. 请求判令被告李四承担本案全部诉讼费用。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5f20\u4e09\u4e0e\u88ab\u544a\u674e\u56db\u4e4b\u95f4\u5b58\u5728\u5408\u6cd5\u6709\u6548\u7684\u623f\u5c4b\u79df\u8d41\u5408\u540c\u5173\u7cfb\uff0c\u7ea6\u5b9a\u4e86\u79df\u8d41\u671f\u9650\u3001\u79df\u91d1\u6807\u51c6\u3001\u652f\u4ed8\u65b9\u5f0f\u3001\u8fdd\u7ea6\u8d23\u4efb\u7b49\u6838\u5fc3\u6761\u6b3e\u3002"}, {"name": "\u79df\u91d1\u652f\u4ed8\u8bb0\u5f55\uff08\u94f6\u884c\u8f6c\u8d26\u51ed\u8bc1/\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u622a\u56fe\uff09", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u88ab\u544a\u674e\u56db\u5df2\u652f\u4ed8\u9996\u671f\u79df\u91d1\u53ca\u62bc\u91d1\uff0c\u4ee5\u53ca\u81ea2024\u5e749\u6708\u8d77\u672a\u518d\u652f\u4ed8\u79df\u91d1\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u50ac\u6536\u79df\u91d1\u7684\u901a\u77e5\uff08\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u8bb0\u5f55\u3001\u5f8b\u5e08\u51fd\u53ca\u90ae\u5bc4\u51ed\u8bc1\uff09", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5f20\u4e09\u5df2\u5c31\u62d6\u6b20\u79df\u91d1\u4e8b\u5b9c\u5411\u88ab\u544a\u674e\u56db\u8fdb\u884c\u8fc7\u6709\u6548\u50ac\u544a\u3002"}, {"name": "\u623f\u5c4b\u4ea7\u6743\u8bc1\u660e\uff08\u623f\u4ea7\u8bc1\u590d\u5370\u4ef6\uff09", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5f20\u4e09\u662f\u6d89\u6848\u623f\u5c4b\u7684\u5408\u6cd5\u6240\u6709\u6743\u4eba\u6216\u6709\u6743\u51fa\u79df\u4eba\u3002"}, {"name": "\u88ab\u544a\u8eab\u4efd\u4fe1\u606f", "type": "\u4e66\u8bc1", "description": "\u88ab\u544a\u674e\u56db\u7684\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6\u6216\u6237\u7c4d\u4fe1\u606f\uff0c\u7528\u4e8e\u786e\u8ba4\u88ab\u544a\u7684\u8bc9\u8bbc\u4e3b\u4f53\u8d44\u683c\u3002"}]', 'text', '???????10??,??2024?6?15???,??????????', '2026-03-23 12:56:35.004923+08', '2026-03-23 12:56:35.004923+08');
INSERT INTO "public"."dispute_infos" VALUES ('ea8198f3-d30f-4779-806e-7cbfd406bad0', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\uff08\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u586b\u5199\uff0c\u5982\uff1a\u7535\u8bdd\u3001\u5730\u5740\u7b49\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\uff08\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u586b\u5199\uff0c\u5982\uff1a\u7535\u8bdd\u3001\u5730\u5740\u7b49\uff09"}]', '2024年6月15日（借款到期日）', '张三向李四借款人民币10万元，双方约定于2024年6月15日偿还。到期后，张三未按约定履行还款义务，构成违约。', '原告李四要求被告张三立即偿还借款本金10万元，并支付自2024年6月16日起至实际清偿之日止的逾期利息（可按合同约定或法律规定计算）。', '[{"name": "\u501f\u6761/\u501f\u6b3e\u5408\u540c", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u51fa\u501f\u4eba\u674e\u56db\u3001\u501f\u6b3e\u4eba\u5f20\u4e09\u3001\u501f\u6b3e\u91d1\u989d10\u4e07\u5143\u3001\u7ea6\u5b9a\u8fd8\u6b3e\u65e5\u671f2024\u5e746\u670815\u65e5\u7b49\u5173\u952e\u6761\u6b3e\u7684\u4e66\u9762\u6587\u4ef6\u3002"}, {"name": "\u8f6c\u8d26\u51ed\u8bc1", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u3001\u5fae\u4fe1\u3001\u652f\u4ed8\u5b9d\u7b49\u65b9\u5f0f\u5411\u5f20\u4e09\u5b9e\u9645\u652f\u4ed810\u4e07\u5143\u501f\u6b3e\u7684\u8bb0\u5f55\u3002"}, {"name": "\u50ac\u6536\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599/\u4e66\u8bc1", "description": "\u674e\u56db\u5728\u501f\u6b3e\u5230\u671f\u540e\u901a\u8fc7\u5fae\u4fe1\u3001\u77ed\u4fe1\u3001\u90ae\u4ef6\u3001\u7535\u8bdd\u5f55\u97f3\u6216\u4e66\u9762\u51fd\u4ef6\u7b49\u65b9\u5f0f\u5411\u5f20\u4e09\u4e3b\u5f20\u6743\u5229\u3001\u8fdb\u884c\u50ac\u6536\u7684\u8bc1\u660e\u3002"}, {"name": "\u5f53\u4e8b\u4eba\u8eab\u4efd\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u674e\u56db\u548c\u5f20\u4e09\u7684\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6\u6216\u6237\u7c4d\u8bc1\u660e\uff0c\u7528\u4e8e\u786e\u8ba4\u8bc9\u8bbc\u4e3b\u4f53\u8d44\u683c\u3002"}]', 'text', '张三向李四借款10万元，约定2024年6月15日还款，但到期后张三未还款。', '2026-03-23 13:20:03.149271+08', '2026-03-23 13:20:03.149271+08');
INSERT INTO "public"."dispute_infos" VALUES ('7c1efb39-13d3-4eea-adec-26456e7e43fd', '房屋租赁押金返还纠纷', '[{"name": "\u5f20\u4f1f", "role": "\u539f\u544a\uff08\u627f\u79df\u4eba\uff09", "contact": "138****1234"}, {"name": "\u674e\u82b3", "role": "\u88ab\u544a\uff08\u51fa\u79df\u4eba\uff09", "contact": "139****5678"}]', '2023年10月15日至2024年4月15日（租赁期间），2024年4月20日（退租交接日）', '原告张伟于2023年10月15日租赁被告李芳位于XX市XX区XX小区X栋X单元XXX室的房屋，租期半年，押金为人民币8000元。租赁合同约定，租期届满且房屋设施完好、无欠费的情况下，押金应于退租后7个工作日内全额退还。2024年4月15日租期届满，双方于4月20日办理退租交接。被告在查验后，口头表示房屋卫生状况不佳、客厅墙壁有一处轻微划痕（约5厘米），并据此单方面决定扣除全部押金8000元作为“清洁费与维修费”，且未提供任何费用票据或维修报价单。原告认为该划痕属于正常使用损耗，且其已进行过基础保洁，被告提出的扣款金额远高于实际可能产生的费用，且程序不合规，属于无故克扣押金。双方多次协商未果。', '原告张伟诉求：1. 判令被告李芳立即返还房屋租赁押金人民币8000元整；2. 判令被告支付自应退还之日至实际支付之日的资金占用利息（可按LPR计算）；3. 本案诉讼费用由被告承担。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u53cc\u65b9\u8eab\u4efd\u4fe1\u606f\u3001\u623f\u5c4b\u5730\u5740\u3001\u79df\u671f\uff082023.10.15-2024.4.15\uff09\u3001\u79df\u91d1\u3001\u62bc\u91d1\u91d1\u989d\uff088000\u5143\uff09\u53ca\u9000\u8fd8\u6761\u4ef6\u7b49\u5173\u952e\u6761\u6b3e\u3002"}, {"name": "\u62bc\u91d1\u652f\u4ed8\u51ed\u8bc1\uff08\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55/\u5fae\u4fe1\u652f\u4ed8\u622a\u56fe\uff09", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5f20\u4f1f\u5df2\u5411\u88ab\u544a\u674e\u82b3\u652f\u4ed8\u62bc\u91d18000\u5143\u3002"}, {"name": "\u9000\u79df\u4ea4\u63a5\u65f6\u7684\u6c9f\u901a\u5f55\u97f3/\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55", "type": "\u89c6\u542c\u8d44\u6599/\u7535\u5b50\u6570\u636e", "description": "\u5185\u5bb9\u5305\u542b\u88ab\u544a\u4ee5\u5899\u58c1\u5212\u75d5\u548c\u536b\u751f\u95ee\u9898\u4e3a\u7531\u62d2\u7edd\u9000\u8fd8\u62bc\u91d1\u7684\u9648\u8ff0\uff0c\u4ee5\u53ca\u53cc\u65b9\u5c31\u8be5\u95ee\u9898\u7684\u4ea4\u6d89\u8fc7\u7a0b\u3002"}, {"name": "\u623f\u5c4b\u9000\u79df\u65f6\u72b6\u6001\u7684\u7167\u7247/\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u9000\u79df\u65f6\u623f\u5c4b\u7684\u6574\u4f53\u72b6\u51b5\u3001\u6240\u8c13\u7684\u5899\u58c1\u5212\u75d5\u7a0b\u5ea6\u53ca\u536b\u751f\u72b6\u51b5\uff0c\u7528\u4ee5\u5224\u65ad\u662f\u5426\u6784\u6210\u4e25\u91cd\u635f\u574f\u6216\u8d85\u51fa\u6b63\u5e38\u635f\u8017\u3002"}, {"name": "\u50ac\u544a\u9000\u8fd8\u62bc\u91d1\u7684\u4e66\u9762\u901a\u77e5\u6216\u804a\u5929\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u539f\u544a\u66fe\u5411\u88ab\u544a\u6b63\u5f0f\u4e3b\u5f20\u6743\u5229\uff0c\u4ee5\u53ca\u88ab\u544a\u7684\u660e\u786e\u62d2\u7edd\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00\uff08\u5982\u90bb\u5c45\u3001\u4e2d\u4ecb\uff09", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u53ef\u80fd\u8bc1\u660e\u623f\u5c4b\u65e5\u5e38\u4f7f\u7528\u72b6\u51b5\u6216\u9000\u79df\u4ea4\u63a5\u65f6\u7684\u73b0\u573a\u60c5\u51b5\u3002"}, {"name": "\u5e02\u573a\u6e05\u6d01\u3001\u5c0f\u9762\u79ef\u5899\u9762\u4fee\u8865\u7684\u62a5\u4ef7\u5355\u6216\u666e\u904d\u8d39\u7528\u6807\u51c6", "type": "\u4e66\u8bc1", "description": "\u7528\u4ee5\u53cd\u9a73\u88ab\u544a\u6263\u9664\u5168\u90e8\u62bc\u91d1\u91d1\u989d\u7684\u5408\u7406\u6027\uff0c\u8bc1\u660e\u5176\u4e3b\u5f20\u7684\u8d39\u7528\u8fdc\u9ad8\u4e8e\u5b9e\u9645\u6240\u9700\u3002"}]', 'audio', '[音频文件: 测试.mp3]', '2026-03-23 13:20:32.062393+08', '2026-03-23 13:20:32.062393+08');
INSERT INTO "public"."dispute_infos" VALUES ('e4a37fce-8523-4c2a-8a32-9d344cd4f9f0', '房屋租赁合同违约纠纷', '[{"name": "\u5f20\u4f1f", "role": "\u539f\u544a\uff08\u627f\u79df\u4eba\uff09", "contact": "138****1234"}, {"name": "\u674e\u82b3", "role": "\u88ab\u544a\uff08\u51fa\u79df\u4eba\uff09", "contact": "139****5678"}]', '2023年10月15日', '原告张伟与被告李芳于2023年8月1日签订《房屋租赁合同》，约定租赁位于XX市XX区XX路XX号XX室房屋，租期一年，月租金5000元，押一付三。合同约定出租人应保证房屋设施完好、可正常使用。原告于2023年10月15日入住后发现：1. 卧室空调无法制冷/制热，经维修人员检测系压缩机故障；2. 卫生间水管存在严重漏水，导致墙面渗水。原告立即通知被告要求维修，被告以“房屋交付时完好”为由拒绝承担维修责任及费用。原告多次沟通无果，被告甚至表示“不愿租可以退租，但押金不退”。', '1. 请求判令被告立即对故障空调及漏水水管进行维修，恢复房屋正常使用状态；2. 请求判令被告赔偿因房屋质量问题导致原告无法正常居住所产生的酒店住宿费1500元；3. 请求判令被告承担本案诉讼费用。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u3001\u623f\u5c4b\u5730\u5740\u3001\u79df\u671f\u3001\u79df\u91d1\u3001\u7ef4\u4fee\u8d23\u4efb\u6761\u6b3e\uff08\u7b2c5\u6761\u7ea6\u5b9a\u51fa\u79df\u4eba\u8d1f\u8d23\u623f\u5c4b\u4e3b\u4f53\u7ed3\u6784\u53ca\u4e3b\u8981\u8bbe\u65bd\u8bbe\u5907\u7684\u7ef4\u4fee\uff09\u3002"}, {"name": "\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u622a\u56fe", "type": "\u7535\u5b50\u6570\u636e", "description": "2023\u5e7410\u670815\u65e5\u81f311\u67081\u65e5\u671f\u95f4\uff0c\u539f\u544a\u5411\u88ab\u544a\u53cd\u6620\u7a7a\u8c03\u6545\u969c\u3001\u6f0f\u6c34\u95ee\u9898\u53ca\u88ab\u544a\u62d2\u7edd\u7ef4\u4fee\u7684\u6c9f\u901a\u8bb0\u5f55\u3002"}, {"name": "\u7a7a\u8c03\u7ef4\u4fee\u68c0\u6d4b\u5355", "type": "\u4e66\u8bc1", "description": "\u7531XX\u7535\u5668\u7ef4\u4fee\u516c\u53f8\u51fa\u5177\uff0c\u8bc1\u660e\u7a7a\u8c03\u538b\u7f29\u673a\u6545\u969c\uff0c\u4e14\u5c5e\u8001\u65e7\u635f\u574f\uff0c\u975e\u4eba\u4e3a\u9020\u6210\u3002"}, {"name": "\u6f0f\u6c34\u73b0\u573a\u7167\u7247/\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u663e\u793a\u536b\u751f\u95f4\u6c34\u7ba1\u6f0f\u6c34\u4f4d\u7f6e\u3001\u5899\u9762\u6e17\u6c34\u3001\u6c34\u6e0d\u75d5\u8ff9\u3002"}, {"name": "\u9152\u5e97\u4f4f\u5bbf\u53d1\u7968", "type": "\u4e66\u8bc1", "description": "\u56e0\u623f\u5c4b\u65e0\u6cd5\u5c45\u4f4f\uff0c\u539f\u544a\u6682\u4f4f\u9152\u5e975\u5929\uff0c\u8d39\u75281500\u5143\u3002"}, {"name": "\u62bc\u91d1\u652f\u4ed8\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\uff0c\u8bc1\u660e\u539f\u544a\u5df2\u652f\u4ed8\u62bc\u91d15000\u5143\u3002"}]', 'image', '[图片文件: 图片.png]', '2026-03-23 13:20:54.161044+08', '2026-03-23 13:20:54.161044+08');
INSERT INTO "public"."dispute_infos" VALUES ('28449667-7a01-42b0-af39-1114e22821a9', '邻里噪音扰民纠纷', '[{"name": "\u674e\u534e", "role": "\u539f\u544a", "contact": "138****1234\uff08\u89c6\u9891\u4e2d\u95e8\u724c\u53f7\u65c1\u4fbf\u5229\u8d34\u663e\u793a\uff09"}, {"name": "\u738b\u5f3a", "role": "\u88ab\u544a", "contact": "\u672a\u77e5\uff08\u9700\u8fdb\u4e00\u6b65\u6838\u5b9e\uff09"}]', '2023年10月15日至11月20日期间，每日晚10点至凌晨2点左右', '原告李华（302室住户）与被告王强（402室住户）为上下楼邻居关系。根据视频中李华提供的手机录制片段显示，自10月中旬以来，402室夜间频繁传出重物掉落、拖动家具、多人高声喧哗及持续低频振动声（疑似家用健身器材）。视频中包含两段关键内容：1）11月5日凌晨1点15分的录音，清晰记录持续敲击声及男性喊叫声；2）11月18日晚11点30分，李华上楼交涉的对话录像，王强承认当晚有朋友聚会，但辩称“正常生活噪音”，双方发生口角。李华称已多次通过物业沟通未果，严重影响其睡眠与身心健康。', '1. 要求王强立即停止夜间（晚10点至早6点）制造超过《社会生活环境噪声排放标准》的噪音；2. 要求王强书面赔礼道歉；3. 赔偿精神损害抚慰金人民币2000元；4. 承担本案诉讼费用。', '[{"name": "\u591c\u95f4\u566a\u97f3\u5f55\u97f3\u5f55\u50cf\u5408\u96c6", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u624b\u673a\u5f55\u5236\u4e8e2023\u5e7411\u6708\u671f\u95f4\uff0c\u51717\u6bb5\u89c6\u9891\u300112\u6bb5\u97f3\u9891\uff0c\u6e05\u6670\u663e\u793a\u65f6\u95f4\u6233\u3001\u566a\u97f3\u5206\u8d1d\u503c\uff08APP\u663e\u793a\uff09\u53ca\u73af\u5883\u7279\u5f81\uff0c\u80fd\u5173\u8054\u58f0\u6e90\u65b9\u5411\u3002"}, {"name": "\u4ea4\u6d89\u8fc7\u7a0b\u5f55\u50cf", "type": "\u89c6\u542c\u8d44\u6599", "description": "2023\u5e7411\u670818\u65e5\u4e0a\u95e8\u4ea4\u6d89\u7684\u5168\u7a0b\u5f55\u50cf\uff0c\u8bb0\u5f55\u53cc\u65b9\u5bf9\u8bdd\u5185\u5bb9\u53ca\u738b\u5f3a\u627f\u8ba4\u805a\u4f1a\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u7269\u4e1a\u6295\u8bc9\u8bb0\u5f55", "type": "\u4e66\u8bc1", "description": "\u5c0f\u533a\u7269\u4e1a\u4e2d\u5fc3\u51fa\u5177\u76843\u6b21\u4e66\u9762\u6295\u8bc9\u56de\u6267\u5355\uff082023\u5e7410\u670820\u65e5\u300111\u67088\u65e5\u300111\u670815\u65e5\uff09\u3002"}, {"name": "\u533b\u9662\u8bca\u65ad\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u674e\u534e\u4e8e2023\u5e7411\u670825\u65e5\u5728\u5e02\u4eba\u6c11\u533b\u9662\u5c31\u8bca\u7684\u75c5\u4f8b\uff0c\u663e\u793a\u201c\u795e\u7ecf\u8870\u5f31\u3001\u7761\u7720\u969c\u788d\u201d\uff0c\u533b\u751f\u5efa\u8bae\u201c\u6539\u5584\u4f11\u606f\u73af\u5883\u201d\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u540c\u697c\u5c42301\u5ba4\u4f4f\u6237\u5f20\u5973\u58eb\u53ef\u4f5c\u8bc1\uff0c\u8868\u793a\u540c\u6837\u53d7\u5230\u566a\u97f3\u5e72\u6270\uff08\u89c6\u9891\u4e2d\u63d0\u53ca\uff09\u3002"}]', 'video', '[视频文件: 测试视频.mp4]', '2026-03-23 13:21:17.903863+08', '2026-03-23 13:21:17.903863+08');
INSERT INTO "public"."dispute_infos" VALUES ('fa5d2ffd-5f08-41e2-9b49-db52d81e85d4', '裴润晨拖欠姚元顺100杯奶茶债务纠纷', '[{"name": "\u59da\u5143\u987a", "role": "\u539f\u544a", "contact": "\u5f85\u8865\u5145"}, {"name": "\u88f4\u6da6\u6668", "role": "\u88ab\u544a", "contact": "\u5f85\u8865\u5145"}]', '待补充具体时间', '裴润晨向姚元顺购买或承诺支付100杯奶茶，但未履行支付义务，构成债务违约。', '姚元顺要求裴润晨履行支付100杯奶茶的债务或等值货币赔偿。', '[{"name": "\u6b20\u6b3e\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u8bb0\u8f7d\u88f4\u6da6\u6668\u6b20\u59da\u5143\u987a100\u676f\u5976\u8336\u7684\u4e66\u9762\u534f\u8bae\u3001\u501f\u6761\u3001\u804a\u5929\u8bb0\u5f55\u6216\u5f55\u97f3\u5f55\u50cf\u7b49\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599", "description": "\u53cc\u65b9\u5c31\u5976\u8336\u503a\u52a1\u8fdb\u884c\u6c9f\u901a\u7684\u5fae\u4fe1\u3001\u77ed\u4fe1\u3001\u90ae\u4ef6\u6216\u901a\u8bdd\u5f55\u97f3\u7b49\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u4e86\u89e3\u8be5\u503a\u52a1\u5173\u7cfb\u7684\u7b2c\u4e09\u65b9\u8bc1\u4eba\u9648\u8ff0\u3002"}, {"name": "\u5976\u8336\u5e02\u573a\u4ef7\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e100\u676f\u5976\u8336\u5f53\u5730\u5e02\u573a\u4ef7\u503c\u7684\u5355\u636e\u3001\u62a5\u4ef7\u5355\u6216\u7f51\u7edc\u622a\u56fe\u7b49\u3002"}]', 'text', '裴润晨欠了姚元顺100杯奶茶赖账不还了', '2026-03-23 13:35:04.096067+08', '2026-03-23 13:35:04.096067+08');
INSERT INTO "public"."dispute_infos" VALUES ('05852b02-dd7b-4694-91e8-ca11190ff717', '奶茶债务纠纷', '[{"name": "\u59da\u5143\u987a", "role": "\u539f\u544a", "contact": "\u672a\u63d0\u4f9b"}, {"name": "\u88f4\u6da6\u6668", "role": "\u88ab\u544a", "contact": "\u672a\u63d0\u4f9b"}]', '未提供具体时间', '裴润晨向姚元顺欠下100杯奶茶的债务，但事后拒绝偿还，存在赖账行为。', '姚元顺要求裴润晨偿还100杯奶茶或等值价款。', '[{"name": "\u6b20\u6761\u6216\u4e66\u9762\u534f\u8bae", "type": "\u4e66\u8bc1", "description": "\u8bb0\u8f7d\u88f4\u6da6\u6668\u6b20\u59da\u5143\u987a100\u676f\u5976\u8336\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u53cc\u65b9\u5c31\u5976\u8336\u503a\u52a1\u8fdb\u884c\u6c9f\u901a\u7684\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\u8bb0\u5f55\u3002"}, {"name": "\u5f55\u97f3\u5f55\u50cf", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u80fd\u8bc1\u660e\u503a\u52a1\u5b58\u5728\u53ca\u88f4\u6da6\u6668\u627f\u8ba4\u503a\u52a1\u6216\u62d2\u7edd\u507f\u8fd8\u7684\u5f55\u97f3\u5f55\u50cf\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u77e5\u6653\u8be5\u503a\u52a1\u60c5\u51b5\u7684\u7b2c\u4e09\u65b9\u8bc1\u4eba\u7684\u9648\u8ff0\u3002"}, {"name": "\u5976\u8336\u5e02\u573a\u4ef7\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u7528\u4e8e\u786e\u5b9a100\u676f\u5976\u8336\u5177\u4f53\u4ef7\u503c\u7684\u5e02\u573a\u4ef7\u683c\u51ed\u8bc1\u3002"}]', 'text', '裴润晨欠了姚元顺100杯奶茶，但是他不还了，赖账', '2026-03-23 13:42:29.181593+08', '2026-03-23 13:42:29.181593+08');
INSERT INTO "public"."dispute_infos" VALUES ('3089bbb1-b56f-483a-a329-1f410cbc88c4', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}]', '2024年1月15日（借款发生日），2024年6月15日（约定还款日）', '2024年1月15日，被告张三向原告李四借款人民币10万元，双方约定于2024年6月15日还款。还款期限届满后，被告张三未履行还款义务，构成违约。', '要求被告张三立即归还借款本金人民币10万元，并支付自2024年6月16日起至实际清偿之日止的逾期利息（利息计算方式需根据法律规定或合同约定进一步明确）。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u501f\u6b3e\u4eba\u3001\u51fa\u501f\u4eba\u3001\u501f\u6b3e\u65e5\u671f\u3001\u7ea6\u5b9a\u8fd8\u6b3e\u65e5\u671f\u7b49\u6838\u5fc3\u6761\u6b3e\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u7b49\u65b9\u5f0f\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u652f\u4ed810\u4e07\u5143\u501f\u6b3e\u7684\u51ed\u8bc1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u53cc\u65b9\u5b58\u5728\u501f\u8d37\u5408\u610f\u3001\u534f\u5546\u501f\u6b3e\u3001\u50ac\u6536\u8fd8\u6b3e\u7b49\u6c9f\u901a\u5185\u5bb9\u7684\u8bb0\u5f55\uff08\u5982\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\uff09\u3002"}]', 'text', '纠纷涉及的人员:张三、李四· 发生时间:2024年1月15日·事件经过:张三向李四借款10万元，约定2024年6月15日还款，但到期后张三未还款 ·您的诉求:要求张三归还借款本金及利息 · 证据材料:借条、转账记录、聊天记录', '2026-03-23 13:52:27.000805+08', '2026-03-23 13:52:27.000805+08');
INSERT INTO "public"."dispute_infos" VALUES ('d39aa814-60de-4aa1-a02d-3ea1b3eabf44', '房屋装修质量纠纷', '[{"name": "\u738b\u5148\u751f", "role": "\u539f\u544a", "contact": "138****1234"}, {"name": "\u674e\u7ecf\u7406", "role": "\u88ab\u544a", "contact": "\u88c5\u4fee\u516c\u53f8\u9879\u76ee\u7ecf\u7406\uff0c\u5177\u4f53\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b"}]', '2023年10月签订合同并开始施工，2024年1月完工', '王先生于2023年10月与李经理所在的装修公司签订全包装修合同，对位于某小区的一套房屋进行装修。合同约定工期为三个月，总价款为15万元。施工过程中，王先生发现存在以下问题：1. 卫生间瓷砖空鼓率超过国家标准；2. 墙面乳胶漆存在多处开裂、起皮现象；3. 定制橱柜尺寸与设计图纸不符，导致无法正常安装电器；4. 部分水电线路未按规范铺设，存在安全隐患。王先生多次向李经理反映，对方虽承诺维修，但拖延数月仍未彻底解决，且维修后问题反复出现。', '王先生要求：1. 装修公司对存在的所有质量问题进行全面、彻底的修复，并达到合同约定的质量标准；2. 因工期延误和质量问题，要求对方支付合同总价款20%的违约金，共计3万元；3. 若无法修复，要求解除合同，返还已支付的全部款项并赔偿相应损失。', '[{"name": "\u300a\u623f\u5c4b\u88c5\u4fee\u5de5\u7a0b\u65bd\u5de5\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u3001\u88c5\u4fee\u6807\u51c6\u3001\u5de5\u671f\u3001\u4ef7\u6b3e\u53ca\u8fdd\u7ea6\u8d23\u4efb\u7b49\u6761\u6b3e\u3002"}, {"name": "\u4ed8\u6b3e\u51ed\u8bc1\uff08\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u3001\u6536\u636e\uff09", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u738b\u5148\u751f\u5df2\u6309\u5408\u540c\u7ea6\u5b9a\u652f\u4ed8\u4e86\u5de5\u7a0b\u6b3e\u9879\u3002"}, {"name": "\u73b0\u573a\u7167\u7247\u4e0e\u89c6\u9891", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599", "description": "\u6e05\u6670\u62cd\u6444\u4e86\u74f7\u7816\u7a7a\u9f13\u3001\u5899\u9762\u5f00\u88c2\u3001\u6a71\u67dc\u5c3a\u5bf8\u4e0d\u7b26\u3001\u6c34\u7535\u7ebf\u8def\u95ee\u9898\u7684\u5177\u4f53\u72b6\u51b5\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55\uff08\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u3001\u901a\u8bdd\u5f55\u97f3\uff09", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u738b\u5148\u751f\u66fe\u591a\u6b21\u5c31\u8d28\u91cf\u95ee\u9898\u5411\u674e\u7ecf\u7406\u63d0\u51fa\u5f02\u8bae\u53ca\u5bf9\u65b9\u627f\u8bfa\u7ef4\u4fee\u4f46\u672a\u5c65\u884c\u7684\u8fc7\u7a0b\u3002"}, {"name": "\u7b2c\u4e09\u65b9\u9274\u5b9a\u62a5\u544a\uff08\u5982\u6709\uff09", "type": "\u9274\u5b9a\u610f\u89c1", "description": "\u7531\u5177\u5907\u8d44\u8d28\u7684\u5de5\u7a0b\u8d28\u91cf\u68c0\u6d4b\u673a\u6784\u51fa\u5177\uff0c\u5bf9\u74f7\u7816\u7a7a\u9f13\u7387\u3001\u5899\u9762\u72b6\u51b5\u3001\u6c34\u7535\u5b89\u5168\u7b49\u8fdb\u884c\u4e13\u4e1a\u68c0\u6d4b\u4e0e\u8bc4\u4f30\u7684\u62a5\u544a\u3002"}, {"name": "\u8bbe\u8ba1\u56fe\u7eb8\u4e0e\u53d8\u66f4\u786e\u8ba4\u5355", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u6a71\u67dc\u7b49\u9879\u76ee\u7684\u539f\u59cb\u8bbe\u8ba1\u89c4\u683c\uff0c\u4ee5\u53ca\u65bd\u5de5\u662f\u5426\u504f\u79bb\u8bbe\u8ba1\u3002"}]', 'audio', '[音频文件: 8d27af42-2832-4ae0-b3df-71a8f97d6e27_测试.mp3]', '2026-03-31 16:55:14.06615+08', '2026-03-31 16:55:14.06615+08');
INSERT INTO "public"."dispute_infos" VALUES ('028112f6-79c1-4e05-aa91-04ebe20b7ad1', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\uff08\u6839\u636e\u539f\u59cb\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u6b64\u5904\u9700\u8865\u5145\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\uff08\u6839\u636e\u539f\u59cb\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u6b64\u5904\u9700\u8865\u5145\uff09"}]', '2024年1月15日（借款发生日），2024年6月15日（约定还款日）', '2024年1月15日，被告张三向原告李四借款人民币10万元，双方约定于2024年6月15日一次性还清。截至约定还款日，被告张三未履行还款义务，构成违约。', '1. 请求判令被告张三立即归还原告李四借款本金人民币10万元；2. 请求判令被告张三支付自2024年6月16日起至实际清偿之日止的逾期利息（利息计算标准可依据法律规定或双方约定）；3. 本案诉讼费用由被告张三承担。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u501f\u6b3e\u4eba\uff08\u5f20\u4e09\uff09\u3001\u51fa\u501f\u4eba\uff08\u674e\u56db\uff09\u3001\u501f\u6b3e\u65e5\u671f\u3001\u7ea6\u5b9a\u8fd8\u6b3e\u65e5\u671f\u7b49\u5173\u952e\u6761\u6b3e\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u65b9\u5f0f\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u652f\u4ed8\u501f\u6b3e\u672c\u91d110\u4e07\u5143\u7684\u51ed\u8bc1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u53cc\u65b9\u5c31\u501f\u6b3e\u4e8b\u5b9c\u3001\u50ac\u6b3e\u7ecf\u8fc7\u7b49\u8fdb\u884c\u6c9f\u901a\u7684\u5373\u65f6\u901a\u8baf\u8f6f\u4ef6\uff08\u5982\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\uff09\u8bb0\u5f55\uff0c\u53ef\u7528\u4e8e\u4f50\u8bc1\u501f\u6b3e\u5408\u610f\u3001\u50ac\u544a\u4e8b\u5b9e\u7b49\u3002"}]', 'text', '纠纷涉及的人员:张三、李四· 发生时间:2024年1月15日·事件经过:张三向李四借款10万元，约定2024年6月15日还款，但到期后张三未还款 ·您的诉求:要求张三归还借款本金及利息 · 证据材料:借条、转账记录、聊天记录', '2026-03-23 13:55:50.194482+08', '2026-03-23 13:55:50.194482+08');
INSERT INTO "public"."dispute_infos" VALUES ('6d563611-9c18-487c-978a-c70a8324046c', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\uff08\u6839\u636e\u539f\u59cb\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u6b64\u5904\u9700\u8865\u5145\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\uff08\u6839\u636e\u539f\u59cb\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u6b64\u5904\u9700\u8865\u5145\uff09"}]', '2024年1月15日（借款发生日），2024年6月15日（约定还款日）', '2024年1月15日，被告张三向原告李四借款人民币10万元，双方约定于2024年6月15日一次性还清。截至约定还款日，被告张三未履行还款义务，构成违约。', '1. 请求判令被告张三立即归还原告李四借款本金人民币10万元；2. 请求判令被告张三支付自2024年6月16日起至实际清偿之日止的逾期利息（利息计算标准可依据法律规定或双方约定）；3. 本案诉讼费用由被告张三承担。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u501f\u6b3e\u4eba\u5f20\u4e09\u3001\u51fa\u501f\u4eba\u674e\u56db\u3001\u501f\u6b3e\u91d1\u989d10\u4e07\u5143\u3001\u7ea6\u5b9a\u8fd8\u6b3e\u65e5\u671f2024\u5e746\u670815\u65e5\u7b49\u5173\u952e\u6761\u6b3e\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u3001\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u7b49\u65b9\u5f0f\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u652f\u4ed810\u4e07\u5143\u501f\u6b3e\u7684\u51ed\u8bc1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5305\u542b\u53cc\u65b9\u5c31\u501f\u6b3e\u4e8b\u5b9c\u8fdb\u884c\u6c9f\u901a\u3001\u786e\u8ba4\u501f\u6b3e\u4e8b\u5b9e\u3001\u50ac\u544a\u8fd8\u6b3e\u7b49\u5185\u5bb9\u7684\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\u901a\u8baf\u8bb0\u5f55\uff0c\u7528\u4ee5\u4f50\u8bc1\u501f\u6b3e\u5408\u610f\u53ca\u8fdd\u7ea6\u4e8b\u5b9e\u3002"}]', 'text', '纠纷涉及的人员:张三、李四· 发生时间:2024年1月15日·事件经过:张三向李四借款10万元，约定2024年6月15日还款，但到期后张三未还款 ·您的诉求:要求张三归还借款本金及利息 · 证据材料:借条、转账记录、聊天记录', '2026-03-23 13:56:35.321641+08', '2026-03-23 13:56:35.321641+08');
INSERT INTO "public"."dispute_infos" VALUES ('f91e773c-0ae6-4cc8-bd19-c993cf1cd3cb', '房屋租赁合同纠纷', '[{"name": "\u5f20\u4e09", "role": "\u539f\u544a", "contact": "13800138000"}, {"name": "\u674e\u56db", "role": "\u88ab\u544a", "contact": "13900139000"}]', '2024年6月15日', '原告张三与被告李四于2024年6月15日签订了一份为期一年的房屋租赁合同。合同约定，张三将位于某市某区某路某号的一套房屋出租给李四居住，月租金为人民币3000元，押一付三。李四在支付了首期租金及押金后入住。入住后不久，李四发现房屋存在多处严重质量问题（包括但不限于卫生间严重漏水、墙面大面积霉变、电路老化频繁跳闸），严重影响其正常居住使用。张三在接到李四多次口头及书面通知后，未能进行有效维修。李四遂自2024年8月起停止支付租金。张三因此主张李四违约，要求其支付拖欠租金并承担违约责任；李四则主张张三提供的租赁物不符合约定用途，构成根本违约，要求解除合同并赔偿损失。', '原告张三的诉求：1. 请求判令被告李四支付自2024年8月起至合同解除或履行完毕之日止的拖欠租金及违约金；2. 请求判令被告承担本案诉讼费用。
被告李四的反诉/抗辩诉求：1. 请求确认租赁合同因出租人根本违约而解除；2. 请求判令原告张三返还已付押金；3. 请求判令原告张三赔偿其因房屋质量问题造成的各项损失（如另行租房的差价、维修费用等）；4. 请求判令原告承担本案诉讼费用。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u3001\u79df\u8d41\u671f\u9650\u3001\u79df\u91d1\u6807\u51c6\u3001\u7ef4\u4fee\u8d23\u4efb\u7b49\u5173\u952e\u6761\u6b3e\u7684\u539f\u4ef6\u3002"}, {"name": "\u79df\u91d1\u53ca\u62bc\u91d1\u652f\u4ed8\u51ed\u8bc1", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u3001\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u8f6c\u8d26\u622a\u56fe\u6216\u6536\u636e\uff0c\u8bc1\u660e\u674e\u56db\u5df2\u652f\u4ed8\u9996\u671f\u79df\u91d1\u548c\u62bc\u91d1\u3002"}, {"name": "\u623f\u5c4b\u73b0\u72b6\u7167\u7247\u53ca\u89c6\u9891", "type": "\u7535\u5b50\u6570\u636e", "description": "\u6e05\u6670\u663e\u793a\u536b\u751f\u95f4\u6f0f\u6c34\u3001\u5899\u9762\u9709\u53d8\u3001\u7535\u8def\u95ee\u9898\u7b49\u8d28\u91cf\u7f3a\u9677\u7684\u5f71\u50cf\u8d44\u6599\uff0c\u6700\u597d\u5e26\u6709\u65f6\u95f4\u6233\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u674e\u56db\u5411\u5f20\u4e09\u53cd\u6620\u623f\u5c4b\u8d28\u91cf\u95ee\u9898\u7684\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u8bb0\u5f55\u6216\u7535\u5b50\u90ae\u4ef6\uff0c\u4ee5\u53ca\u8981\u6c42\u7ef4\u4fee\u7684\u4e66\u9762\u901a\u77e5\uff08\u5982\u6709\u5feb\u9012\u5e95\u5355\uff09\u3002"}, {"name": "\u7b2c\u4e09\u65b9\u7ef4\u4fee\u62a5\u4ef7\u6216\u9274\u5b9a\u62a5\u544a", "type": "\u9274\u5b9a\u610f\u89c1/\u4e66\u8bc1", "description": "\u8058\u8bf7\u4e13\u4e1a\u673a\u6784\u6216\u4eba\u5458\u5bf9\u623f\u5c4b\u8d28\u91cf\u95ee\u9898\u8fdb\u884c\u7684\u8bc4\u4f30\u3001\u62a5\u4ef7\u6216\u51fa\u5177\u7684\u9274\u5b9a\u62a5\u544a\uff0c\u7528\u4ee5\u8bc1\u660e\u95ee\u9898\u7684\u4e25\u91cd\u6027\u548c\u7ef4\u4fee\u6210\u672c\u3002"}, {"name": "\u7269\u4e1a\u6216\u90bb\u5c45\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u53ef\u8bc1\u660e\u623f\u5c4b\u957f\u671f\u5b58\u5728\u76f8\u5173\u8d28\u91cf\u95ee\u9898\u7684\u8bc1\u4eba\u8bc1\u8a00\u3002"}, {"name": "\u53e6\u884c\u79df\u8d41\u623f\u5c4b\u7684\u5408\u540c\u53ca\u4ed8\u6b3e\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u5982\u679c\u674e\u56db\u56e0\u539f\u623f\u5c4b\u65e0\u6cd5\u5c45\u4f4f\u800c\u53e6\u79df\u623f\u5c4b\uff0c\u76f8\u5173\u5408\u540c\u548c\u4ed8\u6b3e\u51ed\u8bc1\u53ef\u4f5c\u4e3a\u635f\u5931\u8bc1\u636e\u3002"}]', 'text', '???????10??,??2024?6?15???,?????????', '2026-03-23 13:58:46.638221+08', '2026-03-23 13:58:46.638221+08');
INSERT INTO "public"."dispute_infos" VALUES ('85c317c1-03a5-4e5d-8ff2-c8e4ed22f718', '房屋租赁合同纠纷', '[{"name": "\u5f20\u4e09", "role": "\u539f\u544a", "contact": "13800138000"}, {"name": "\u674e\u56db", "role": "\u88ab\u544a", "contact": "13900139000"}]', '2024年6月15日', '原告张三与被告李四签订了一份为期一年的房屋租赁合同，约定租金为每月5000元，押一付三。合同签订后，张三按约支付了首期租金及押金共计20000元。但在2024年6月15日，张三发现房屋存在严重的漏水问题，导致部分家具受损，且经多次沟通，李四拒绝进行维修。张三认为该房屋不符合合同约定的居住条件，要求解除合同并退还已支付款项，但李四以合同已生效且问题属于“自然损耗”为由拒绝。', '1. 请求法院判令解除双方于【合同签订日期】签订的《房屋租赁合同》；2. 请求法院判令被告李四返还原告张三已支付的租金15000元及押金5000元，共计20000元；3. 请求法院判令被告李四赔偿原告张三因房屋漏水导致的家具损失【具体金额待评估】；4. 本案诉讼费用由被告承担。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u3001\u79df\u91d1\u3001\u79df\u671f\u3001\u623f\u5c4b\u72b6\u51b5\u4fdd\u8bc1\u7b49\u5173\u952e\u6761\u6b3e\u7684\u539f\u4ef6\u6216\u6e05\u6670\u590d\u5370\u4ef6\u3002"}, {"name": "\u79df\u91d1\u53ca\u62bc\u91d1\u652f\u4ed8\u51ed\u8bc1", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u3001\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u8f6c\u8d26\u622a\u56fe\u6216\u6536\u636e\uff0c\u8bc1\u660e\u539f\u544a\u5df2\u652f\u4ed820000\u5143\u3002"}, {"name": "\u623f\u5c4b\u6f0f\u6c34\u73b0\u573a\u7167\u7247/\u89c6\u9891", "type": "\u7535\u5b50\u6570\u636e", "description": "\u6e05\u6670\u663e\u793a\u6f0f\u6c34\u4f4d\u7f6e\u3001\u4e25\u91cd\u7a0b\u5ea6\u3001\u4ee5\u53ca\u9020\u6210\u5bb6\u5177\u7b49\u8d22\u4ea7\u53d7\u635f\u60c5\u51b5\u7684\u5f71\u50cf\u8d44\u6599\uff0c\u6700\u597d\u5e26\u6709\u65f6\u95f4\u6233\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599", "description": "\u4e0e\u88ab\u544a\u674e\u56db\u5c31\u623f\u5c4b\u6f0f\u6c34\u95ee\u9898\u8fdb\u884c\u4ea4\u6d89\u7684\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u8bb0\u5f55\u6216\u901a\u8bdd\u5f55\u97f3\uff0c\u8bc1\u660e\u539f\u544a\u5df2\u5c65\u884c\u544a\u77e5\u4e49\u52a1\u4e14\u88ab\u544a\u62d2\u7edd\u7ef4\u4fee\u3002"}, {"name": "\u5bb6\u5177\u8d2d\u4e70\u51ed\u8bc1\u53ca\u635f\u5931\u8bc4\u4f30\u62a5\u544a", "type": "\u4e66\u8bc1/\u9274\u5b9a\u610f\u89c1", "description": "\u53d7\u635f\u5bb6\u5177\u7684\u539f\u59cb\u8d2d\u4e70\u53d1\u7968\u3001\u5408\u540c\uff0c\u4ee5\u53ca\u5982\u6709\u7b2c\u4e09\u65b9\u9274\u5b9a\u673a\u6784\u51fa\u5177\u7684\u635f\u5931\u4ef7\u503c\u8bc4\u4f30\u62a5\u544a\u3002"}, {"name": "\u623f\u4ea7\u8bc1\u6216\u4ea7\u6743\u8bc1\u660e\u590d\u5370\u4ef6", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u88ab\u544a\u674e\u56db\u7cfb\u8be5\u51fa\u79df\u623f\u5c4b\u7684\u5408\u6cd5\u6743\u5229\u4eba\u6216\u6709\u51fa\u79df\u6743\u3002"}]', 'text', '???????10??,??2024?6?15???,?????????', '2026-03-23 14:01:06.620055+08', '2026-03-23 14:01:06.620055+08');
INSERT INTO "public"."dispute_infos" VALUES ('b762bda1-f958-4942-bbe4-45f0ca443dd4', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\uff08\u6839\u636e\u539f\u59cb\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u6b64\u5904\u7559\u7a7a\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\uff08\u6839\u636e\u539f\u59cb\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u6b64\u5904\u7559\u7a7a\uff09"}]', '2024年1月15日（借款发生日），2024年6月15日（约定还款日）', '2024年1月15日，被告张三向原告李四借款人民币10万元，双方约定于2024年6月15日一次性还清。截至约定还款日届满，被告张三未履行还款义务，构成违约。', '1. 请求判令被告张三立即归还原告李四借款本金人民币10万元；2. 请求判令被告张三支付自2024年6月16日起至实际清偿之日止的逾期利息（利息计算标准可依据法律规定或双方约定）。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u501f\u6b3e\u4eba\u3001\u51fa\u501f\u4eba\u3001\u501f\u6b3e\u65e5\u671f\u3001\u7ea6\u5b9a\u8fd8\u6b3e\u65e5\u671f\u7b49\u6838\u5fc3\u6761\u6b3e\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u3001\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u7b49\u65b9\u5f0f\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u652f\u4ed810\u4e07\u5143\u501f\u6b3e\u7684\u51ed\u8bc1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5305\u542b\u53cc\u65b9\u5c31\u501f\u6b3e\u4e8b\u5b9c\u8fdb\u884c\u6c9f\u901a\u3001\u50ac\u6536\u8fd8\u6b3e\u7b49\u5185\u5bb9\u7684\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\u901a\u8baf\u8bb0\u5f55\uff0c\u7528\u4ee5\u4f50\u8bc1\u501f\u6b3e\u5408\u610f\u3001\u50ac\u544a\u4e8b\u5b9e\u7b49\u3002"}]', 'text', '纠纷涉及的人员:张三、李四· 发生时间:2024年1月15日·事件经过:张三向李四借款10万元，约定2024年6月15日还款，但到期后张三未还款 ·您的诉求:要求张三归还借款本金及利息 · 证据材料:借条、转账记录、聊天记录', '2026-03-23 14:04:05.239726+08', '2026-03-23 14:04:05.239726+08');
INSERT INTO "public"."dispute_infos" VALUES ('f580f51e-74d1-44c3-9a4d-831fa3e8edeb', '奶茶债务纠纷', '[{"name": "\u8d75\u4e1c\u65b9", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}, {"name": "\u5f20\u50b2", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}]', '信息缺失', '张傲向赵东方欠下二十杯奶茶的债务，但张傲拒绝偿还。赵东方指称张傲为“老赖”，即存在习惯性拖欠债务的行为。', '赵东方要求张傲偿还二十杯奶茶的债务（或等值货币）。', '[{"name": "\u6b20\u6761\u6216\u4e66\u9762\u534f\u8bae", "type": "\u4e66\u8bc1", "description": "\u80fd\u8bc1\u660e\u5f20\u50b2\u627f\u8ba4\u6b20\u8d75\u4e1c\u65b9\u4e8c\u5341\u676f\u5976\u8336\u7684\u4e66\u9762\u6587\u4ef6\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\u901a\u8baf\u8bb0\u5f55\u4e2d\uff0c\u5173\u4e8e\u5f20\u50b2\u627f\u8ba4\u503a\u52a1\u6216\u8d75\u4e1c\u65b9\u50ac\u8ba8\u3001\u5f20\u50b2\u62d2\u7edd\u507f\u8fd8\u7684\u5185\u5bb9\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u77e5\u6653\u8be5\u503a\u52a1\u5b58\u5728\u7684\u7b2c\u4e09\u65b9\u8bc1\u4eba\u7684\u9648\u8ff0\u3002"}, {"name": "\u5f55\u97f3/\u5f55\u50cf", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u5305\u542b\u5f20\u50b2\u627f\u8ba4\u503a\u52a1\u6216\u8ba8\u8bba\u8fd8\u6b3e\u4e8b\u5b9c\u7684\u5f55\u97f3\u6216\u5f55\u50cf\u3002"}, {"name": "\u5976\u8336\u4ef7\u683c\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u7528\u4e8e\u786e\u5b9a\u4e8c\u5341\u676f\u5976\u8336\u5e02\u573a\u4ef7\u503c\u7684\u5355\u636e\uff0c\u5982\u83dc\u5355\u3001\u6536\u636e\u6216\u652f\u4ed8\u8bb0\u5f55\u3002"}]', 'voice', '张傲欠了赵东方二十杯奶茶，但是张傲不还。他是个老赖。', '2026-03-23 14:05:02.205794+08', '2026-03-23 14:05:02.205794+08');
INSERT INTO "public"."dispute_infos" VALUES ('60068dd6-21f2-45b0-981b-566cd04d01e5', '房屋租赁押金返还纠纷', '[{"name": "\u5f20\u4f1f", "role": "\u539f\u544a\uff08\u627f\u79df\u4eba\uff09", "contact": "138****1234"}, {"name": "\u674e\u82b3", "role": "\u88ab\u544a\uff08\u51fa\u79df\u4eba\uff09", "contact": "139****5678"}]', '2023年10月15日（租赁合同到期日）', '原告张伟于2022年10月15日与被告李芳签订为期一年的房屋租赁合同，租赁位于XX市XX区XX小区X栋X单元XXX室的房屋，押金为人民币8000元。合同约定租期届满，房屋设施完好且结清所有费用后，被告应在7个工作日内无息返还押金。2023年10月15日合同到期，张伟依约交还房屋，并结清了水电燃气及物业费。但李芳以‘墙面有轻微污渍、厨房抽油烟机需深度清洁’为由，单方面决定扣除押金中的2000元作为‘维修清洁费’，仅同意返还6000元。张伟认为污渍属正常使用损耗，抽油烟机已进行过基础清洁，李芳的要求不合理且超出合同约定，双方多次协商未果。', '原告张伟要求被告李芳立即全额返还房屋租赁押金人民币8000元，并支付自应返还之日（2023年10月25日）起至实际付清之日止的逾期返还利息（可按全国银行间同业拆借中心公布的贷款市场报价利率计算）。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u79df\u8d41\u671f\u9650\u3001\u62bc\u91d1\u91d1\u989d\u3001\u8fd4\u8fd8\u6761\u4ef6\u53ca\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u7684\u539f\u59cb\u5408\u540c\u3002"}, {"name": "\u62bc\u91d1\u652f\u4ed8\u51ed\u8bc1", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u6216\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u8f6c\u8d26\u622a\u56fe\uff0c\u8bc1\u660e\u5f20\u4f1f\u5df2\u652f\u4ed88000\u5143\u62bc\u91d1\u3002"}, {"name": "\u623f\u5c4b\u4ea4\u63a5\u786e\u8ba4\u5355/\u89c6\u9891\u7167\u7247", "type": "\u89c6\u542c\u8d44\u6599/\u7535\u5b50\u6570\u636e", "description": "\u9000\u79df\u65f6\u623f\u5c4b\u72b6\u6001\u7684\u89c6\u9891\u3001\u7167\u7247\uff0c\u6216\u53cc\u65b9\u7b7e\u5b57\u7684\u4ea4\u63a5\u6e05\u5355\uff0c\u7528\u4ee5\u8bc1\u660e\u623f\u5c4b\u5df2\u6309\u7ea6\u5b9a\u72b6\u6001\u8fd4\u8fd8\uff0c\u65e0\u660e\u663e\u4eba\u4e3a\u635f\u574f\u3002"}, {"name": "\u5404\u9879\u8d39\u7528\u7ed3\u6e05\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u6c34\u7535\u8d39\u3001\u71c3\u6c14\u8d39\u3001\u7269\u4e1a\u8d39\u7684\u6700\u7ec8\u7f34\u8d39\u8d26\u5355\u6216\u7ed3\u6e05\u8bc1\u660e\u3002"}, {"name": "\u53cc\u65b9\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u6216\u7535\u5b50\u90ae\u4ef6\uff0c\u5185\u5bb9\u6d89\u53ca\u674e\u82b3\u63d0\u51fa\u6263\u6b3e\u7406\u7531\u53ca\u53cc\u65b9\u5c31\u6b64\u8fdb\u884c\u7684\u534f\u5546\u8fc7\u7a0b\u3002"}, {"name": "\u50ac\u544a\u51fd\u53ca\u9001\u8fbe\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u5f20\u4f1f\u5411\u674e\u82b3\u53d1\u51fa\u7684\u8981\u6c42\u8fd4\u8fd8\u5168\u989d\u62bc\u91d1\u7684\u4e66\u9762\u50ac\u544a\u51fd\u53ca\u5feb\u9012\u5e95\u5355\u3002"}]', 'audio', '[音频文件: 测试.mp3]', '2026-03-23 14:06:04.328912+08', '2026-03-23 14:06:04.328912+08');
INSERT INTO "public"."dispute_infos" VALUES ('63a114a2-f65d-4bc4-a0c1-befd639c623b', '房屋租赁合同违约纠纷', '[{"name": "\u5f20\u4f1f", "role": "\u539f\u544a\uff08\u627f\u79df\u4eba\uff09", "contact": "138****1234"}, {"name": "\u674e\u82b3", "role": "\u88ab\u544a\uff08\u51fa\u79df\u4eba\uff09", "contact": "139****5678"}]', '2023年10月15日', '原告张伟与被告李芳于2023年9月1日签订《房屋租赁合同》，约定租赁位于XX市XX区XX路XX号XX室房屋，租期一年，月租金5000元，押一付三。合同约定出租人应保证房屋设施完好、可正常使用。原告于9月1日支付首期租金及押金共计20000元。入住后发现卫生间水管严重漏水、空调无法制冷，多次联系被告要求维修，被告口头答应但迟迟未处理。10月15日，因漏水导致楼下邻居天花板受损，邻居索赔，原告再次催促被告，被告以“小问题租客自己解决”为由推诿，并拒绝承担维修责任及邻居损失。原告认为被告行为构成根本违约，无法实现合同目的。', '1. 解除双方签订的《房屋租赁合同》；2. 被告返还已支付租金15000元及押金5000元；3. 被告赔偿原告因房屋质量问题导致的临时住宿费、误工费等损失共计3000元；4. 被告承担本案诉讼费用。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u3001\u79df\u91d1\u3001\u79df\u671f\u3001\u7ef4\u4fee\u8d23\u4efb\u6761\u6b3e\uff08\u7b2c5\u6761\u7ea6\u5b9a\u51fa\u79df\u4eba\u8d1f\u8d23\u623f\u5c4b\u53ca\u8bbe\u65bd\u7ef4\u4fee\uff09\u3002"}, {"name": "\u79df\u91d1\u53ca\u62bc\u91d1\u652f\u4ed8\u51ed\u8bc1", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55/\u5fae\u4fe1\u652f\u4ed8\u622a\u56fe\uff0c\u663e\u793a\u539f\u544a\u5411\u88ab\u544a\u652f\u4ed820000\u5143\u3002"}, {"name": "\u623f\u5c4b\u8d28\u91cf\u95ee\u9898\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55/\u77ed\u4fe1\u8bb0\u5f55\uff0c\u663e\u793a\u539f\u544a\u591a\u6b21\u53cd\u6620\u6f0f\u6c34\u3001\u7a7a\u8c03\u6545\u969c\u95ee\u9898\uff0c\u88ab\u544a\u62d6\u5ef6\u5904\u7406\u3002"}, {"name": "\u623f\u5c4b\u73b0\u72b6\u7167\u7247/\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u536b\u751f\u95f4\u6f0f\u6c34\u73b0\u573a\u3001\u7a7a\u8c03\u65e0\u6cd5\u5236\u51b7\u3001\u697c\u4e0b\u90bb\u5c45\u5929\u82b1\u677f\u53d7\u635f\u60c5\u51b5\u7684\u5f71\u50cf\u8d44\u6599\u3002"}, {"name": "\u90bb\u5c45\u7d22\u8d54\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u4e0e\u697c\u4e0b\u90bb\u5c45\u5c31\u6f0f\u6c34\u635f\u5931\u7684\u6c9f\u901a\u8bb0\u5f55\uff0c\u6216\u90bb\u5c45\u51fa\u5177\u7684\u4e66\u9762\u8bf4\u660e\u3002"}, {"name": "\u4e34\u65f6\u4f4f\u5bbf\u8d39\u7528\u7968\u636e", "type": "\u4e66\u8bc1", "description": "\u56e0\u623f\u5c4b\u65e0\u6cd5\u5c45\u4f4f\u5728\u5916\u4e34\u65f6\u4f4f\u5bbf\u7684\u9152\u5e97\u53d1\u7968\u6216\u79df\u8d41\u6536\u636e\u3002"}]', 'image', '[图片文件: 图片.png]', '2026-03-23 14:06:47.650207+08', '2026-03-23 14:06:47.650207+08');
INSERT INTO "public"."dispute_infos" VALUES ('2fba37a7-1b06-4a52-bf25-aee3c9cfe6d6', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u660e\u786e\u63d0\u4f9b\uff0c\u9700\u5728\u8bc9\u8bbc\u4e2d\u8865\u5145\u3002"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u660e\u786e\u63d0\u4f9b\uff0c\u9700\u5728\u8bc9\u8bbc\u4e2d\u8865\u5145\u3002"}]', '2026年3月31日', '2026年3月31日，被告张三因个人资金周转需要，向原告李四借款。双方就借款金额、借款期限及借款利率达成口头或书面约定。李四通过银行转账等方式向张三交付了约定的借款本金。张三收到借款后，向李四出具了借条，对借款事实、金额、期限、利率等予以书面确认。借款到期后，张三未按约定偿还借款本金及支付相应利息。经原告李四多次催告，被告张三仍以拖延等方式拒绝履行还款义务。', '原告李四的诉讼请求为：1. 判令被告张三立即偿还原告借款本金（具体金额需根据借条及转账记录确定）；2. 判令被告张三支付自借款之日起至实际清偿之日止的约定利息（具体利率和计算方式需根据借条约定确定）；3. 本案诉讼费用由被告张三承担。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u4eb2\u7b14\u4e66\u5199\u5e76\u7b7e\u540d\u7684\u501f\u6761\u539f\u4ef6\uff0c\u7528\u4ee5\u8bc1\u660e\u53cc\u65b9\u5b58\u5728\u501f\u8d37\u5408\u610f\uff0c\u5e76\u8f7d\u660e\u4e86\u501f\u6b3e\u672c\u91d1\u3001\u501f\u6b3e\u671f\u9650\u3001\u7ea6\u5b9a\u5229\u7387\u7b49\u6838\u5fc3\u6761\u6b3e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u539f\u544a\u674e\u56db\u5411\u88ab\u544a\u5f20\u4e09\u652f\u4ed8\u501f\u6b3e\u7684\u94f6\u884c\u8f6c\u8d26\u51ed\u8bc1\uff08\u5982\u7f51\u94f6\u622a\u56fe\u3001\u94f6\u884c\u56de\u5355\u7b49\uff09\uff0c\u7528\u4ee5\u8bc1\u660e\u539f\u544a\u5df2\u5b9e\u9645\u5c65\u884c\u4e86\u51fa\u501f\u4e49\u52a1\uff0c\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u53cc\u65b9\u5c31\u501f\u6b3e\u4e8b\u5b9c\u3001\u50ac\u544a\u8fd8\u6b3e\u7b49\u8fdb\u884c\u6c9f\u901a\u7684\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\u804a\u5929\u8bb0\u5f55\uff0c\u7528\u4ee5\u8f85\u52a9\u8bc1\u660e\u501f\u8d37\u5173\u7cfb\u6210\u7acb\u3001\u50ac\u544a\u4e8b\u5b9e\u4ee5\u53ca\u88ab\u544a\u62d6\u5ef6\u8fd8\u6b3e\u7684\u610f\u601d\u8868\u793a\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u89c6\u542c\u8d44\u6599/\u7535\u5b50\u6570\u636e/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u539f\u544a\u591a\u6b21\u5411\u88ab\u544a\u8fdb\u884c\u50ac\u544a\u7684\u8bc1\u636e\uff0c\u5982\u50ac\u6536\u7535\u8bdd\u5f55\u97f3\u3001\u50ac\u6b3e\u51fd\u53ca\u90ae\u5bc4\u51ed\u8bc1\u3001\u6709\u50ac\u6536\u5185\u5bb9\u7684\u804a\u5929\u8bb0\u5f55\u7b49\uff0c\u7528\u4ee5\u8bc1\u660e\u539f\u544a\u4e3b\u5f20\u6743\u5229\u672a\u8d85\u8fc7\u8bc9\u8bbc\u65f6\u6548\uff0c\u4ee5\u53ca\u88ab\u544a\u8fdd\u7ea6\u7684\u4e8b\u5b9e\u3002"}]', 'text', ' 2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-31 15:22:57.547365+08', '2026-03-31 15:22:57.547365+08');
INSERT INTO "public"."dispute_infos" VALUES ('894509f4-4944-4217-8277-99c981962299', '房屋租赁合同纠纷', '[{"name": "\u5f20\u4e09", "role": "\u539f\u544a", "contact": "13800138000"}, {"name": "\u674e\u56db", "role": "\u88ab\u544a", "contact": "13900139000"}]', '2023年5月1日', '原告张三与被告李四于2023年5月1日签订《房屋租赁合同》，约定张三将其位于XX市XX区XX路XX号XX室的房屋出租给李四，租期一年，月租金5000元，押一付三。合同签订后，李四支付了首期租金及押金共计20000元。李四入住后，以房屋存在漏水、空调不制冷等问题为由，自2023年8月起拒绝支付后续租金。张三多次催告无果，李四至今仍占用房屋但未支付2023年8月至今的租金。', '1. 请求判令被告李四立即支付拖欠的租金共计25000元（自2023年8月1日至2023年12月31日，共5个月，每月5000元）；2. 请求判令被告李四立即腾退并返还涉案房屋；3. 请求判令被告承担本案全部诉讼费用。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u88ab\u544a\u4e4b\u95f4\u5b58\u5728\u5408\u6cd5\u6709\u6548\u7684\u623f\u5c4b\u79df\u8d41\u5408\u540c\u5173\u7cfb\uff0c\u7ea6\u5b9a\u4e86\u79df\u8d41\u671f\u9650\u3001\u79df\u91d1\u6807\u51c6\u3001\u652f\u4ed8\u65b9\u5f0f\u53ca\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u3002"}, {"name": "\u79df\u91d1\u53ca\u62bc\u91d1\u6536\u636e/\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u88ab\u544a\u5df2\u652f\u4ed8\u9996\u671f\u79df\u91d1\u53ca\u62bc\u91d1\uff0c\u4ee5\u53ca\u540e\u7eed\u79df\u91d1\u672a\u652f\u4ed8\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u50ac\u6536\u79df\u91d1\u7684\u901a\u77e5\uff08\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55/\u77ed\u4fe1/\u51fd\u4ef6\uff09", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5df2\u5c31\u62d6\u6b20\u79df\u91d1\u4e8b\u5b9c\u5411\u88ab\u544a\u8fdb\u884c\u8fc7\u6709\u6548\u50ac\u544a\u3002"}, {"name": "\u623f\u5c4b\u73b0\u72b6\u7684\u7167\u7247\u6216\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u88ab\u544a\u76ee\u524d\u4ecd\u5b9e\u9645\u5360\u6709\u4f7f\u7528\u6d89\u6848\u623f\u5c4b\u3002"}, {"name": "\u5173\u4e8e\u623f\u5c4b\u95ee\u9898\u7684\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e\uff08\u5982\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\uff09", "description": "\u8bc1\u660e\u88ab\u544a\u66fe\u63d0\u51fa\u623f\u5c4b\u5b58\u5728\u8d28\u91cf\u95ee\u9898\uff0c\u4ee5\u53ca\u53cc\u65b9\u5c31\u6b64\u95ee\u9898\u7684\u4ea4\u6d89\u60c5\u51b5\u3002"}]', 'image', '[图片文件: b405fc56-2750-4c07-a7f1-fa46a9e9ea34_图片.png]', '2026-03-23 14:50:05.836129+08', '2026-03-23 14:50:05.836129+08');
INSERT INTO "public"."dispute_infos" VALUES ('ab5143af-cf33-4857-8521-6eedcd9690e3', '奶茶债务纠纷', '[{"name": "\u59da\u5143\u987a", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}, {"name": "\u88f4\u6da6\u6668", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}]', '信息缺失', '被告裴润晨向原告姚元顺承诺或约定提供100杯奶茶，但至今未履行该承诺或约定，构成债务未清偿。', '原告姚元顺要求被告裴润晨履行交付100杯奶茶的债务，或支付相应的等值价款。', '[{"name": "\u503a\u6743\u51ed\u8bc1", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u80fd\u8bc1\u660e\u503a\u52a1\u5b58\u5728\u7684\u4e66\u9762\u534f\u8bae\u3001\u501f\u6761\u3001\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1/\u77ed\u4fe1\u7b49\uff09\u3001\u7535\u5b50\u90ae\u4ef6\u6216\u5f55\u97f3\u5f55\u50cf\u3002\u5185\u5bb9\u9700\u660e\u786e\u6307\u5411\u201c100\u676f\u5976\u8336\u201d\u7684\u503a\u52a1\u5173\u7cfb\u3001\u5f53\u4e8b\u4eba\u8eab\u4efd\u53ca\u503a\u52a1\u5f62\u6210\u539f\u56e0\uff08\u5982\u8d60\u4e0e\u3001\u4e70\u5356\u3001\u62b5\u507f\u7b49\uff09\u3002"}, {"name": "\u5c65\u884c\u50ac\u544a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u539f\u544a\u5411\u88ab\u544a\u50ac\u8ba8\u503a\u52a1\u7684\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u3001\u90ae\u4ef6\u6216\u51fd\u4ef6\uff0c\u8bc1\u660e\u539f\u544a\u66fe\u4e3b\u5f20\u6743\u5229\u800c\u88ab\u544a\u672a\u5c65\u884c\u3002"}, {"name": "\u5f53\u4e8b\u4eba\u8eab\u4efd\u4fe1\u606f", "type": "\u4e66\u8bc1", "description": "\u539f\u3001\u88ab\u544a\u7684\u8eab\u4efd\u8bc1\u660e\u6587\u4ef6\uff08\u5982\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6\uff09\uff0c\u7528\u4e8e\u786e\u8ba4\u8bc9\u8bbc\u4e3b\u4f53\u8d44\u683c\u3002"}, {"name": "\u5976\u8336\u4ef7\u503c\u8bc1\u660e", "type": "\u4e66\u8bc1/\u9274\u5b9a\u610f\u89c1", "description": "\u7528\u4e8e\u786e\u5b9a\u503a\u52a1\u6807\u7684\u7269\u4ef7\u503c\u7684\u8bc1\u636e\uff0c\u5982\u76f8\u5173\u5976\u8336\u4ea7\u54c1\u7684\u5e02\u573a\u4ef7\u683c\u8bc1\u660e\u3001\u83dc\u5355\u3001\u53d1\u7968\uff0c\u6216\u53cc\u65b9\u7ea6\u5b9a\u7684\u5355\u4ef7\u8bb0\u5f55\u3002\u5728\u8981\u6c42\u6298\u4ef7\u8d54\u507f\u65f6\u9700\u63d0\u4f9b\u3002"}]', 'text', ' 裴润晨欠姚元顺100杯奶茶不还', '2026-03-26 22:15:42.737836+08', '2026-03-26 22:15:42.737836+08');
INSERT INTO "public"."dispute_infos" VALUES ('c35a3154-9dee-424e-8bf9-18f8272357ab', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b"}]', '具体借款时间未提供', '张三向李四借款人民币1000元，但借款到期后，张三一直未履行还款义务，构成违约。', '要求张三立即偿还借款本金1000元，并可能主张逾期利息（如有约定或法律规定）。', '[{"name": "\u501f\u6761/\u6b20\u6761", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u501f\u6b3e\u4eba\u5f20\u4e09\u3001\u51fa\u501f\u4eba\u674e\u56db\u3001\u501f\u6b3e\u91d1\u989d1000\u5143\u3001\u501f\u6b3e\u65e5\u671f\u3001\u8fd8\u6b3e\u65e5\u671f\uff08\u5982\u6709\uff09\u3001\u5229\u606f\u7ea6\u5b9a\uff08\u5982\u6709\uff09\u53ca\u53cc\u65b9\u7b7e\u5b57\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u51ed\u8bc1\u3001\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u8f6c\u8d26\u622a\u56fe\u7b49\uff0c\u80fd\u8bc1\u660e\u674e\u56db\u5df2\u5411\u5f20\u4e09\u5b9e\u9645\u652f\u4ed81000\u5143\u501f\u6b3e\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55/\u77ed\u4fe1/\u90ae\u4ef6", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5305\u542b\u501f\u6b3e\u5408\u610f\u3001\u50ac\u6b3e\u5185\u5bb9\u3001\u5bf9\u65b9\u627f\u8ba4\u6b20\u6b3e\u6216\u627f\u8bfa\u8fd8\u6b3e\u7b49\u5185\u5bb9\u7684\u6c9f\u901a\u8bb0\u5f55\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u77e5\u6653\u8be5\u501f\u6b3e\u4e8b\u5b9e\u7684\u7b2c\u4e09\u65b9\u8bc1\u4eba\u7684\u8bc1\u8a00\u3002"}, {"name": "\u5f55\u97f3/\u5f55\u50cf", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u5728\u5408\u6cd5\u53d6\u5f97\u7684\u524d\u63d0\u4e0b\uff0c\u80fd\u8bc1\u660e\u501f\u6b3e\u4e8b\u5b9e\u6216\u50ac\u6b3e\u8fc7\u7a0b\u7684\u5f55\u97f3\u5f55\u50cf\u3002"}]', 'text', ' 张三欠了李四1000元一直拖欠不还怎么办', '2026-03-27 10:42:21.619971+08', '2026-03-27 10:42:21.619971+08');
INSERT INTO "public"."dispute_infos" VALUES ('1e86df6c-b915-40cb-bc5f-fa589ee239f2', '房屋租赁押金退还纠纷', '[{"name": "\u5f20\u4f1f", "role": "\u539f\u544a", "contact": "138****1234"}, {"name": "\u674e\u82b3", "role": "\u88ab\u544a", "contact": "\u623f\u4e1c\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b"}]', '2023年10月15日', '原告张伟于2023年5月1日租赁被告李芳位于某小区的一套房屋，租期半年，押金为两个月租金共计8000元。合同约定租期届满，房屋设施完好且无欠费的情况下，押金应全额退还。2023年10月31日租约到期，张伟按期搬离并交还钥匙。经双方现场查验，房屋设施基本完好，仅客厅墙壁有一处轻微划痕（约5厘米）。被告李芳以“房屋需要整体粉刷”为由，拒绝退还全部押金，提出要扣除5000元作为“墙面修复及清洁费”。张伟认为该费用极不合理，轻微划痕的修复成本极低，且合同中未约定此类情况的扣款标准。双方多次协商未果。', '原告张伟要求被告李芳按照合同约定，全额退还房屋租赁押金8000元。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u79df\u8d41\u671f\u9650\u3001\u79df\u91d1\u3001\u62bc\u91d1\u91d1\u989d\u3001\u9000\u8fd8\u6761\u4ef6\u53ca\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u7684\u5173\u952e\u6587\u4ef6\u3002"}, {"name": "\u62bc\u91d1\u652f\u4ed8\u51ed\u8bc1", "type": "\u7535\u5b50\u51ed\u8bc1/\u6536\u636e", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u6216\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u8f6c\u8d26\u622a\u56fe\uff0c\u8bc1\u660e\u5f20\u4f1f\u5df2\u652f\u4ed88000\u5143\u62bc\u91d1\u3002"}, {"name": "\u623f\u5c4b\u4ea4\u63a5\u65f6\u7684\u7167\u7247/\u89c6\u9891", "type": "\u7535\u5b50\u6570\u636e", "description": "\u79df\u671f\u5c4a\u6ee1\u65f6\u623f\u5c4b\u72b6\u51b5\u7684\u5f71\u50cf\u8d44\u6599\uff0c\u7279\u522b\u662f\u80fd\u663e\u793a\u5899\u58c1\u5212\u75d5\u5b9e\u9645\u5927\u5c0f\u4e0e\u7a0b\u5ea6\u7684\u8bc1\u636e\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u53cc\u65b9\u5c31\u62bc\u91d1\u9000\u8fd8\u4e8b\u5b9c\u8fdb\u884c\u534f\u5546\u7684\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u6216\u90ae\u4ef6\uff0c\u80fd\u8bc1\u660e\u674e\u82b3\u4ee5\u4e0d\u5408\u7406\u7406\u7531\u6263\u6b3e\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u82e5\u4ea4\u63a5\u65f6\u6709\u4e2d\u4ecb\u6216\u7b2c\u4e09\u65b9\u5728\u573a\uff0c\u5176\u8bc1\u8a00\u53ef\u4f5c\u4e3a\u8f85\u52a9\u8bc1\u636e\u3002"}, {"name": "\u5e02\u573a\u7ef4\u4fee\u62a5\u4ef7\u5355", "type": "\u4e66\u8bc1", "description": "\u53ef\u5411\u4e13\u4e1a\u673a\u6784\u54a8\u8be2\u83b7\u53d6\u9488\u5bf9\u8f7b\u5fae\u5899\u9762\u5212\u75d5\u7684\u4fee\u590d\u5e02\u573a\u62a5\u4ef7\uff0c\u7528\u4ee5\u53cd\u9a73\u88ab\u544a\u63d0\u51fa\u7684\u9ad8\u989d\u6263\u6b3e\u8981\u6c42\u3002"}]', 'audio', '[音频文件: 1e8d4ac1-4e85-4d40-ada8-2625f38e6ad9_测试.mp3]', '2026-03-27 10:44:00.217285+08', '2026-03-27 10:44:00.217285+08');
INSERT INTO "public"."dispute_infos" VALUES ('a88e3e83-a3f2-4870-aa29-f9d5ddd1e0de', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931"}]', '信息缺失', '张三向李四借款人民币2000元，但至今未偿还该笔欠款。', '要求张三立即偿还借款本金2000元，并可能主张相应的利息（如有约定）及维权产生的合理费用。', '[{"name": "\u501f\u6761/\u6b20\u6761", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u501f\u6b3e\u4eba\u5f20\u4e09\u3001\u51fa\u501f\u4eba\u674e\u56db\u3001\u501f\u6b3e\u91d1\u989d2000\u5143\u3001\u501f\u6b3e\u65e5\u671f\u53ca\u7ea6\u5b9a\u8fd8\u6b3e\u65e5\u671f\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u901a\u8fc7\u94f6\u884c\u3001\u5fae\u4fe1\u3001\u652f\u4ed8\u5b9d\u7b49\u6e20\u9053\u5411\u5f20\u4e09\u652f\u4ed82000\u5143\u7684\u8f6c\u8d26\u51ed\u8bc1\u3002"}, {"name": "\u804a\u5929/\u901a\u8baf\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u80fd\u8bc1\u660e\u501f\u8d37\u5408\u610f\u3001\u50ac\u6b3e\u4e8b\u5b9e\u7684\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\u804a\u5929\u8bb0\u5f55\u6216\u901a\u8bdd\u5f55\u97f3\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u4e86\u89e3\u8be5\u501f\u8d37\u4e8b\u5b9e\u7684\u8bc1\u4eba\u7684\u9648\u8ff0\u3002"}]', 'text', ' 张三欠了李四2000元，至今欠款不换', '2026-03-27 10:51:49.26353+08', '2026-03-27 10:51:49.26353+08');
INSERT INTO "public"."dispute_infos" VALUES ('9d68264b-4b49-4401-b01a-5b3b1de79115', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '2026年3月20日', '被告张三因个人资金周转需要，向原告李四借款人民币2万元。双方约定了借款金额、还款期限及借款利率。原告李四通过银行转账方式向被告张三交付了借款，被告张三收到款项后向原告李四出具了借条予以确认。借款到期后，被告张三未按约定偿还借款本金及利息。经原告李四多次催告，被告张三仍拖延不还，故引发诉讼。', '请求法院判令被告张三立即偿还原告李四借款本金人民币2万元及自借款之日起至实际清偿之日止的约定利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u65b9\u5f0f\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d12\u4e07\u5143\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1/\u77ed\u4fe1\u7b49\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5185\u5bb9\u53ef\u80fd\u5305\u542b\u501f\u6b3e\u534f\u5546\u3001\u50ac\u544a\u8fd8\u6b3e\u7b49\u8fc7\u7a0b\uff0c\u7528\u4e8e\u8f85\u52a9\u8bc1\u660e\u501f\u8d37\u4e8b\u5b9e\u3001\u50ac\u544a\u884c\u4e3a\u53ca\u88ab\u544a\u7684\u56de\u5e94\u60c5\u51b5\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u8bc1\u660e\u539f\u544a\u5728\u8bc9\u8bbc\u524d\u5df2\u5411\u88ab\u544a\u8fdb\u884c\u8fc7\u6709\u6548\u50ac\u544a\uff0c\u53ef\u80fd\u5305\u542b\u901a\u8bdd\u5f55\u97f3\u3001\u77ed\u4fe1\u3001\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u6216\u8bc1\u4eba\u8bc1\u8a00\u7b49\u3002"}]', 'text', '2026 年 3 月 20 日，被告张三因个人资金周转向原告李四借款2万元，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-27 11:24:57.244447+08', '2026-03-27 11:24:57.244447+08');
INSERT INTO "public"."dispute_infos" VALUES ('866e15a4-179f-47ab-98e3-f3e4d0db3a76', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}]', '2026年1月12日（此为约定的还款日或纠纷发生日，具体借款时间需进一步确认）', '被告张三向原告李四借款人民币20000元，双方约定于2026年1月12日归还。到期后，经原告李四催告，被告张三未履行还款义务，构成违约。', '原告李四的诉求为：1. 判令被告张三立即归还借款本金人民币20000元；2. 判令被告张三支付自2026年1月13日起至实际清偿之日止的逾期利息（可按起诉时一年期贷款市场报价利率LPR计算）；3. 本案诉讼费用由被告张三承担。', '[{"name": "\u501f\u6761/\u501f\u6b3e\u5408\u540c", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u51fa\u501f\u4eba\uff08\u674e\u56db\uff09\u3001\u501f\u6b3e\u4eba\uff08\u5f20\u4e09\uff09\u3001\u501f\u6b3e\u91d1\u989d\uff0820000\u5143\uff09\u3001\u501f\u6b3e\u65e5\u671f\u3001\u7ea6\u5b9a\u8fd8\u6b3e\u65e5\u671f\uff082026\u5e741\u670812\u65e5\uff09\u3001\u5229\u606f\u7ea6\u5b9a\uff08\u5982\u6709\uff09\u3001\u53cc\u65b9\u7b7e\u5b57\u7b49\u6838\u5fc3\u6761\u6b3e\u7684\u4e66\u9762\u6587\u4ef6\u3002"}, {"name": "\u4ed8\u6b3e\u51ed\u8bc1", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u674e\u56db\u5df2\u5411\u5f20\u4e09\u5b9e\u9645\u4ea4\u4ed820000\u5143\u501f\u6b3e\u7684\u8bc1\u636e\uff0c\u5982\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u3001\u5fae\u4fe1/\u652f\u4ed8\u5b9d\u8f6c\u8d26\u622a\u56fe\u3001\u6536\u6761\u7b49\u3002"}, {"name": "\u50ac\u6536\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u8bc1\u660e\u674e\u56db\u5728\u501f\u6b3e\u5230\u671f\u540e\u66fe\u5411\u5f20\u4e09\u4e3b\u5f20\u8fc7\u6743\u5229\u7684\u8bc1\u636e\uff0c\u5982\u5fae\u4fe1/\u77ed\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u901a\u8bdd\u5f55\u97f3\u3001\u7535\u5b50\u90ae\u4ef6\u3001\u50ac\u6536\u51fd\u53ca\u5feb\u9012\u5355\u636e\u3001\u8bc1\u4eba\u8bc1\u8a00\u7b49\u3002"}, {"name": "\u5f53\u4e8b\u4eba\u8eab\u4efd\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u539f\u544a\u674e\u56db\u548c\u88ab\u544a\u5f20\u4e09\u7684\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6\u6216\u6237\u7c4d\u4fe1\u606f\uff0c\u7528\u4e8e\u786e\u8ba4\u8bc9\u8bbc\u4e3b\u4f53\u8d44\u683c\u3002"}]', 'text', '张三欠李四20000元不还
2026年1月12日', '2026-03-27 13:50:29.889753+08', '2026-03-27 13:50:29.889753+08');
INSERT INTO "public"."dispute_infos" VALUES ('a195f756-3dcf-4b80-97e1-9174f5308672', '张三李四王五纠纷', '[{"name": "\u5f20\u4e09", "role": "\u539f\u544a", "contact": "\u672a\u63d0\u4f9b"}, {"name": "\u674e\u56db", "role": "\u88ab\u544a", "contact": "\u672a\u63d0\u4f9b"}, {"name": "\u738b\u4e94", "role": "\u7b2c\u4e09\u4eba", "contact": "\u672a\u63d0\u4f9b"}]', '未提供', '用户仅提供了当事人姓名“张三、李四、王五”，未提供具体纠纷事实经过。根据常规法律实践推断，此三人之间可能存在某种民事纠纷（如合同、侵权、债务、合伙等），但具体情节缺失。', '未提供。需由当事人明确其具体诉求（如要求赔偿、履行合同、确认权利、停止侵害等）。', '[{"name": "\u8eab\u4efd\u8bc1\u660e\u6587\u4ef6", "type": "\u4e66\u8bc1", "description": "\u5f20\u4e09\u3001\u674e\u56db\u3001\u738b\u4e94\u7684\u8eab\u4efd\u8bc1\u3001\u6237\u53e3\u672c\u6216\u8425\u4e1a\u6267\u7167\u7b49\uff0c\u7528\u4e8e\u786e\u8ba4\u8bc9\u8bbc\u4e3b\u4f53\u8d44\u683c\u3002"}, {"name": "\u57fa\u7840\u6cd5\u5f8b\u5173\u7cfb\u8bc1\u636e", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u53ef\u80fd\u5b58\u5728\u7684\u5408\u540c\u3001\u534f\u8bae\u3001\u501f\u6761\u3001\u6b20\u6761\u3001\u804a\u5929\u8bb0\u5f55\u3001\u90ae\u4ef6\u5f80\u6765\u7b49\uff0c\u7528\u4e8e\u8bc1\u660e\u5404\u65b9\u4e4b\u95f4\u5b58\u5728\u7684\u6cd5\u5f8b\u5173\u7cfb\u53ca\u6743\u5229\u4e49\u52a1\u5185\u5bb9\u3002"}, {"name": "\u7ea0\u7eb7\u4e8b\u5b9e\u8bc1\u636e", "type": "\u89c6\u6848\u4ef6\u6027\u8d28\u800c\u5b9a", "description": "\u5982\u6d89\u53ca\u4fb5\u6743\uff0c\u9700\u63d0\u4f9b\u635f\u5bb3\u8bc1\u660e\u3001\u73b0\u573a\u7167\u7247\u89c6\u9891\uff1b\u5982\u6d89\u53ca\u8fdd\u7ea6\uff0c\u9700\u63d0\u4f9b\u8fdd\u7ea6\u884c\u4e3a\u8bc1\u636e\uff1b\u5982\u6d89\u53ca\u503a\u52a1\uff0c\u9700\u63d0\u4f9b\u4ed8\u6b3e\u51ed\u8bc1\u3001\u50ac\u6536\u8bb0\u5f55\u7b49\u3002"}, {"name": "\u635f\u5931\u8ba1\u7b97\u4f9d\u636e", "type": "\u4e66\u8bc1/\u9274\u5b9a\u610f\u89c1", "description": "\u635f\u5931\u6e05\u5355\u3001\u53d1\u7968\u3001\u6536\u636e\u3001\u8bc4\u4f30\u62a5\u544a\u3001\u5ba1\u8ba1\u62a5\u544a\u7b49\uff0c\u7528\u4e8e\u652f\u6301\u5177\u4f53\u7684\u8d54\u507f\u6216\u8865\u507f\u8bc9\u6c42\u3002"}, {"name": "\u5176\u4ed6\u76f8\u5173\u8bc1\u636e", "type": "\u89c6\u6848\u4ef6\u6027\u8d28\u800c\u5b9a", "description": "\u8bc1\u4eba\u8bc1\u8a00\u3001\u5f55\u97f3\u5f55\u50cf\u3001\u516c\u8bc1\u4e66\u3001\u884c\u653f\u673a\u5173\u5904\u7406\u51b3\u5b9a\u7b49\u4e0e\u7ea0\u7eb7\u76f8\u5173\u7684\u5176\u4ed6\u6750\u6599\u3002"}]', 'voice', '张三李四王五。', '2026-03-28 20:24:32.239178+08', '2026-03-28 20:24:32.239178+08');
INSERT INTO "public"."dispute_infos" VALUES ('7277f09a-2f73-4d9d-8874-1be88137efa3', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '2026年3月31日', '被告张三因个人资金周转向原告李四借款。双方约定了借款金额、期限及利率，李四通过银行转账方式向张三交付了借款，张三收到款项后向李四出具了借条予以确认。借款到期后，张三未按约定归还本金及支付利息。经原告李四多次催告，被告张三仍拖延不还。', '要求被告张三偿还借款本金及自借款之日起至实际清偿之日止的约定利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u6309\u7ea6\u5b9a\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u65b9\u5f0f\u5b9e\u9645\u5411\u88ab\u544a\u5f20\u4e09\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1/\u77ed\u4fe1\u7b49\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5185\u5bb9\u53ef\u80fd\u6d89\u53ca\u501f\u6b3e\u534f\u5546\u3001\u50ac\u544a\u8fd8\u6b3e\u7b49\u8fc7\u7a0b\uff0c\u7528\u4e8e\u4f50\u8bc1\u501f\u8d37\u4e8b\u5b9e\u3001\u50ac\u544a\u884c\u4e3a\u53ca\u88ab\u544a\u62d6\u5ef6\u8fd8\u6b3e\u7684\u610f\u601d\u8868\u793a\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u8bc1\u660e\u539f\u544a\u5728\u8bc9\u8bbc\u524d\u5df2\u5411\u88ab\u544a\u8fdb\u884c\u8fc7\u6709\u6548\u50ac\u544a\uff0c\u53ef\u80fd\u5305\u542b\u901a\u8bdd\u5f55\u97f3\u3001\u77ed\u4fe1\u3001\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u6216\u8bc1\u4eba\u8bc1\u8a00\u7b49\u3002"}]', 'voice', ' 2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-31 15:23:36.140691+08', '2026-03-31 15:23:36.140691+08');
INSERT INTO "public"."dispute_infos" VALUES ('e29e2127-6645-422f-b8ea-fcbb715c650f', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b\uff0c\u9700\u8865\u5145"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b\uff0c\u9700\u8865\u5145"}]', '借款交付日（具体日期需根据借条或转账记录确定）至借款到期日（具体日期需根据借条确定）', '被告张三因个人资金周转需要，向原告李四借款。双方就借款金额、期限及利率达成口头或书面约定。李四通过银行转账方式向张三交付了借款，张三随后向李四出具了借条予以确认。约定的借款期限届满后，张三未能按约偿还借款本金及利息。经李四多次催告，张三仍以拖延等方式拒绝履行还款义务。李四为维护自身合法权益，遂向法院提起诉讼。', '1. 请求判令被告张三立即偿还原告李四借款本金【具体金额需根据借条及转账记录确定】；2. 请求判令被告张三支付以本金为基数，按约定利率计算至实际清偿之日止的利息（需明确计算期间及利率标准）；3. 请求判令本案诉讼费用由被告张三承担。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u4eba\u3001\u51fa\u501f\u4eba\u3001\u501f\u6b3e\u91d1\u989d\u3001\u501f\u6b3e\u671f\u9650\u3001\u5229\u7387\uff08\u5982\u6709\uff09\u3001\u51fa\u5177\u65e5\u671f\u7b49\u5173\u952e\u8981\u7d20\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u6761\u6b3e\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u51ed\u8bc1", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u65b9\u5f0f\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\uff0c\u662f\u8bc1\u660e\u501f\u6b3e\u5df2\u5b9e\u9645\u53d1\u751f\u7684\u5173\u952e\u8bc1\u636e\u3002"}, {"name": "\u50ac\u6536\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1/\u77ed\u4fe1\u7b49\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u5728\u501f\u6b3e\u5230\u671f\u540e\uff0c\u539f\u544a\u674e\u56db\u66fe\u5411\u88ab\u544a\u5f20\u4e09\u8fdb\u884c\u8fc7\u50ac\u544a\uff0c\u53ef\u80fd\u6d89\u53ca\u50ac\u544a\u65f6\u95f4\u3001\u91d1\u989d\u3001\u88ab\u544a\u7684\u56de\u5e94\uff08\u5982\u627f\u8ba4\u503a\u52a1\u3001\u627f\u8bfa\u8fd8\u6b3e\u6216\u62d6\u5ef6\u7406\u7531\uff09\u7b49\u5185\u5bb9\uff0c\u53ef\u7528\u4e8e\u8bc1\u660e\u8bc9\u8bbc\u65f6\u6548\u4e2d\u65ad\u53ca\u88ab\u544a\u8fdd\u7ea6\u4e8b\u5b9e\u3002"}, {"name": "\u901a\u8bdd\u5f55\u97f3", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u5982\u5b58\u5728\uff0c\u53ef\u8bc1\u660e\u50ac\u6536\u8fc7\u7a0b\u3001\u88ab\u544a\u5bf9\u501f\u6b3e\u4e8b\u5b9e\u7684\u627f\u8ba4\u6216\u8fd8\u6b3e\u627f\u8bfa\u3002"}, {"name": "\u5f53\u4e8b\u4eba\u8eab\u4efd\u8bc1\u660e\u6587\u4ef6", "type": "\u4e66\u8bc1", "description": "\u539f\u544a\u53ca\u88ab\u544a\u7684\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6\u6216\u6237\u7c4d\u8bc1\u660e\uff0c\u7528\u4e8e\u786e\u8ba4\u8bc9\u8bbc\u4e3b\u4f53\u8d44\u683c\u3002"}]', 'voice', '被告人张三因个人资金周转向原告李四借款，双方约定了借款金额期限及利率。李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按照约定归还北京以及利息，经过多次催告，仍然拖延不还。李四于是根据借条转账记录和聊天记录等证据向法院提起诉讼，要求张三偿还借款本金以及相应利息。', '2026-03-31 15:47:27.236944+08', '2026-03-31 15:47:27.236944+08');
INSERT INTO "public"."dispute_infos" VALUES ('2c588d73-3d8b-4c9d-bc21-f332d809303f', '房屋装修质量纠纷', '[{"name": "\u738b\u5148\u751f", "role": "\u539f\u544a", "contact": "138****1234\uff08\u97f3\u9891\u4e2d\u63d0\u53ca\uff09"}, {"name": "\u674e\u7ecf\u7406", "role": "\u88ab\u544a", "contact": "\u88c5\u4fee\u516c\u53f8\u8d1f\u8d23\u4eba\uff0c\u5177\u4f53\u8054\u7cfb\u65b9\u5f0f\u97f3\u9891\u4e2d\u672a\u660e\u786e"}]', '2023年10月（装修完工时间）', '王先生委托李经理所在的装修公司进行新房装修，于2023年10月完工。入住后发现存在多项严重质量问题：1. 卫生间防水层失效，导致楼下邻居天花板渗水并引发投诉；2. 客厅墙面瓷砖大面积空鼓，部分已出现裂纹；3. 定制橱柜尺寸错误，无法正常安装使用。王先生多次联系李经理要求返工维修，但对方起初拖延，后期拒绝处理，并声称保修期已过或属于正常损耗。双方协商无果，矛盾激化。', '王先生要求：1. 装修公司对全部质量问题（防水、瓷砖、橱柜）进行彻底返工修复，并承担修复期间其在外租住的合理费用；2. 赔偿因漏水给楼下邻居造成的损失（已由王先生先行垫付）；3. 就装修不达标部分，退还相应比例的装修款。', '[{"name": "\u300a\u5bb6\u5ead\u5c45\u5ba4\u88c5\u9970\u88c5\u4fee\u5de5\u7a0b\u65bd\u5de5\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u660e\u786e\u7ea6\u5b9a\u88c5\u4fee\u8303\u56f4\u3001\u8d28\u91cf\u6807\u51c6\u3001\u5de5\u671f\u3001\u4fdd\u4fee\u671f\uff08\u5e94\u81f3\u5c11\u4e24\u5e74\uff09\u53ca\u8fdd\u7ea6\u8d23\u4efb\u3002"}, {"name": "\u88c5\u4fee\u8d39\u7528\u652f\u4ed8\u51ed\u8bc1", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u3001\u6536\u636e\u7b49\uff0c\u8bc1\u660e\u5408\u540c\u4ef7\u6b3e\u53ca\u652f\u4ed8\u60c5\u51b5\u3002"}, {"name": "\u73b0\u573a\u7167\u7247\u4e0e\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u6e05\u6670\u53cd\u6620\u536b\u751f\u95f4\u6f0f\u6c34\u75d5\u8ff9\u3001\u5899\u9762\u74f7\u7816\u7a7a\u9f13\u88c2\u7eb9\u3001\u6a71\u67dc\u5c3a\u5bf8\u4e0d\u7b26\u7b49\u73b0\u72b6\u7684\u5f71\u50cf\u8d44\u6599\u3002"}, {"name": "\u4e0e\u674e\u7ecf\u7406/\u88c5\u4fee\u516c\u53f8\u7684\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599", "description": "\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u3001\u7535\u5b50\u90ae\u4ef6\u6216\u901a\u8bdd\u5f55\u97f3\uff0c\u8bc1\u660e\u738b\u5148\u751f\u66fe\u591a\u6b21\u63d0\u51fa\u8d28\u91cf\u95ee\u9898\u53ca\u5bf9\u65b9\u63a8\u8bff\u3001\u62d2\u7edd\u7684\u8fc7\u7a0b\u3002"}, {"name": "\u7b2c\u4e09\u65b9\u9274\u5b9a\u62a5\u544a\uff08\u6f5c\u5728\u8bc1\u636e\uff09", "type": "\u9274\u5b9a\u610f\u89c1", "description": "\u53ef\u7533\u8bf7\u5177\u6709\u8d44\u8d28\u7684\u9274\u5b9a\u673a\u6784\u5bf9\u88c5\u4fee\u8d28\u91cf\uff08\u7279\u522b\u662f\u9632\u6c34\u5de5\u7a0b\uff09\u662f\u5426\u8fbe\u6807\u8fdb\u884c\u4e13\u4e1a\u9274\u5b9a\u3002"}, {"name": "\u90bb\u5c45\u7684\u8bc1\u8a00\u53ca\u635f\u5931\u51ed\u8bc1", "type": "\u8bc1\u4eba\u8bc1\u8a00/\u4e66\u8bc1", "description": "\u697c\u4e0b\u90bb\u5c45\u5173\u4e8e\u6f0f\u6c34\u7684\u8bc1\u8a00\uff0c\u4ee5\u53ca\u738b\u5148\u751f\u57ab\u4ed8\u7684\u7ef4\u4fee\u8d39\u7528\u6536\u636e\u7b49\u3002"}, {"name": "\u7269\u4e1a\u516c\u53f8\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u53ef\u8bc1\u660e\u6f0f\u6c34\u6295\u8bc9\u3001\u62a5\u4fee\u8bb0\u5f55\u7b49\u60c5\u51b5\u3002"}]', 'audio', '[音频文件: fc774783-5700-4330-84c9-726fb4d91887_测试.mp3]', '2026-03-31 15:48:55.386938+08', '2026-03-31 15:48:55.386938+08');
INSERT INTO "public"."dispute_infos" VALUES ('e934e2cf-9dbf-4cf2-bc4e-cc05461aefa4', '邻里噪音扰民纠纷', '[{"name": "\u738b\u5148\u751f", "role": "\u539f\u544a/\u6295\u8bc9\u65b9", "contact": "\u89c6\u9891\u4e2d\u672a\u63d0\u4f9b\u5177\u4f53\u8054\u7cfb\u65b9\u5f0f"}, {"name": "\u697c\u4e0a\u90bb\u5c45", "role": "\u88ab\u544a/\u88ab\u6295\u8bc9\u65b9", "contact": "\u89c6\u9891\u4e2d\u672a\u63d0\u4f9b\u5177\u4f53\u8054\u7cfb\u65b9\u5f0f"}]', '近三个月内，每日晚间至凌晨时段', '王先生反映，其楼上邻居近三个月来，每日晚间至凌晨时段持续产生巨大噪音，包括但不限于拖动家具、重物坠落、频繁脚步声及喧哗声。该行为严重影响了王先生及其家人的正常休息与生活安宁。王先生曾多次上门沟通，但对方态度恶劣，拒不改正。物业介入调解后，情况仍未改善。', '1. 要求楼上邻居立即停止制造噪音的扰民行为；2. 要求对方就其行为造成的困扰进行口头或书面道歉；3. 如协商不成，保留通过法律途径（如提起相邻关系纠纷诉讼）要求其停止侵害、赔偿精神损害抚慰金的权利。', '[{"name": "\u81ea\u884c\u5f55\u5236\u7684\u566a\u97f3\u97f3\u9891/\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u738b\u5148\u751f\u7528\u624b\u673a\u7b49\u8bbe\u5907\u5728\u81ea\u5bb6\u5c4b\u5185\u5f55\u5236\u7684\uff0c\u80fd\u6e05\u6670\u663e\u793a\u65f6\u95f4\u3001\u5e76\u8bb0\u5f55\u4e0b\u566a\u97f3\u6765\u6e90\uff08\u697c\u4e0a\uff09\u3001\u7c7b\u578b\u53ca\u6301\u7eed\u65f6\u95f4\u7684\u5f55\u97f3\u6216\u5f55\u50cf\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u4e0e\u90bb\u5c45\u6c9f\u901a\u7684\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u8bb0\u5f55\u6216\u901a\u8bdd\u5f55\u97f3\u3002\u82e5\u65e0\uff0c\u5219\u9700\u51c6\u5907\u5173\u4e8e\u6c9f\u901a\u65f6\u95f4\u3001\u5185\u5bb9\u3001\u5bf9\u65b9\u6001\u5ea6\u7684\u8be6\u7ec6\u4e66\u9762\u8bf4\u660e\u3002"}, {"name": "\u7269\u4e1a\u8c03\u89e3\u8bb0\u5f55\u6216\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u5c0f\u533a\u7269\u4e1a\u516c\u53f8\u51fa\u5177\u7684\u8c03\u89e3\u60c5\u51b5\u8bf4\u660e\u3001\u5de5\u4f5c\u8bb0\u5f55\u6216\u8bc1\u660e\u51fd\uff0c\u8bc1\u5b9e\u738b\u5148\u751f\u66fe\u6295\u8bc9\u53ca\u7269\u4e1a\u66fe\u4ecb\u5165\u5904\u7406\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u5176\u4ed6\u53d7\u5f71\u54cd\u90bb\u5c45\u7684\u8bc1\u8a00\uff0c\u8bc1\u660e\u566a\u97f3\u7684\u5b58\u5728\u53ca\u5176\u5f71\u54cd\u3002"}, {"name": "\u4e13\u4e1a\u673a\u6784\u566a\u97f3\u68c0\u6d4b\u62a5\u544a", "type": "\u9274\u5b9a\u610f\u89c1", "description": "\uff08\u5982\u6761\u4ef6\u5141\u8bb8\uff09\u59d4\u6258\u6709\u8d44\u8d28\u7684\u7b2c\u4e09\u65b9\u68c0\u6d4b\u673a\u6784\u5728\u7279\u5b9a\u65f6\u6bb5\u5bf9\u5ba4\u5185\u566a\u97f3\u8fdb\u884c\u68c0\u6d4b\uff0c\u51fa\u5177\u662f\u5426\u8d85\u8fc7\u56fd\u5bb6\u6216\u5730\u65b9\u89c4\u5b9a\u7684\u751f\u6d3b\u566a\u97f3\u6807\u51c6\u7684\u62a5\u544a\u3002"}]', 'video', '[视频文件: bfcf690c-d2a1-4b95-9443-f987852f9ed1_测试视频.mp4]', '2026-03-31 15:49:41.945892+08', '2026-03-31 15:49:41.945892+08');
INSERT INTO "public"."dispute_infos" VALUES ('5137603a-47d7-42f4-b008-f22a456908fa', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u539f\u6587\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u539f\u6587\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}]', '2026年3月31日', '被告张三因个人资金周转向原告李四借款，双方就借款金额、期限及利率达成约定。李四通过银行转账方式向张三交付了借款，张三向李四出具了借条予以确认。借款到期后，张三未按约定偿还本金及支付利息。经李四多次催告，张三仍拖延不还。', '要求被告张三偿还借款本金及按约定利率计算的相应利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u6309\u7ea6\u5b9a\u901a\u8fc7\u8f6c\u8d26\u65b9\u5f0f\u5b9e\u9645\u5411\u88ab\u544a\u5f20\u4e09\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55\uff08\u50ac\u544a\u5185\u5bb9\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u501f\u6b3e\u5230\u671f\u540e\uff0c\u539f\u544a\u674e\u56db\u66fe\u591a\u6b21\u5411\u88ab\u544a\u5f20\u4e09\u8fdb\u884c\u50ac\u544a\uff0c\u88ab\u544a\u5b58\u5728\u8fdd\u7ea6\u4e8b\u5b9e\u3002\u804a\u5929\u8bb0\u5f55\u53ef\u80fd\u540c\u65f6\u4f50\u8bc1\u501f\u6b3e\u4e8b\u5b9e\u3001\u5229\u7387\u7ea6\u5b9a\u6216\u88ab\u544a\u7684\u8fd8\u6b3e\u627f\u8bfa\u3002"}]', 'text', '2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-31 16:41:55.943091+08', '2026-03-31 16:41:55.943091+08');
INSERT INTO "public"."dispute_infos" VALUES ('3aa3cb8a-9a67-4a3d-9ae5-66285113c8cc', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b"}]', '2026年3月31日', '被告张三因个人资金周转向原告李四借款，双方就借款金额、期限及利率达成约定。李四通过银行转账方式向张三交付了借款，张三向李四出具了借条予以确认。借款到期后，张三未按约定偿还借款本金及支付利息。经原告李四多次催告，被告张三仍拖延不还。', '要求被告张三偿还借款本金及自借款之日起至实际清偿之日止的约定利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u6838\u5fc3\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u5173\u952e\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u6309\u7ea6\u5b9a\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\uff0c\u662f\u8bc1\u660e\u501f\u6b3e\u4e8b\u5b9e\u5df2\u5c65\u884c\u7684\u5173\u952e\u8bc1\u636e\u3002"}, {"name": "\u50ac\u6536\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u539f\u544a\u5728\u501f\u6b3e\u5230\u671f\u540e\u66fe\u5411\u88ab\u544a\u8fdb\u884c\u50ac\u544a\uff0c\u53ef\u80fd\u6d89\u53ca\u5bf9\u501f\u6b3e\u4e8b\u5b9e\u3001\u91d1\u989d\u3001\u62d6\u6b20\u60c5\u51b5\u7684\u786e\u8ba4\uff0c\u4ee5\u53ca\u8bc9\u8bbc\u65f6\u6548\u4e2d\u65ad\u7684\u8bc1\u660e\u3002"}]', 'text', '2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-31 16:44:52.876583+08', '2026-03-31 16:44:52.876583+08');
INSERT INTO "public"."dispute_infos" VALUES ('461969b3-4ad6-4747-9a20-7093b13c9e11', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '2026年3月31日', '被告张三因个人资金周转需要，向原告李四借款。双方约定了具体的借款金额、还款期限及借款利率。李四通过银行转账等方式向张三交付了借款，张三随后向李四出具了借条予以确认。借款到期后，张三未按约定偿还借款本金及利息。经原告李四多次催告，被告张三仍以拖延等方式拒绝履行还款义务。', '请求法院判令被告张三立即偿还原告李四借款本金及自借款之日起至实际清偿之日止的约定利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u6309\u7ea6\u5b9a\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\uff0c\u662f\u8bc1\u660e\u501f\u6b3e\u4e8b\u5b9e\u5df2\u5b9e\u9645\u53d1\u751f\u7684\u5173\u952e\u8bc1\u636e\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1/\u77ed\u4fe1\u7b49\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5185\u5bb9\u53ef\u80fd\u5305\u62ec\u501f\u6b3e\u534f\u5546\u8fc7\u7a0b\u3001\u50ac\u544a\u8fd8\u6b3e\u8bb0\u5f55\u7b49\uff0c\u7528\u4e8e\u8f85\u52a9\u8bc1\u660e\u501f\u8d37\u5408\u610f\u3001\u50ac\u544a\u4e8b\u5b9e\u53ca\u88ab\u544a\u62d6\u5ef6\u8fd8\u6b3e\u7684\u610f\u56fe\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u5305\u62ec\u7535\u8bdd\u5f55\u97f3\u3001\u77ed\u4fe1\u3001\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u6216\u8bc1\u4eba\u8bc1\u8a00\u7b49\uff0c\u7528\u4e8e\u8bc1\u660e\u539f\u544a\u5728\u8bc9\u8bbc\u524d\u5df2\u5c65\u884c\u50ac\u544a\u7a0b\u5e8f\u3002"}]', 'text', '2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-31 16:49:26.125799+08', '2026-03-31 16:49:26.125799+08');
INSERT INTO "public"."dispute_infos" VALUES ('bb4afc21-75ea-455a-bb92-a8a2e1268e0f', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '2026年3月31日', '被告张三因个人资金周转向原告李四借款，双方就借款金额、期限及利率达成约定。原告李四通过银行转账方式向被告张三交付了借款，被告张三向原告李四出具了借条予以确认。借款到期后，被告张三未按约定归还借款本金及支付利息。经原告李四多次催告，被告张三仍拖延不还。', '要求被告张三偿还借款本金及按约定利率计算的相应利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u7528\u4ee5\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u7ea6\u5b9a\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u6309\u7ea6\u5b9a\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1/\u77ed\u4fe1\u7b49\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5185\u5bb9\u53ef\u80fd\u6d89\u53ca\u501f\u6b3e\u534f\u5546\u3001\u50ac\u544a\u8fd8\u6b3e\u7b49\u8fc7\u7a0b\uff0c\u7528\u4ee5\u8f85\u52a9\u8bc1\u660e\u501f\u8d37\u4e8b\u5b9e\u3001\u50ac\u544a\u884c\u4e3a\u53ca\u88ab\u544a\u7684\u8fd8\u6b3e\u627f\u8bfa\u6216\u62d6\u5ef6\u60c5\u51b5\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u89c6\u542c\u8d44\u6599/\u7535\u5b50\u6570\u636e/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u8bc1\u660e\u539f\u544a\u5728\u501f\u6b3e\u5230\u671f\u540e\u66fe\u5411\u88ab\u544a\u8fdb\u884c\u8fc7\u6709\u6548\u50ac\u544a\uff08\u5982\u50ac\u6536\u77ed\u4fe1\u3001\u90ae\u4ef6\u3001\u901a\u8bdd\u5f55\u97f3\u6216\u8bc1\u4eba\u8bc1\u8a00\u7b49\uff09\u3002"}]', 'text', '2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-31 16:53:11.207957+08', '2026-03-31 16:53:11.207957+08');
INSERT INTO "public"."dispute_infos" VALUES ('c4871659-2427-4de1-b788-0c046cc1b01a', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u9700\u5728\u8bc9\u8bbc\u6750\u6599\u4e2d\u8865\u5145"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\uff0c\u8054\u7cfb\u65b9\u5f0f\u672a\u63d0\u4f9b\uff0c\u9700\u5728\u8bc9\u8bbc\u6750\u6599\u4e2d\u8865\u5145"}]', '2026年3月31日', '2026年3月31日，被告张三因个人资金周转需要，向原告李四借款。双方就借款金额、期限及利率达成口头或书面约定。当日，李四通过银行转账方式向张三交付了借款。张三收款后，向李四出具了借条，对借款事实予以确认。借款到期后，张三未按约定偿还本金及利息。经李四多次催告，张三仍拖延不还。李四遂向法院提起诉讼。', '原告李四请求法院判令被告张三：1. 立即偿还借款本金；2. 支付自借款之日起至实际清偿之日止的约定利息（需明确利率标准）；3. 承担本案的诉讼费用。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u501f\u6b3e\u4eba\u3001\u51fa\u501f\u4eba\u3001\u501f\u6b3e\u65e5\u671f\u3001\u8fd8\u6b3e\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u65b9\u5f0f\u5b9e\u9645\u5411\u88ab\u544a\u5f20\u4e09\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\uff0c\u662f\u8bc1\u660e\u501f\u6b3e\u5df2\u5b9e\u9645\u5c65\u884c\u7684\u5173\u952e\u8bc1\u636e\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55\uff08\u5fae\u4fe1/\u77ed\u4fe1\u7b49\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u5185\u5bb9\u53ef\u80fd\u5305\u62ec\uff1a1. \u501f\u6b3e\u524d\u7684\u534f\u5546\u8fc7\u7a0b\uff0c\u4f50\u8bc1\u501f\u6b3e\u5408\u610f\u53ca\u7ea6\u5b9a\u7ec6\u8282\uff1b2. \u501f\u6b3e\u5230\u671f\u540e\u7684\u50ac\u6536\u8bb0\u5f55\uff0c\u8bc1\u660e\u539f\u544a\u5df2\u4e3b\u5f20\u6743\u5229\u53ca\u88ab\u544a\u62d6\u5ef6\u8fd8\u6b3e\u7684\u4e8b\u5b9e\uff0c\u53ef\u80fd\u6d89\u53ca\u8bc9\u8bbc\u65f6\u6548\u4e2d\u65ad\u3002"}, {"name": "\u50ac\u544a\u5f55\u97f3/\u5f55\u50cf", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u5982\u5b58\u5728\uff0c\u53ef\u8bc1\u660e\u539f\u544a\u8fdb\u884c\u8fc7\u50ac\u544a\u53ca\u88ab\u544a\u7684\u56de\u5e94\u60c5\u51b5\uff0c\u8f85\u52a9\u8bc1\u660e\u8fdd\u7ea6\u4e8b\u5b9e\u53ca\u8bc9\u8bbc\u65f6\u6548\u4e2d\u65ad\u3002"}, {"name": "\u5f53\u4e8b\u4eba\u8eab\u4efd\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u539f\u544a\u4e0e\u88ab\u544a\u7684\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6\u6216\u6237\u7c4d\u8bc1\u660e\uff0c\u7528\u4e8e\u786e\u8ba4\u8bc9\u8bbc\u4e3b\u4f53\u8d44\u683c\u3002"}]', 'voice', '2026年3月31日，被告人张三因为个人资金周转向原告李四借款。双方约定了借款金额期限以及利率。李四通过转账交付借款之后，张三出具借条确认借款到期后，张三未按照约定归还北京以及利息，经过多次催告，仍然拖延不还。李四于是根据借条转账记录和聊天记录等证据向法院提起诉讼。要求张三偿还借款本金以及相应的利息。', '2026-03-31 16:54:23.964864+08', '2026-03-31 16:54:23.964864+08');
INSERT INTO "public"."dispute_infos" VALUES ('b794b9dd-b023-4489-afa0-e7694f7fb5a3', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u539f\u6587\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u539f\u6587\u4fe1\u606f\u7f3a\u5931\uff0c\u9700\u8865\u5145"}]', '2026年3月31日', '被告张三因个人资金周转向原告李四借款，双方就借款金额、期限及利率达成约定。李四通过银行转账方式向张三交付了借款，张三向李四出具了借条予以确认。借款到期后，张三未按约定偿还本金及支付利息。经原告李四多次催告，被告张三仍拖延不还。', '请求法院判令被告张三偿还原告李四借款本金及自借款之日起至实际清偿之日止的约定利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u6309\u7ea6\u5b9a\u901a\u8fc7\u94f6\u884c\u8f6c\u8d26\u65b9\u5f0f\u5411\u88ab\u544a\u5f20\u4e09\u5b9e\u9645\u4ea4\u4ed8\u4e86\u501f\u6b3e\u672c\u91d1\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55\uff08\u50ac\u544a\u8bb0\u5f55\uff09", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u501f\u6b3e\u5230\u671f\u540e\uff0c\u539f\u544a\u674e\u56db\u66fe\u591a\u6b21\u5411\u88ab\u544a\u5f20\u4e09\u8fdb\u884c\u50ac\u544a\uff0c\u4ee5\u53ca\u88ab\u544a\u62d6\u5ef6\u8fd8\u6b3e\u7684\u4e8b\u5b9e\u3002"}]', 'text', '2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额、期限及利率，李四通过转账交付借款后，张三出具借条确认。借款到期后，张三未按约定归还本金及利息，经多次催告仍拖延不还，李四遂依据借条、转账记录及聊天记录等证据，向法院提起诉讼，要求张三偿还借款本金及相应利息。', '2026-03-31 17:04:48.472531+08', '2026-03-31 17:04:48.472531+08');
INSERT INTO "public"."dispute_infos" VALUES ('01b14c97-79c5-4406-b98d-f644e6d0cf2b', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b"}]', '2026年3月31日', '2026年3月31日，被告张三因个人资金周转需要，向原告李四借款。双方就借款金额、期限及利率达成口头或书面约定。当日，原告李四通过银行转账方式向被告张三交付了借款。被告张三随后向原告李四出具了借条，对借款事实、金额、期限及利率等予以确认。借款到期后，被告张三未按约定偿还借款本金及利息。经原告李四多次催告，被告张三至今仍未履行还款义务。', '原告李四请求法院判令被告张三立即偿还全部借款本金，并支付自借款之日起至实际清偿之日止的约定利息（或法定利息）。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u88ab\u544a\u5f20\u4e09\u51fa\u5177\u7684\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u3001\u501f\u6b3e\u4eba\u53ca\u51fa\u501f\u4eba\u7b49\u4fe1\u606f\u7684\u4e66\u9762\u51ed\u8bc1\u3002"}, {"name": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u4e8e\u7ea6\u5b9a\u65f6\u95f4\u901a\u8fc7\u94f6\u884c\u5411\u88ab\u544a\u5f20\u4e09\u8d26\u6237\u652f\u4ed8\u501f\u6b3e\u6b3e\u9879\u7684\u8bb0\u5f55\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u53cc\u65b9\u5c31\u501f\u6b3e\u4e8b\u5b9c\u8fdb\u884c\u6c9f\u901a\u3001\u50ac\u6536\u7b49\u5185\u5bb9\u7684\u5373\u65f6\u901a\u8baf\u8f6f\u4ef6\uff08\u5982\u5fae\u4fe1\u3001\u77ed\u4fe1\uff09\u8bb0\u5f55\uff0c\u53ef\u7528\u4e8e\u4f50\u8bc1\u501f\u6b3e\u5408\u610f\u3001\u50ac\u544a\u4e8b\u5b9e\u7b49\u3002"}, {"name": "\u50ac\u6536\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u8bc1\u660e\u539f\u544a\u66fe\u591a\u6b21\u5411\u88ab\u544a\u8fdb\u884c\u50ac\u6536\u7684\u8bc1\u636e\uff0c\u5982\u50ac\u6536\u77ed\u4fe1\u3001\u90ae\u4ef6\u3001\u901a\u8bdd\u5f55\u97f3\u6216\u76f8\u5173\u8bc1\u4eba\u8bc1\u8a00\u3002"}]', 'voice', '2026年3月31日，被告人张三因为个人资金周转向原告李四借款，双方约定了借款金额期限以及利率，李四通过转账交付借款。之后，张三出具借条进行确认，借款到期后，张三未按照约定归还北金以及利息。经过多次催。告，仍然拖欠不还。李四于是依据借条转账记录和聊天记录等依据向法院提起诉讼，要求张三偿还借款本金以及相应的利息。', '2026-03-31 17:11:53.453791+08', '2026-03-31 17:11:53.453791+08');
INSERT INTO "public"."dispute_infos" VALUES ('4edee6ef-d48d-405a-bace-c389702ea104', '房屋租赁合同纠纷', '[{"name": "\u5f20\u4e09", "role": "\u539f\u544a", "contact": "13800138000"}, {"name": "\u674e\u56db", "role": "\u88ab\u544a", "contact": "13900139000"}]', '2023年5月1日', '原告张三与被告李四于2023年5月1日签订房屋租赁合同，约定张三将其名下位于XX市XX区XX路XX号XX室的房屋出租给李四，租期一年，月租金5000元，押一付三。合同签订后，李四支付了首期租金及押金共计20000元。2023年8月1日，李四应支付下一季度租金时，以房屋存在漏水问题、影响居住为由拒绝支付，并要求张三退还押金及未到期租金。张三认为漏水问题轻微，已联系维修，李四以此为由拒付租金构成违约，要求李四继续履行合同并支付拖欠租金。双方协商未果。', '原告张三的诉求：1. 判令被告李四支付拖欠的2023年8月至10月租金共计15000元；2. 判令被告李四继续履行《房屋租赁合同》；3. 本案诉讼费用由被告承担。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u3001\u88ab\u544a\u4e4b\u95f4\u5b58\u5728\u5408\u6cd5\u6709\u6548\u7684\u623f\u5c4b\u79df\u8d41\u6cd5\u5f8b\u5173\u7cfb\uff0c\u7ea6\u5b9a\u4e86\u79df\u91d1\u3001\u79df\u671f\u3001\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u7b49\u6838\u5fc3\u6761\u6b3e\u3002"}, {"name": "\u79df\u91d1\u53ca\u62bc\u91d1\u6536\u636e/\u8f6c\u8d26\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u88ab\u544a\u5df2\u652f\u4ed8\u9996\u671f\u79df\u91d1\u53ca\u62bc\u91d1\uff0c\u4ee5\u53ca\u540e\u7eed\u79df\u91d1\u652f\u4ed8\u60c5\u51b5\uff0c\u7528\u4e8e\u8ba1\u7b97\u62d6\u6b20\u91d1\u989d\u3002"}, {"name": "\u5173\u4e8e\u623f\u5c4b\u6f0f\u6c34\u95ee\u9898\u7684\u6c9f\u901a\u8bb0\u5f55\uff08\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u3001\u90ae\u4ef6\u6216\u901a\u8bdd\u5f55\u97f3\uff09", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u88ab\u544a\u66fe\u5c31\u623f\u5c4b\u6f0f\u6c34\u95ee\u9898\u5411\u539f\u544a\u63d0\u51fa\u5f02\u8bae\uff0c\u4ee5\u53ca\u539f\u544a\u5bf9\u6b64\u95ee\u9898\u7684\u56de\u5e94\u548c\u5904\u7406\u8fc7\u7a0b\u3002"}, {"name": "\u7ef4\u4fee\u8bb0\u5f55\u6216\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5728\u88ab\u544a\u63d0\u51fa\u6f0f\u6c34\u95ee\u9898\u540e\uff0c\u5df2\u91c7\u53d6\u5b9e\u9645\u7ef4\u4fee\u63aa\u65bd\u3002"}, {"name": "\u50ac\u544a\u652f\u4ed8\u79df\u91d1\u7684\u901a\u77e5", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u66fe\u5411\u88ab\u544a\u6b63\u5f0f\u50ac\u544a\u652f\u4ed8\u62d6\u6b20\u79df\u91d1\u3002"}]', 'image', '[图片文件: 823d5c63-9304-4773-979c-24a614686745_图片.png]', '2026-03-31 17:14:16.461424+08', '2026-03-31 17:14:16.461424+08');
INSERT INTO "public"."dispute_infos" VALUES ('fb27a1fa-3113-4d45-8340-4e6d9945be0c', '劳务报酬支付纠纷', '[{"name": "\u5b59\u67d0", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5434\u67d0", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '2026年3月31日', '被告吴某因装修工程需要，于2026年3月31日雇佣原告孙某提供劳务。双方就劳务报酬及支付时间达成约定。原告孙某按约定完成了全部工作，但被告吴某在原告完成工作后，以各种理由拒绝支付约定的劳务费。原告孙某多次与被告沟通并催告，被告仍拖延支付。', '原告孙某要求被告吴某支付拖欠的劳务报酬，并支付自应付款之日起至实际付清之日止的逾期付款损失（如利息等）。', '[{"name": "\u52b3\u52a1\u7ed3\u7b97\u5355", "type": "\u4e66\u8bc1", "description": "\u8bb0\u8f7d\u4e86\u52b3\u52a1\u5185\u5bb9\u3001\u5de5\u4f5c\u91cf\u3001\u62a5\u916c\u91d1\u989d\u53ca\u652f\u4ed8\u65f6\u95f4\u7b49\u7ed3\u7b97\u4fe1\u606f\u7684\u5355\u636e\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u53cc\u65b9\u5c31\u96c7\u4f63\u5173\u7cfb\u3001\u5de5\u4f5c\u5185\u5bb9\u3001\u62a5\u916c\u6807\u51c6\u3001\u50ac\u6b3e\u8fc7\u7a0b\u7b49\u8fdb\u884c\u6c9f\u901a\u7684\u8bb0\u5f55\uff08\u5982\u5fae\u4fe1\u3001\u77ed\u4fe1\u7b49\uff09\u3002"}, {"name": "\u73b0\u573a\u5de5\u4f5c\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u89c6\u542c\u8d44\u6599", "description": "\u8bb0\u5f55\u539f\u544a\u5b59\u67d0\u5728\u88c5\u4fee\u73b0\u573a\u63d0\u4f9b\u52b3\u52a1\u8fc7\u7a0b\u3001\u5de5\u4f5c\u8fdb\u5ea6\u7684\u6587\u4ef6\u3001\u7167\u7247\u6216\u89c6\u9891\u7b49\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u539f\u544a\u5411\u88ab\u544a\u50ac\u8ba8\u52b3\u52a1\u8d39\u7684\u7535\u8bdd\u5f55\u97f3\u3001\u77ed\u4fe1\u3001\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u6216\u4e66\u9762\u50ac\u544a\u51fd\u7b49\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u4e86\u89e3\u96c7\u4f63\u5173\u7cfb\u3001\u5de5\u4f5c\u5b8c\u6210\u60c5\u51b5\u6216\u50ac\u6b3e\u8fc7\u7a0b\u7684\u5176\u4ed6\u4eba\u5458\uff08\u5982\u5de5\u5730\u5176\u4ed6\u5de5\u4eba\u3001\u4e1a\u4e3b\u7b49\uff09\u7684\u8bc1\u8a00\u3002"}]', 'text', '2026 年 3 月 31 日，被告吴某因装修工程需要，雇佣原告孙某提供劳务，双方约定了劳务报酬及支付时间。原告按要求完成全部工作后，被告以各种理由拒不支付劳务费，经多次沟通催告仍拖延不付。原告遂持劳务结算单、聊天记录及现场工作记录等证据向法院起诉，要求被告支付劳务报酬及相应逾期损失。', '2026-03-31 17:10:45.136753+08', '2026-03-31 17:10:45.136753+08');
INSERT INTO "public"."dispute_infos" VALUES ('bddfab98-deb5-4a97-b650-43ca4d2af30d', '健身房私教课程服务质量纠纷', '[{"name": "\u5f20\u660e", "role": "\u539f\u544a", "contact": "138****1234\uff08\u89c6\u9891\u4e2d\u663e\u793a\uff09"}, {"name": "\u5353\u8d8a\u5065\u8eab\u4e2d\u5fc3", "role": "\u88ab\u544a", "contact": "\u573a\u9986\u5730\u5740\uff1aXX\u8defXX\u53f7"}]', '2023年10月至2024年1月', '原告张明于2023年10月在被告卓越健身中心购买价值8000元的私人教练课程包。在课程进行过程中，张明认为指派的教练频繁更换、训练计划不专业且与其健身目标不符，多次沟通后未改善。2024年1月，张明提出终止合同并退还剩余课程费用，遭健身房以“课程协议中规定不予退款”为由拒绝。', '原告张明要求解除私教课程服务合同，并由被告卓越健身中心退还剩余未上课时费用共计人民币4800元。', '[{"name": "\u300a\u79c1\u4eba\u6559\u7ec3\u8bfe\u7a0b\u534f\u8bae\u300b", "type": "\u4e66\u8bc1", "description": "\u8f7d\u660e\u8bfe\u7a0b\u4ef7\u683c\u3001\u8bfe\u65f6\u3001\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u7684\u5408\u540c\u6587\u4ef6\u3002"}, {"name": "\u8bfe\u7a0b\u5b89\u6392\u4e0e\u6c9f\u901a\u5fae\u4fe1\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u6559\u7ec3\u9891\u7e41\u66f4\u6362\u3001\u539f\u544a\u63d0\u51fa\u8d28\u7591\u53ca\u534f\u5546\u8fc7\u7a0b\u7684\u804a\u5929\u8bb0\u5f55\u3002"}, {"name": "\u4ed8\u6b3e\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\uff0c\u8bc1\u660e\u652f\u4ed8\u4e868000\u5143\u8bfe\u7a0b\u8d39\u7528\u3002"}, {"name": "\u73b0\u573a\u8bfe\u7a0b\u5f55\u50cf\u7247\u6bb5", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u89c6\u9891\u4e2d\u53ef\u80fd\u5305\u542b\u7684\u8bfe\u7a0b\u73b0\u573a\u60c5\u51b5\uff0c\u7528\u4ee5\u4f50\u8bc1\u6559\u7ec3\u4e13\u4e1a\u6027\u7b49\u95ee\u9898\u3002"}]', 'video', '[视频文件: 50acec7e-5740-4774-90bd-5b25da652350_测试视频.mp4]', '2026-03-31 17:13:36.43379+08', '2026-03-31 17:13:36.43379+08');
INSERT INTO "public"."dispute_infos" VALUES ('5851ac7b-4254-4f4f-8aa6-dc596184a784', '房屋装修质量纠纷', '[{"name": "\u738b\u5148\u751f", "role": "\u539f\u544a", "contact": "138****1234"}, {"name": "\u674e\u7ecf\u7406", "role": "\u88ab\u544a", "contact": "\u88c5\u4fee\u516c\u53f8\u9879\u76ee\u7ecf\u7406\uff0c\u516c\u53f8\u7535\u8bdd\uff1a400-xxx-xxxx"}]', '2023年10月签订合同，2024年1月完工验收时发现问题', '王先生于2023年10月与某装修公司签订全包装修合同，由其项目经理李经理负责施工。合同约定工期3个月，预算20万元。施工过程中，王先生发现多处问题：1. 墙面涂料存在明显色差与不平整；2. 卫生间地砖空鼓率超过国家标准；3. 定制橱柜尺寸与设计图纸不符，导致无法正常安装电器；4. 水电隐蔽工程未按规范施工，部分线路未穿管保护。王先生多次向李经理反映，对方起初承诺维修，但拖延数月后仅进行表面修补，根本问题未解决。双方多次协商未果，矛盾激化。', '王先生要求：1. 装修公司对不合格工程进行彻底返工，达到合同约定的质量标准；2. 赔偿因工期延误和维修导致的在外租房费用，共计3个月，每月5000元；3. 承担本次纠纷产生的鉴定费用；4. 若无法达成一致，要求解除合同并返还已支付的全部工程款18万元，并赔偿相应损失。', '[{"name": "\u300a\u5bb6\u5ead\u5c45\u5ba4\u88c5\u9970\u88c5\u4fee\u5de5\u7a0b\u65bd\u5de5\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u660e\u786e\u7ea6\u5b9a\u4e86\u5de5\u7a0b\u4ef7\u6b3e\u3001\u5de5\u671f\u3001\u8d28\u91cf\u6807\u51c6\u3001\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u53ca\u8fdd\u7ea6\u8d23\u4efb\u3002"}, {"name": "\u8bbe\u8ba1\u56fe\u7eb8\u3001\u9884\u7b97\u660e\u7ec6\u5355", "type": "\u4e66\u8bc1", "description": "\u5305\u542b\u5177\u4f53\u7684\u65bd\u5de5\u65b9\u6848\u3001\u6750\u6599\u54c1\u724c\u578b\u53f7\u3001\u6a71\u67dc\u5c3a\u5bf8\u56fe\u7b49\uff0c\u662f\u9a8c\u6536\u7684\u4f9d\u636e\u3002"}, {"name": "\u5de5\u7a0b\u6b3e\u652f\u4ed8\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u3001\u6536\u636e\u7b49\uff0c\u8bc1\u660e\u738b\u5148\u751f\u5df2\u652f\u4ed818\u4e07\u5143\u5de5\u7a0b\u6b3e\u3002"}, {"name": "\u73b0\u573a\u7167\u7247\u4e0e\u89c6\u9891", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599", "description": "\u6e05\u6670\u8bb0\u5f55\u4e86\u5899\u9762\u8272\u5dee\u3001\u5730\u7816\u7a7a\u9f13\u3001\u6a71\u67dc\u5c3a\u5bf8\u4e0d\u7b26\u3001\u6c34\u7535\u7ebf\u8def\u672a\u7a7f\u7ba1\u7b49\u8d28\u91cf\u95ee\u9898\u7684\u73b0\u72b6\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u4e0e\u674e\u7ecf\u7406\u53ca\u88c5\u4fee\u516c\u53f8\u7684\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u3001\u90ae\u4ef6\u6216\u901a\u8bdd\u5f55\u97f3\uff0c\u8bc1\u660e\u738b\u5148\u751f\u5df2\u591a\u6b21\u63d0\u51fa\u8d28\u91cf\u95ee\u9898\u53ca\u5bf9\u65b9\u62d6\u5ef6\u5904\u7406\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u7b2c\u4e09\u65b9\u9274\u5b9a\u62a5\u544a", "type": "\u9274\u5b9a\u610f\u89c1", "description": "\u5efa\u8bae\u59d4\u6258\u5177\u6709\u8d44\u8d28\u7684\u5de5\u7a0b\u8d28\u91cf\u68c0\u6d4b\u673a\u6784\u5bf9\u88c5\u4fee\u8d28\u91cf\uff08\u5982\u7a7a\u9f13\u7387\u3001\u9632\u6c34\u3001\u7535\u8def\u5b89\u5168\u7b49\uff09\u8fdb\u884c\u53f8\u6cd5\u9274\u5b9a\uff0c\u51fa\u5177\u4e66\u9762\u62a5\u544a\u3002"}, {"name": "\u79df\u623f\u5408\u540c\u53ca\u4ed8\u6b3e\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u56e0\u623f\u5c4b\u65e0\u6cd5\u5165\u4f4f\u800c\u4ea7\u751f\u7684\u5b9e\u9645\u79df\u91d1\u635f\u5931\u3002"}]', 'audio', '[音频文件: 2359c9cf-3d4d-45d4-a5e5-39436224d8fc_测试.mp3]', '2026-03-31 17:12:38.808111+08', '2026-03-31 17:12:38.808111+08');
INSERT INTO "public"."dispute_infos" VALUES ('c7bb1b78-e3d9-422c-bb2f-dcea1cc3e7d3', '纠纷信息', '[]', '', '比如开始整理，整理出来了什么内容，比如维权路线，规划了什么路线什么路径，比如流程提醒，都有哪些需要注意的点', '', '[]', 'text', '比如开始整理，整理出来了什么内容，比如维权路线，规划了什么路线什么路径，比如流程提醒，都有哪些需要注意的点', '2026-03-31 22:18:18.904077+08', '2026-03-31 22:18:18.904077+08');
INSERT INTO "public"."dispute_infos" VALUES ('06874c95-48bc-423e-a1d8-4bf14e18ecab', '劳务报酬拖欠纠纷', '[{"name": "\u5b59\u67d0", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5434\u67d0", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '信息缺失（需补充具体劳务提供及付款期限届满时间）', '被告吴某因装修工程雇佣原告孙某提供劳务，双方就报酬标准、支付期限达成明确约定。原告孙某依约完成全部工作且成果符合要求。付款期限届满后，被告吴某无正当理由拒不支付报酬，虽经原告多次沟通及书面催告，仍拖延拒付，构成违约。', '1. 判令被告吴某支付拖欠的劳务报酬；2. 判令被告吴某赔偿相应的逾期付款损失。', '[{"name": "\u52b3\u52a1\u7ed3\u7b97\u5355", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u53cc\u65b9\u7ea6\u5b9a\u7684\u52b3\u52a1\u5185\u5bb9\u3001\u62a5\u916c\u6807\u51c6\u3001\u652f\u4ed8\u671f\u9650\u53ca\u6700\u7ec8\u7ed3\u7b97\u91d1\u989d\u3002"}, {"name": "\u6c9f\u901a\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u53cc\u65b9\u5c31\u96c7\u4f63\u4e8b\u5b9c\u3001\u5de5\u4f5c\u5185\u5bb9\u3001\u62a5\u916c\u652f\u4ed8\u8fdb\u884c\u6c9f\u901a\uff0c\u4ee5\u53ca\u539f\u544a\u8fdb\u884c\u50ac\u544a\u3001\u88ab\u544a\u62d6\u5ef6\u652f\u4ed8\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u73b0\u573a\u65bd\u5de5\u5de5\u4f5c\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u539f\u544a\u5df2\u4f9d\u7ea6\u5b8c\u6210\u5168\u90e8\u52b3\u52a1\u5de5\u4f5c\uff0c\u4e14\u5de5\u4f5c\u6210\u679c\u7b26\u5408\u7ea6\u5b9a\u8981\u6c42\u3002"}, {"name": "\u4e66\u9762\u50ac\u544a\u51fd\u53ca\u9001\u8fbe\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5728\u8d77\u8bc9\u524d\u5df2\u5c65\u884c\u50ac\u544a\u7a0b\u5e8f\uff0c\u88ab\u544a\u7ecf\u50ac\u544a\u540e\u4ecd\u4e0d\u5c65\u884c\u4ed8\u6b3e\u4e49\u52a1\u3002"}]', 'text', '原告孙某与被告吴某达成劳务合意，被告吴某因装修工程事宜，雇佣原告孙某提供劳务，双方就劳务报酬标准、支付期限达成明确约定。
原告孙某依约完成全部劳务工作，且劳务成果符合双方约定要求，已全面履行劳务义务。
付款期限届满后，被告吴某无正当理由，拒不支付约定的劳务报酬，经原告孙某多次沟通、书面催告，被告仍拖延拒付，构成违约。
原告孙某为维护自身合法权益，持劳务结算单、沟通聊天记录、现场施工工作记录等相关证据，依法向人民法院提起诉讼，诉请判令被告吴某支付拖欠的劳务报酬，并赔偿相应逾期付款损失。', '2026-03-31 23:41:51.448492+08', '2026-03-31 23:41:51.448492+08');
INSERT INTO "public"."dispute_infos" VALUES ('f23b373d-ae68-4fba-a159-9b27494aef58', '劳务报酬拖欠纠纷', '[{"name": "\u5b59\u67d0", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5434\u67d0", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '信息缺失（需补充具体劳务提供及付款期限届满时间）', '被告吴某因装修工程雇佣原告孙某提供劳务，双方就报酬标准、支付期限达成明确约定。原告孙某依约完成全部工作且成果符合要求。付款期限届满后，被告吴某无正当理由拒不支付报酬，虽经原告多次沟通及书面催告，仍拖延拒付，构成违约。', '1. 判令被告吴某支付拖欠的劳务报酬；2. 判令被告吴某赔偿相应的逾期付款损失。', '[{"name": "\u52b3\u52a1\u7ed3\u7b97\u5355", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u53cc\u65b9\u7ea6\u5b9a\u7684\u52b3\u52a1\u5185\u5bb9\u3001\u62a5\u916c\u6807\u51c6\u3001\u652f\u4ed8\u671f\u9650\u53ca\u6700\u7ec8\u7ed3\u7b97\u91d1\u989d\u3002"}, {"name": "\u6c9f\u901a\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u53cc\u65b9\u5c31\u96c7\u4f63\u4e8b\u5b9c\u3001\u5de5\u4f5c\u5185\u5bb9\u3001\u62a5\u916c\u652f\u4ed8\u8fdb\u884c\u6c9f\u901a\uff0c\u4ee5\u53ca\u539f\u544a\u8fdb\u884c\u50ac\u544a\u3001\u88ab\u544a\u62d6\u5ef6\u652f\u4ed8\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u73b0\u573a\u65bd\u5de5\u5de5\u4f5c\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u539f\u544a\u5df2\u4f9d\u7ea6\u5b8c\u6210\u52b3\u52a1\u5de5\u4f5c\uff0c\u4e14\u5de5\u4f5c\u6210\u679c\u7b26\u5408\u8981\u6c42\u3002"}, {"name": "\u4e66\u9762\u50ac\u544a\u51fd\u53ca\u9001\u8fbe\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5df2\u5c31\u62d6\u6b20\u62a5\u916c\u4e8b\u5b9c\u5411\u88ab\u544a\u8fdb\u884c\u6b63\u5f0f\u50ac\u544a\u3002"}]', 'text', '原告孙某与被告吴某达成劳务合意，被告吴某因装修工程事宜，雇佣原告孙某提供劳务，双方就劳务报酬标准、支付期限达成明确约定。
原告孙某依约完成全部劳务工作，且劳务成果符合双方约定要求，已全面履行劳务义务。
付款期限届满后，被告吴某无正当理由，拒不支付约定的劳务报酬，经原告孙某多次沟通、书面催告，被告仍拖延拒付，构成违约。
原告孙某为维护自身合法权益，持劳务结算单、沟通聊天记录、现场施工工作记录等相关证据，依法向人民法院提起诉讼，诉请判令被告吴某支付拖欠的劳务报酬，并赔偿相应逾期付款损失。', '2026-04-01 14:10:21.00352+08', '2026-04-01 14:10:21.00352+08');
INSERT INTO "public"."dispute_infos" VALUES ('78813e0b-40b3-4514-9ca9-be44d6e76a45', '劳务报酬拖欠纠纷', '[{"name": "\u5b59\u67d0", "role": "\u539f\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}, {"name": "\u5434\u67d0", "role": "\u88ab\u544a", "contact": "\u4fe1\u606f\u7f3a\u5931\uff08\u9700\u8865\u5145\uff09"}]', '信息缺失（需补充具体劳务提供及付款期限届满时间）', '被告吴某因装修工程雇佣原告孙某提供劳务，双方就报酬标准、支付期限达成明确约定。原告孙某依约完成全部工作且成果符合要求。付款期限届满后，被告吴某无正当理由拒不支付报酬，经原告多次沟通及书面催告后仍拖延拒付，构成违约。', '1. 判令被告吴某支付拖欠的劳务报酬；2. 判令被告吴某赔偿相应的逾期付款损失。', '[{"name": "\u52b3\u52a1\u7ed3\u7b97\u5355", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u53cc\u65b9\u7ea6\u5b9a\u7684\u52b3\u52a1\u62a5\u916c\u6807\u51c6\u3001\u652f\u4ed8\u671f\u9650\u53ca\u6700\u7ec8\u7ed3\u7b97\u91d1\u989d\u3002"}, {"name": "\u6c9f\u901a\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u53cc\u65b9\u5b58\u5728\u96c7\u4f63\u5408\u610f\u3001\u539f\u544a\u50ac\u544a\u8fc7\u7a0b\u53ca\u88ab\u544a\u62d6\u5ef6\u4ed8\u6b3e\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u73b0\u573a\u65bd\u5de5\u5de5\u4f5c\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u539f\u544a\u5df2\u4f9d\u7ea6\u5b8c\u6210\u5168\u90e8\u52b3\u52a1\u5de5\u4f5c\u4e14\u6210\u679c\u7b26\u5408\u8981\u6c42\u3002"}, {"name": "\u4e66\u9762\u50ac\u544a\u51fd\u53ca\u9001\u8fbe\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5df2\u5c65\u884c\u50ac\u544a\u7a0b\u5e8f\u3002"}]', 'text', '原告孙某与被告吴某达成劳务合意，被告吴某因装修工程事宜，雇佣原告孙某提供劳务，双方就劳务报酬标准、支付期限达成明确约定。
原告孙某依约完成全部劳务工作，且劳务成果符合双方约定要求，已全面履行劳务义务。
付款期限届满后，被告吴某无正当理由，拒不支付约定的劳务报酬，经原告孙某多次沟通、书面催告，被告仍拖延拒付，构成违约。
原告孙某为维护自身合法权益，持劳务结算单、沟通聊天记录、现场施工工作记录等相关证据，依法向人民法院提起诉讼，诉请判令被告吴某支付拖欠的劳务报酬，并赔偿相应逾期付款损失。', '2026-04-01 14:51:14.132361+08', '2026-04-01 14:51:14.132361+08');
INSERT INTO "public"."dispute_infos" VALUES ('303408e7-54b3-4106-9eb5-f632dd5abcf9', '劳务报酬支付纠纷', '[{"name": "\u5b59\u67d0", "role": "\u539f\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b\uff0c\u9700\u8865\u5145"}, {"name": "\u5434\u67d0", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b\uff0c\u9700\u8865\u5145"}]', '2026年3月31日', '被告吴某因装修工程需要，于2026年3月31日雇佣原告孙某提供劳务，双方约定了劳务报酬及支付时间。原告孙某按约定完成了全部工作。工作完成后，被告吴某以各种理由拒绝支付劳务费。原告孙某经多次沟通和催告，被告吴某仍拖延支付。', '原告孙某要求被告吴某支付拖欠的劳务报酬，并支付相应的逾期付款损失（如利息等）。', '[{"name": "\u52b3\u52a1\u7ed3\u7b97\u5355", "type": "\u4e66\u8bc1", "description": "\u8bb0\u8f7d\u4e86\u52b3\u52a1\u5185\u5bb9\u3001\u5de5\u4f5c\u91cf\u3001\u62a5\u916c\u91d1\u989d\u53ca\u652f\u4ed8\u7ea6\u5b9a\u7684\u4e66\u9762\u6587\u4ef6\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u53cc\u65b9\u5c31\u96c7\u4f63\u5173\u7cfb\u3001\u5de5\u4f5c\u5185\u5bb9\u3001\u62a5\u916c\u6807\u51c6\u3001\u50ac\u6b3e\u8fc7\u7a0b\u7b49\u8fdb\u884c\u6c9f\u901a\u7684\u8bb0\u5f55\uff0c\u53ef\u8bc1\u660e\u5408\u540c\u5173\u7cfb\u53ca\u8fdd\u7ea6\u4e8b\u5b9e\u3002"}, {"name": "\u73b0\u573a\u5de5\u4f5c\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u89c6\u542c\u8d44\u6599", "description": "\u8bb0\u5f55\u539f\u544a\u5b8c\u6210\u5de5\u4f5c\u7684\u8fc7\u7a0b\u3001\u65f6\u95f4\u3001\u6210\u679c\u7b49\uff0c\u7528\u4ee5\u8bc1\u660e\u539f\u544a\u5df2\u5c65\u884c\u5408\u540c\u4e49\u52a1\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u539f\u544a\u591a\u6b21\u5411\u88ab\u544a\u50ac\u8ba8\u52b3\u52a1\u8d39\u7684\u8bb0\u5f55\uff08\u5982\u77ed\u4fe1\u3001\u5fae\u4fe1\u3001\u90ae\u4ef6\u3001\u901a\u8bdd\u5f55\u97f3\u6216\u8bc1\u4eba\u8bc1\u8a00\uff09\uff0c\u7528\u4ee5\u8bc1\u660e\u539f\u544a\u4e3b\u5f20\u6743\u5229\u53ca\u88ab\u544a\u62d6\u5ef6\u7684\u4e8b\u5b9e\u3002"}]', 'text', '2026 年 3 月 31 日，被告吴某因装修工程需要，雇佣原告孙某提供劳务，双方约定了劳务报酬及支付时间。原告按要求完成全部工作后，被告以各种理由拒不支付劳务费，经多次沟通催告仍拖延不付。原告遂持劳务结算单、聊天记录及现场工作记录等证据向法院起诉，要求被告支付劳务报酬及相应逾期损失。', '2026-04-01 18:18:17.673362+08', '2026-04-01 18:18:17.673362+08');
INSERT INTO "public"."dispute_infos" VALUES ('aa8a9ee8-a9d3-4ddc-87f7-a7aeae8271c5', '民间借贷纠纷', '[{"name": "\u674e\u56db", "role": "\u539f\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b\uff0c\u9700\u8865\u5145"}, {"name": "\u5f20\u4e09", "role": "\u88ab\u544a", "contact": "\u6839\u636e\u6848\u60c5\u4fe1\u606f\u672a\u63d0\u4f9b\uff0c\u9700\u8865\u5145"}]', '2026年3月31日', '被告张三因个人资金周转需要，向原告李四借款。双方约定了具体的借款金额、借款期限及借款利率。李四通过银行转账等方式向张三交付了借款，张三向李四出具了借条予以确认。借款到期后，张三未按约定归还借款本金及支付利息。经李四多次催告，张三仍拖欠不还。', '原告李四请求法院判令被告张三偿还借款本金及按约定利率计算的相应利息。', '[{"name": "\u501f\u6761", "type": "\u4e66\u8bc1", "description": "\u7531\u88ab\u544a\u5f20\u4e09\u51fa\u5177\uff0c\u8f7d\u660e\u501f\u6b3e\u91d1\u989d\u3001\u671f\u9650\u3001\u5229\u7387\u7b49\u5173\u952e\u6761\u6b3e\uff0c\u662f\u8bc1\u660e\u501f\u8d37\u5408\u610f\u53ca\u5177\u4f53\u5185\u5bb9\u7684\u6838\u5fc3\u8bc1\u636e\u3002"}, {"name": "\u8f6c\u8d26\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u674e\u56db\u5df2\u5b9e\u9645\u5411\u88ab\u544a\u5f20\u4e09\u4ea4\u4ed8\u501f\u6b3e\u672c\u91d1\uff0c\u662f\u8bc1\u660e\u501f\u6b3e\u4e8b\u5b9e\u5df2\u53d1\u751f\u7684\u5173\u952e\u5c65\u884c\u8bc1\u636e\u3002"}, {"name": "\u804a\u5929\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e", "description": "\u53ef\u80fd\u5305\u542b\u53cc\u65b9\u534f\u5546\u501f\u6b3e\u3001\u786e\u8ba4\u6761\u6b3e\u3001\u50ac\u6536\u6b20\u6b3e\u7b49\u8fc7\u7a0b\u7684\u6c9f\u901a\u5185\u5bb9\uff0c\u7528\u4e8e\u4f50\u8bc1\u501f\u8d37\u4e8b\u5b9e\u3001\u50ac\u544a\u8fc7\u7a0b\u53ca\u88ab\u544a\u7684\u8fdd\u7ea6\u60c5\u51b5\u3002"}, {"name": "\u50ac\u544a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u89c6\u542c\u8d44\u6599/\u8bc1\u4eba\u8bc1\u8a00", "description": "\u8bc1\u660e\u539f\u544a\u5728\u8bc9\u8bbc\u524d\u5df2\u5411\u88ab\u544a\u8fdb\u884c\u8fc7\u6709\u6548\u50ac\u544a\uff0c\u53ef\u80fd\u5305\u62ec\u77ed\u4fe1\u3001\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u7535\u5b50\u90ae\u4ef6\u3001\u901a\u8bdd\u5f55\u97f3\u6216\u8bc1\u4eba\u8bc1\u8a00\u7b49\u3002"}]', 'voice', '2026年3月31日，被告张三因个人资金周转向原告李四借款，双方约定了借款金额期限以及利率。李斯通过转账交付借款后，张三出具借条确认。结款到期后，张三未按照定期归还本金以及利息，经过多次催告之后仍然拖欠不还。李四于是根据借条转账记录和聊天记录等证据向法院提起诉讼。要求张三偿还本金以及相应的利息。', '2026-04-01 18:19:36.53213+08', '2026-04-01 18:19:36.53213+08');
INSERT INTO "public"."dispute_infos" VALUES ('a83c65ed-a878-4f54-b590-54e4a470e9bf', '房屋装修质量纠纷', '[{"name": "\u738b\u5148\u751f", "role": "\u539f\u544a", "contact": "\u7535\u8bdd\uff1a138****1234\uff08\u97f3\u9891\u4e2d\u63d0\u53ca\uff09"}, {"name": "\u674e\u5e08\u5085", "role": "\u88ab\u544a", "contact": "\u7535\u8bdd\uff1a159****5678\uff08\u97f3\u9891\u4e2d\u63d0\u53ca\uff0c\u4e3a\u88c5\u4fee\u961f\u8d1f\u8d23\u4eba\uff09"}]', '2023年10月（签订合同并开始施工），问题发现于2024年1月', '王先生于2023年10月雇佣李师傅的装修队为其新房进行全屋装修，合同约定工期两个月，总费用12万元。施工过程中，王先生发现多处质量问题：1. 卫生间墙面瓷砖空鼓率超过50%，部分已脱落；2. 客厅铺设的实木地板存在严重色差且多处起拱；3. 定制橱柜尺寸与设计图纸不符，无法正常安装。王先生多次向李师傅反映，要求整改，但李师傅以‘材料本身问题’、‘正常工艺误差’等理由推诿，仅进行简单修补，问题未根本解决。双方沟通无效，矛盾激化。', '王先生要求：1. 李师傅对存在质量问题的部分（卫生间瓷砖、客厅地板、定制橱柜）进行彻底返工，达到合同约定的质量标准；2. 赔偿因工期延误和整改导致的误工费、在外租房费等损失共计3万元；3. 承担本次纠纷产生的相关鉴定费用。', '[{"name": "\u300a\u623f\u5c4b\u88c5\u4fee\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u660e\u786e\u7ea6\u5b9a\u4e86\u65bd\u5de5\u8303\u56f4\u3001\u6750\u6599\u54c1\u724c\u578b\u53f7\u3001\u5de5\u827a\u6807\u51c6\u3001\u5de5\u671f\u3001\u603b\u4ef7\u6b3e\u53ca\u4ed8\u6b3e\u65b9\u5f0f\u3002"}, {"name": "\u8bbe\u8ba1\u56fe\u7eb8\u4e0e\u6548\u679c\u56fe", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u53cc\u65b9\u786e\u8ba4\u7684\u88c5\u4fee\u8bbe\u8ba1\u56fe\u7eb8\uff0c\u7279\u522b\u662f\u6a71\u67dc\u7684\u8be6\u7ec6\u5c3a\u5bf8\u56fe\u3002"}, {"name": "\u73b0\u573a\u7167\u7247\u4e0e\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u6e05\u6670\u663e\u793a\u74f7\u7816\u7a7a\u9f13\u8131\u843d\u3001\u5730\u677f\u8272\u5dee\u8d77\u62f1\u3001\u6a71\u67dc\u5b89\u88c5\u4e0d\u7b26\u7684\u73b0\u72b6\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u5305\u62ec\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u6216\u7535\u5b50\u90ae\u4ef6\uff0c\u8bc1\u660e\u738b\u5148\u751f\u66fe\u591a\u6b21\u5c31\u8d28\u91cf\u95ee\u9898\u5411\u674e\u5e08\u5085\u63d0\u51fa\u5f02\u8bae\u53ca\u674e\u5e08\u5085\u7684\u56de\u590d\u5185\u5bb9\u3002"}, {"name": "\u4ed8\u6b3e\u51ed\u8bc1", "type": "\u4e66\u8bc1", "description": "\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55\u6216\u6536\u636e\uff0c\u8bc1\u660e\u738b\u5148\u751f\u5df2\u652f\u4ed8\u7684\u5de5\u7a0b\u6b3e\u91d1\u989d\u3002"}, {"name": "\u7b2c\u4e09\u65b9\u9274\u5b9a\u62a5\u544a", "type": "\u9274\u5b9a\u610f\u89c1", "description": "\u5efa\u8bae\u59d4\u6258\u5177\u6709\u8d44\u8d28\u7684\u5de5\u7a0b\u8d28\u91cf\u68c0\u6d4b\u673a\u6784\u5bf9\u88c5\u4fee\u8d28\u91cf\uff08\u5982\u74f7\u7816\u7a7a\u9f13\u7387\u3001\u5730\u677f\u95ee\u9898\u539f\u56e0\uff09\u8fdb\u884c\u9274\u5b9a\uff0c\u51fa\u5177\u4e66\u9762\u62a5\u544a\u3002"}, {"name": "\u635f\u5931\u8d39\u7528\u7968\u636e", "type": "\u4e66\u8bc1", "description": "\u5982\u56e0\u623f\u5c4b\u65e0\u6cd5\u5165\u4f4f\u800c\u4ea7\u751f\u7684\u989d\u5916\u79df\u623f\u5408\u540c\u53ca\u79df\u91d1\u652f\u4ed8\u51ed\u8bc1\u3002"}]', 'audio', '[音频文件: 8153aa7e-618b-4ce3-a7f9-26cbd3450049_测试.mp3]', '2026-04-01 18:20:22.613354+08', '2026-04-01 18:20:22.613354+08');
INSERT INTO "public"."dispute_infos" VALUES ('287029e7-f861-49c3-bade-fe33fe868e65', '邻里噪音扰民纠纷', '[{"name": "\u738b\u5973\u58eb", "role": "\u539f\u544a/\u6295\u8bc9\u65b9", "contact": "\u89c6\u9891\u4e2d\u672a\u63d0\u4f9b\u5177\u4f53\u8054\u7cfb\u65b9\u5f0f\uff0c\u5efa\u8bae\u8865\u5145\u624b\u673a\u53f7\u7801\u6216\u4f4f\u5740"}, {"name": "\u697c\u4e0a\u90bb\u5c45\uff08\u8eab\u4efd\u5f85\u6838\u5b9e\uff09", "role": "\u88ab\u544a/\u88ab\u6295\u8bc9\u65b9", "contact": "\u672a\u77e5"}]', '近三个月内，每日晚间至深夜（具体时间段视频中未明确）', '王女士反映，其楼上邻居长期在夜间制造持续噪音，包括拖动家具、重物掉落、脚步声等，严重影响其正常休息与生活。王女士曾多次与邻居沟通，但对方态度敷衍，问题未得到改善。噪音已导致王女士精神焦虑、睡眠不足。', '1. 要求楼上邻居立即停止噪音扰民行为；2. 要求对方书面道歉；3. 如协商无效，拟向法院提起诉讼，要求精神损害赔偿。', '[{"name": "\u81ea\u884c\u5f55\u5236\u7684\u566a\u97f3\u97f3\u9891/\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u738b\u5973\u58eb\u7528\u624b\u673a\u5f55\u5236\u7684\u591c\u95f4\u566a\u97f3\u7247\u6bb5\uff0c\u9700\u5305\u542b\u65f6\u95f4\u6233\uff0c\u80fd\u6e05\u6670\u53cd\u6620\u566a\u97f3\u7c7b\u578b\u3001\u6301\u7eed\u65f6\u95f4\u548c\u5f3a\u5ea6\u3002"}, {"name": "\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u4e0e\u90bb\u5c45\u6c9f\u901a\u7684\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u77ed\u4fe1\u6216\u5f55\u97f3\uff0c\u8bc1\u660e\u5df2\u5c1d\u8bd5\u534f\u5546\u4f46\u672a\u679c\u3002"}, {"name": "\u7269\u4e1a\u6216\u5c45\u59d4\u4f1a\u8c03\u89e3\u8bb0\u5f55", "type": "\u4e66\u8bc1", "description": "\u5982\u66fe\u5411\u7269\u4e1a\u6216\u5c45\u59d4\u4f1a\u6295\u8bc9\uff0c\u53ef\u63d0\u4f9b\u76f8\u5173\u8c03\u89e3\u8bb0\u5f55\u6216\u8bc1\u660e\u6587\u4ef6\u3002"}, {"name": "\u533b\u9662\u8bca\u65ad\u8bc1\u660e", "type": "\u4e66\u8bc1", "description": "\u5982\u56e0\u566a\u97f3\u5bfc\u81f4\u5065\u5eb7\u95ee\u9898\uff08\u5982\u795e\u7ecf\u8870\u5f31\u3001\u5931\u7720\u7b49\uff09\uff0c\u53ef\u63d0\u4f9b\u75c5\u5386\u6216\u8bca\u65ad\u8bc1\u660e\u3002"}, {"name": "\u8bc1\u4eba\u8bc1\u8a00", "type": "\u8bc1\u4eba\u8bc1\u8a00", "description": "\u5176\u4ed6\u53d7\u5f71\u54cd\u90bb\u5c45\u7684\u8bc1\u8a00\uff0c\u8bc1\u660e\u566a\u97f3\u5b58\u5728\u7684\u666e\u904d\u6027\u3002"}]', 'video', '[视频文件: ecd2b2ad-5609-4cb7-b90f-6e608b34db31_测试视频.mp4]', '2026-04-01 18:21:11.532235+08', '2026-04-01 18:21:11.532235+08');
INSERT INTO "public"."dispute_infos" VALUES ('f662d222-af66-4da6-a431-97e819f1fd25', '房屋租赁合同纠纷', '[{"name": "\u5f20\u4e09", "role": "\u539f\u544a", "contact": "13800138000"}, {"name": "\u674e\u56db", "role": "\u88ab\u544a", "contact": "13900139000"}]', '2023年10月1日', '原告张三与被告李四于2023年10月1日签订《房屋租赁合同》，约定张三将其位于XX市XX区XX路XX号XX室的房屋出租给李四，租期一年，月租金5000元，押一付三。合同签订后，李四支付了首期租金及押金共计20000元。李四入住后，以房屋存在漏水、空调无法制冷等质量问题为由，自2023年12月起拒绝支付后续租金。张三多次催告无果，双方协商未达成一致。', '原告张三诉求：1. 判令被告李四支付拖欠的租金15000元（2023年12月至2024年2月）；2. 判令解除双方签订的《房屋租赁合同》；3. 判令被告李四立即腾退房屋；4. 本案诉讼费用由被告承担。', '[{"name": "\u300a\u623f\u5c4b\u79df\u8d41\u5408\u540c\u300b", "type": "\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u88ab\u544a\u4e4b\u95f4\u5b58\u5728\u5408\u6cd5\u6709\u6548\u7684\u623f\u5c4b\u79df\u8d41\u6cd5\u5f8b\u5173\u7cfb\uff0c\u7ea6\u5b9a\u4e86\u79df\u91d1\u3001\u79df\u671f\u3001\u53cc\u65b9\u6743\u5229\u4e49\u52a1\u7b49\u6838\u5fc3\u6761\u6b3e\u3002"}, {"name": "\u79df\u91d1\u53ca\u62bc\u91d1\u6536\u636e/\u94f6\u884c\u8f6c\u8d26\u8bb0\u5f55", "type": "\u4e66\u8bc1/\u7535\u5b50\u6570\u636e", "description": "\u8bc1\u660e\u88ab\u544a\u5df2\u652f\u4ed8\u9996\u671f\u79df\u91d1\u53ca\u62bc\u91d1\uff0c\u4ee5\u53ca\u540e\u7eed\u79df\u91d1\u672a\u652f\u4ed8\u7684\u4e8b\u5b9e\u3002"}, {"name": "\u50ac\u6536\u79df\u91d1\u7684\u901a\u77e5\uff08\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55/\u77ed\u4fe1/\u51fd\u4ef6\uff09", "type": "\u7535\u5b50\u6570\u636e/\u4e66\u8bc1", "description": "\u8bc1\u660e\u539f\u544a\u5df2\u5c65\u884c\u50ac\u544a\u4e49\u52a1\uff0c\u88ab\u544a\u5b58\u5728\u8fdd\u7ea6\u884c\u4e3a\u3002"}, {"name": "\u5173\u4e8e\u623f\u5c4b\u8d28\u91cf\u95ee\u9898\u7684\u6c9f\u901a\u8bb0\u5f55", "type": "\u7535\u5b50\u6570\u636e\uff08\u5982\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\uff09", "description": "\u8bc1\u660e\u88ab\u544a\u66fe\u63d0\u51fa\u623f\u5c4b\u5b58\u5728\u8d28\u91cf\u95ee\u9898\uff0c\u4ee5\u53ca\u53cc\u65b9\u5c31\u6b64\u95ee\u9898\u8fdb\u884c\u534f\u5546\u7684\u8fc7\u7a0b\u3002"}, {"name": "\u623f\u5c4b\u73b0\u72b6\u7684\u7167\u7247\u6216\u89c6\u9891", "type": "\u89c6\u542c\u8d44\u6599", "description": "\u8bc1\u660e\u623f\u5c4b\u5728\u79df\u8d41\u671f\u95f4\u7684\u72b6\u6001\uff0c\u4ee5\u53ca\u53ef\u80fd\u5b58\u5728\u7684\u8d28\u91cf\u95ee\u9898\uff08\u5982\u6f0f\u6c34\u75d5\u8ff9\uff09\u3002"}, {"name": "\u7269\u4e1a\u6216\u7ef4\u4fee\u4eba\u5458\u7684\u8bc1\u8a00/\u8bb0\u5f55", "type": "\u8bc1\u4eba\u8bc1\u8a00/\u4e66\u8bc1", "description": "\u8f85\u52a9\u8bc1\u660e\u623f\u5c4b\u662f\u5426\u5b58\u5728\u88ab\u544a\u6240\u79f0\u7684\u8d28\u91cf\u95ee\u9898\u53ca\u5176\u4e25\u91cd\u7a0b\u5ea6\u3002"}]', 'image', '[图片文件: 2175a2b2-41a4-4797-a041-a483b8b15428_图片.png]', '2026-04-01 18:21:52.923483+08', '2026-04-01 18:21:52.923483+08');

-- ----------------------------
-- Table structure for document_drafts
-- ----------------------------
DROP TABLE IF EXISTS "public"."document_drafts";
CREATE TABLE "public"."document_drafts" (
  "id" int4 NOT NULL DEFAULT nextval('document_drafts_id_seq'::regclass),
  "user_id" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "document_type" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "title" varchar(255) COLLATE "pg_catalog"."default",
  "content" text COLLATE "pg_catalog"."default" NOT NULL,
  "result" text COLLATE "pg_catalog"."default",
  "status" varchar(20) COLLATE "pg_catalog"."default",
  "is_pinned" bool,
  "custom_title" varchar(255) COLLATE "pg_catalog"."default",
  "created_at" timestamptz(6) DEFAULT now(),
  "updated_at" timestamptz(6) DEFAULT now()
)
;

-- ----------------------------
-- Records of document_drafts
