INSERT INTO "public"."rights_protection_paths" VALUES ('730d4003-a49c-4a8a-8797-0b5cd02bbfa7', '949dc3b9-8bef-416c-89c3-625c664d6ba6', '合同纠纷/不当得利纠纷', '[{"step": 1, "action": "\u8bc1\u636e\u56fa\u5b9a\u4e0e\u5185\u90e8\u8bc4\u4f30", "description": "\u5168\u9762\u6536\u96c6\u5e76\u6574\u7406\u6240\u6709\u80fd\u8bc1\u660e\u53cc\u65b9\u5b58\u5728\u4e70\u5356\u5408\u610f\uff08\u800c\u975e\u8d60\u4e0e\uff09\u3001\u6807\u7684\u7269\uff08\u5976\u8336\uff09\u5df2\u4ea4\u4ed8\u3001\u4ef7\u6b3e\u91d1\u989d\u53ca\u4ed8\u6b3e\u671f\u9650\u7ea6\u5b9a\u7684\u8bc1\u636e\u3002\u8bc4\u4f30\u8bc1\u636e\u7684\u8bc1\u660e\u529b\u53ca\u7ea0\u7eb7\u91d1\u989d\u662f\u5426\u503c\u5f97\u542f\u52a8\u540e\u7eed\u7a0b\u5e8f\u3002", "required_materials": ["\u5fae\u4fe1/\u77ed\u4fe1\u804a\u5929\u8bb0\u5f55\uff08\u542b\u63d0\u53ca\u8d2d\u4e70\u3001\u4ef7\u683c\u3001\u6570\u91cf\u3001\u50ac\u6b3e\u7b49\u5185\u5bb9\uff09", "\u8f6c\u8d26\u8bb0\u5f55\u6216\u6536\u636e\uff08\u5982\u6709\u5b9a\u91d1\u6216\u90e8\u5206\u4ed8\u6b3e\uff09", "\u8bc1\u4eba\u8bc1\u8a00\uff08\u5982\u6709\u5171\u540c\u5728\u573a\u7684\u670b\u53cb\uff09", "\u5976\u8336\u5e97\u8ba2\u5355\u8bb0\u5f55\u6216\u6d88\u8d39\u51ed\u8bc1", "\u6e05\u6670\u7684\u7ea0\u7eb7\u8fc7\u7a0b\u4e66\u9762\u9648\u8ff0"], "estimated_time": "3-7\u5929", "estimated_cost": "\u514d\u8d39"}, {"step": 2, "action": "\u6b63\u5f0f\u534f\u5546\u4e0e\u50ac\u544a", "description": "\u57fa\u4e8e\u6574\u7406\u597d\u7684\u8bc1\u636e\uff0c\u901a\u8fc7\u5fae\u4fe1\u3001\u77ed\u4fe1\u6216\u53d1\u9001\u4e66\u9762\u300a\u50ac\u6b3e\u51fd\u300b/\u300a\u5f8b\u5e08\u51fd\u300b\u7684\u65b9\u5f0f\uff0c\u5411\u88ab\u544a\u88f4\u6da6\u6668\u6b63\u5f0f\u63d0\u51fa\u4ed8\u6b3e\u8981\u6c42\u3002\u5728\u6c9f\u901a\u4e2d\u660e\u786e\u6b3e\u9879\u6027\u8d28\u3001\u91d1\u989d\u3001\u62d6\u6b20\u4e8b\u5b9e\u53ca\u62df\u5b9a\u7684\u6700\u540e\u4ed8\u6b3e\u671f\u9650\uff0c\u5e76\u4fdd\u7559\u597d\u6240\u6709\u50ac\u544a\u8bb0\u5f55\u3002", "required_materials": ["\u6b65\u9aa41\u4e2d\u6574\u7406\u7684\u5168\u90e8\u8bc1\u636e\u526f\u672c", "\u64b0\u5199\u7684\u300a\u50ac\u6b3e\u51fd\u300b\u6216\u300a\u5f8b\u5e08\u51fd\u300b", "\u51fd\u4ef6\u9001\u8fbe\u7684\u51ed\u8bc1\uff08\u5982\u5feb\u9012\u5355\u3001\u622a\u56fe\uff09"], "estimated_time": "1-2\u5468", "estimated_cost": "\u82e5\u53d1\u5f8b\u5e08\u51fd\uff0c\u7ea6500-2000\u5143\uff1b\u81ea\u884c\u53d1\u51fd\u5219\u4ec5\u5feb\u9012\u8d39"}, {"step": 3, "action": "\u7533\u8bf7\u652f\u4ed8\u4ee4", "description": "\u82e5\u534f\u5546\u65e0\u679c\uff0c\u4e14\u503a\u6743\u503a\u52a1\u5173\u7cfb\u660e\u786e\u3001\u65e0\u5176\u4ed6\u4e89\u8bae\uff0c\u53ef\u5411\u6709\u7ba1\u8f96\u6743\u7684\u4eba\u6c11\u6cd5\u9662\u7533\u8bf7\u652f\u4ed8\u4ee4\u3002\u8fd9\u662f\u4e00\u79cd\u6bd4\u8bc9\u8bbc\u66f4\u5feb\u6377\u7684\u7a0b\u5e8f\u3002\u6cd5\u9662\u5ba1\u67e5\u540e\u5411\u503a\u52a1\u4eba\u53d1\u51fa\u652f\u4ed8\u4ee4\uff0c\u503a\u52a1\u4eba\u572815\u65e5\u5185\u4e0d\u63d0\u51fa\u5f02\u8bae\u5219\u652f\u4ed8\u4ee4\u751f\u6548\uff0c\u53ef\u7533\u8bf7\u5f3a\u5236\u6267\u884c\u3002", "required_materials": ["\u652f\u4ed8\u4ee4\u7533\u8bf7\u4e66", "\u539f\u544a\u8eab\u4efd\u8bc1\u660e", "\u88ab\u544a\u8eab\u4efd\u4fe1\u606f", "\u6b65\u9aa41\u548c2\u4e2d\u6240\u6709\u8bc1\u636e\u7684\u6e05\u6670\u526f\u672c", "\u8bc1\u660e\u503a\u6743\u5230\u671f\u4e14\u65e0\u4e89\u8bae\u7684\u8bf4\u660e"], "estimated_time": "1-2\u4e2a\u6708", "estimated_cost": "\u8bc9\u8bbc\u8d39\u6807\u51c6\u7ea61/3\uff0c\u5177\u4f53\u6309\u6b20\u6b3e\u91d1\u989d\u8ba1\u7b97\uff1b\u82e5\u9700\u5f8b\u5e08\u4ee3\u7406\uff0c\u589e\u52a0\u4ee3\u7406\u8d39"}, {"step": 4, "action": "\u63d0\u8d77\u6c11\u4e8b\u8bc9\u8bbc", "description": "\u5982\u679c\u652f\u4ed8\u4ee4\u56e0\u5bf9\u65b9\u5f02\u8bae\u800c\u5931\u6548\uff0c\u6216\u7ea0\u7eb7\u672c\u8eab\u5b58\u5728\u4e00\u5b9a\u4e89\u8bae\uff08\u5982\u5bf9\u65b9\u6297\u8fa9\u662f\u8d60\u4e0e\uff09\uff0c\u5219\u5e94\u76f4\u63a5\u63d0\u8d77\u8bc9\u8bbc\u3002\u6848\u7531\u53ef\u9009\u62e9\u201c\u4e70\u5356\u5408\u540c\u7ea0\u7eb7\u201d\u6216\u201c\u4e0d\u5f53\u5f97\u5229\u7ea0\u7eb7\u201d\u3002\u5411\u6cd5\u9662\u63d0\u4ea4\u8d77\u8bc9\u72b6\u548c\u8bc1\u636e\uff0c\u8bf7\u6c42\u5224\u4ee4\u88ab\u544a\u652f\u4ed8\u5976\u8336\u6b3e\u53ca\u903e\u671f\u4ed8\u6b3e\u5229\u606f\uff08\u53ef\u53c2\u7167LPR\u8ba1\u7b97\uff09\u3002", "required_materials": ["\u6c11\u4e8b\u8d77\u8bc9\u72b6", "\u539f\u88ab\u544a\u53cc\u65b9\u8eab\u4efd\u8bc1\u660e\u6587\u4ef6", "\u8bc1\u636e\u6e05\u5355\u53ca\u6240\u6709\u8bc1\u636e\u6750\u6599\u526f\u672c\uff08\u6309\u88ab\u544a\u4eba\u6570+1\u4efd\u51c6\u5907\uff09", "\u9001\u8fbe\u5730\u5740\u786e\u8ba4\u4e66"], "estimated_time": "3-6\u4e2a\u6708\uff08\u4e00\u5ba1\u7b80\u6613\u7a0b\u5e8f\uff09", "estimated_cost": "\u6848\u4ef6\u53d7\u7406\u8d39\uff08\u6309\u8bc9\u8bbc\u6807\u7684\u989d\u8ba1\u7b97\uff0c\u91d1\u989d\u5c0f\u5219\u8d39\u7528\u5f88\u4f4e\uff09\uff1b\u5f8b\u5e08\u4ee3\u7406\u8d39\uff08\u5982\u59d4\u6258\uff09\uff1b\u53ef\u80fd\u7684\u516c\u544a\u8d39\u3001\u9274\u5b9a\u8d39\u7b49"}, {"step": 5, "action": "\u7533\u8bf7\u5f3a\u5236\u6267\u884c", "description": "\u5728\u83b7\u5f97\u751f\u6548\u7684\u652f\u4ed8\u4ee4\u6216\u80dc\u8bc9\u5224\u51b3\u540e\uff0c\u5982\u679c\u88ab\u544a\u88f4\u6da6\u6668\u5728\u6cd5\u5b9a\u671f\u9650\u5185\u4ecd\u4e0d\u5c65\u884c\u4ed8\u6b3e\u4e49\u52a1\uff0c\u539f\u544a\u53ef\u5411\u4e00\u5ba1\u6cd5\u9662\u6216\u540c\u7ea7\u88ab\u6267\u884c\u4eba\u8d22\u4ea7\u6240\u5728\u5730\u6cd5\u9662\u7533\u8bf7\u5f3a\u5236\u6267\u884c\u3002", "required_materials": ["\u5f3a\u5236\u6267\u884c\u7533\u8bf7\u4e66", "\u751f\u6548\u6cd5\u5f8b\u6587\u4e66\uff08\u652f\u4ed8\u4ee4\u6216\u5224\u51b3\u4e66\uff09\u539f\u4ef6\u53ca\u590d\u5370\u4ef6", "\u6cd5\u5f8b\u6587\u4e66\u751f\u6548\u8bc1\u660e", "\u88ab\u6267\u884c\u4eba\u8d22\u4ea7\u7ebf\u7d22\uff08\u5982\u6709\uff09"], "estimated_time": "\u6267\u884c\u671f\u9650\u4e00\u822c\u4e3a6\u4e2a\u6708\uff0c\u4f46\u5b9e\u9645\u53d6\u51b3\u4e8e\u8d22\u4ea7\u67e5\u627e\u60c5\u51b5", "estimated_cost": "\u65e0\u9700\u7f34\u7eb3\u7533\u8bf7\u6267\u884c\u8d39\uff08\u7531\u88ab\u6267\u884c\u4eba\u627f\u62c5\uff09\uff0c\u4f46\u53ef\u80fd\u6d89\u53ca\u6267\u884c\u4e2d\u7684\u5b9e\u9645\u652f\u51fa"}]', 0, NULL, NULL, NULL, NULL, 85, '2026-03-22 22:19:49.590741+08', '2026-03-22 22:19:49.590741+08');
INSERT INTO "public"."rights_protection_paths" VALUES ('9bb2c54f-02a0-4345-a3de-bcd23deb3ca0', 'ab5143af-cf33-4857-8521-6eedcd9690e3', '合同纠纷/债务纠纷', '[{"step": 1, "action": "\u8bc1\u636e\u56fa\u5b9a\u4e0e\u6b63\u5f0f\u50ac\u544a", "description": "1. \u7cfb\u7edf\u6574\u7406\u5e76\u56fa\u5b9a\u6240\u6709\u80fd\u8bc1\u660e\u8be5\u627f\u8bfa\u6216\u7ea6\u5b9a\u7684\u8bc1\u636e\uff0c\u5305\u62ec\u4f46\u4e0d\u9650\u4e8e\uff1a\n   - \u4e66\u9762\u534f\u8bae\u3001\u5408\u540c\u3001\u8ba2\u5355\u786e\u8ba4\u5355\n   - \u5fae\u4fe1/\u77ed\u4fe1\u804a\u5929\u8bb0\u5f55\uff08\u9700\u5b8c\u6574\u622a\u56fe\uff0c\u4f53\u73b0\u53cc\u65b9\u8eab\u4efd\u3001\u627f\u8bfa\u5185\u5bb9\u3001\u6570\u91cf100\u676f\u3001\u672a\u5c65\u884c\u4e8b\u5b9e\uff09\n   - \u7535\u5b50\u90ae\u4ef6\u5f80\u6765\n   - \u5f55\u97f3\u5f55\u50cf\uff08\u5982\u6709\uff0c\u9700\u6e05\u6670\u53cd\u6620\u627f\u8bfa\u5185\u5bb9\uff09\n   - \u8bc1\u4eba\u8bc1\u8a00\uff08\u5982\u6709\uff09\n2. \u5411\u88ab\u544a\u88f4\u6da6\u6668\u53d1\u9001\u4e00\u4efd\u6b63\u5f0f\u7684\u4e66\u9762\u300a\u50ac\u544a\u51fd\u300b\u6216\u5f8b\u5e08\u51fd\uff0c\u660e\u786e\u8981\u6c42\u5176\u5728\u6307\u5b9a\u5408\u7406\u671f\u9650\u5185\uff08\u59827-15\u65e5\uff09\u5c65\u884c\u4ea4\u4ed8100\u676f\u5976\u8336\u7684\u4e49\u52a1\u3002\u51fd\u4ef6\u5e94\u901a\u8fc7\u53ef\u7559\u5b58\u51ed\u8bc1\u7684\u65b9\u5f0f\u9001\u8fbe\uff08\u5982\u5feb\u9012\u3001\u6302\u53f7\u4fe1\u3001\u516c\u8bc1\u9001\u8fbe\uff09\u3002", "required_materials": ["\u6240\u6709\u76f8\u5173\u6c9f\u901a\u8bb0\u5f55\u622a\u56fe/\u539f\u4ef6", "\u50ac\u544a\u51fd\u6587\u672c", "\u9001\u8fbe\u51ed\u8bc1\uff08\u5982\u5feb\u9012\u5355\uff09"], "estimated_time": "1-2\u5468", "estimated_cost": "\u8f83\u4f4e\uff08\u4e3b\u8981\u4e3a\u901a\u8baf\u3001\u5feb\u9012\u8d39\uff1b\u82e5\u59d4\u6258\u5f8b\u5e08\u53d1\u51fd\uff0c\u8d39\u7528\u53e6\u8ba1\uff09"}, {"step": 2, "action": "\u884c\u653f\u8c03\u89e3\u6216\u884c\u4e1a\u6295\u8bc9", "description": "\u82e5\u50ac\u544a\u65e0\u6548\uff0c\u53ef\u5c1d\u8bd5\u5411\u4ee5\u4e0b\u673a\u6784\u5bfb\u6c42\u8c03\u89e3\u6216\u6295\u8bc9\uff1a\n1. \u5f53\u5730\u5e02\u573a\u76d1\u7763\u7ba1\u7406\u90e8\u95e8\uff0812315\u5e73\u53f0\uff09\uff1a\u6295\u8bc9\u5176\u4e0d\u5c65\u884c\u5408\u540c\u7ea6\u5b9a\u6216\u627f\u8bfa\uff0c\u6d89\u5acc\u6d88\u8d39\u6b3a\u8bc8\uff08\u82e5\u6d89\u53ca\u7ecf\u8425\u884c\u4e3a\uff09\u3002\n2. \u6d88\u8d39\u8005\u534f\u4f1a\uff1a\u7533\u8bf7\u8c03\u89e3\u3002\n\u6b64\u6b65\u9aa4\u53ef\u5229\u7528\u884c\u653f\u529b\u91cf\u65bd\u52a0\u538b\u529b\uff0c\u4fc3\u6210\u548c\u89e3\u3002", "required_materials": ["\u6b65\u9aa41\u4e2d\u7684\u6240\u6709\u8bc1\u636e", "\u50ac\u544a\u51fd\u53ca\u9001\u8fbe\u51ed\u8bc1", "\u6295\u8bc9/\u8c03\u89e3\u7533\u8bf7\u4e66"], "estimated_time": "2-4\u5468", "estimated_cost": "\u514d\u8d39"}, {"step": 3, "action": "\u63d0\u8d77\u8bc9\u8bbc", "description": "\u82e5\u8c03\u89e3\u5931\u8d25\uff0c\u539f\u544a\u53ef\u5411\u4eba\u6c11\u6cd5\u9662\u63d0\u8d77\u8bc9\u8bbc\u3002\n1. **\u786e\u5b9a\u6848\u7531**\uff1a\u901a\u5e38\u4e3a\u201c\u4e70\u5356\u5408\u540c\u7ea0\u7eb7\u201d\u6216\u201c\u5408\u540c\u7ea0\u7eb7\u201d\u3002\n2. **\u786e\u5b9a\u8bc9\u8bbc\u8bf7\u6c42**\uff1a\n   - \u4e3b\u8981\u8bf7\u6c42\uff1a\u5224\u4ee4\u88ab\u544a\u5c65\u884c\u4ea4\u4ed8100\u676f\u5976\u8336\u7684\u503a\u52a1\u3002\n   - \u5907\u7528/\u66ff\u4ee3\u8bf7\u6c42\uff1a\u82e5\u4ea4\u4ed8\u5df2\u4e0d\u53ef\u80fd\u6216\u4e0d\u7ecf\u6d4e\uff0c\u8bf7\u6c42\u5224\u4ee4\u88ab\u544a\u652f\u4ed8\u7b49\u503c\u4ef7\u6b3e\uff08\u9700\u51c6\u5907\u5976\u8336\u5e02\u573a\u4ef7\u683c\u7684\u8bc1\u636e\uff09\u3002\n   - \u53ef\u9644\u52a0\u8bf7\u6c42\uff1a\u8d54\u507f\u56e0\u6b64\u4ea7\u751f\u7684\u5408\u7406\u8d39\u7528\uff08\u5982\u4ea4\u901a\u3001\u8bef\u5de5\u7b49\uff0c\u9700\u8bc1\u636e\uff09\u3002\n3. **\u9009\u62e9\u7ba1\u8f96\u6cd5\u9662**\uff1a\u88ab\u544a\u4f4f\u6240\u5730\u6216\u5408\u540c\u5c65\u884c\u5730\u4eba\u6c11\u6cd5\u9662\u3002\n4. **\u51c6\u5907\u8d77\u8bc9\u6750\u6599**\uff1a\u8d77\u8bc9\u72b6\u3001\u539f\u88ab\u544a\u8eab\u4efd\u8bc1\u660e\u3001\u6240\u6709\u8bc1\u636e\u6750\u6599\u526f\u672c\u3002\n5. **\u7acb\u6848**\uff1a\u5411\u6709\u7ba1\u8f96\u6743\u7684\u4eba\u6c11\u6cd5\u9662\u9012\u4ea4\u6750\u6599\u3002", "required_materials": ["\u8d77\u8bc9\u72b6", "\u539f\u544a\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6", "\u88ab\u544a\u8eab\u4efd\u4fe1\u606f\uff08\u59d3\u540d\u3001\u4f4f\u5740\u7b49\uff09", "\u6240\u6709\u8bc1\u636e\u6750\u6599\u7684\u6e05\u6670\u590d\u5370\u4ef6/\u6253\u5370\u4ef6", "\u8bc1\u636e\u6e05\u5355"], "estimated_time": "3-6\u4e2a\u6708\uff08\u4e00\u5ba1\u7b80\u6613\u7a0b\u5e8f\uff09\u6216\u66f4\u957f", "estimated_cost": "\u6848\u4ef6\u53d7\u7406\u8d39\uff08\u6309\u8bc9\u8bbc\u6807\u7684\u989d\u8ba1\u7b97\uff0c\u6807\u7684\u989d\u5c0f\u5219\u8d39\u7528\u5f88\u4f4e\uff09\u3001\u53ef\u80fd\u7684\u5f8b\u5e08\u8d39\u3001\u65f6\u95f4\u6210\u672c"}, {"step": 4, "action": "\u7533\u8bf7\u5f3a\u5236\u6267\u884c", "description": "\u5982\u679c\u6cd5\u9662\u5224\u51b3\u539f\u544a\u80dc\u8bc9\uff0c\u800c\u88ab\u544a\u5728\u5224\u51b3\u751f\u6548\u540e\u89c4\u5b9a\u671f\u9650\u5185\u4ecd\u4e0d\u5c65\u884c\uff0c\u539f\u544a\u53ef\u4ee5\u5411\u4e00\u5ba1\u6cd5\u9662\u7533\u8bf7\u5f3a\u5236\u6267\u884c\u3002\u6267\u884c\u6807\u7684\u53ef\u4ee5\u662f100\u676f\u5976\u8336\uff08\u7279\u5b9a\u7269\u4ea4\u4ed8\uff09\uff0c\u4e5f\u53ef\u4ee5\u662f\u7b49\u503c\u4ef7\u6b3e\uff08\u91d1\u94b1\u7ed9\u4ed8\uff09\u3002", "required_materials": ["\u5f3a\u5236\u6267\u884c\u7533\u8bf7\u4e66", "\u751f\u6548\u5224\u51b3\u4e66\u539f\u4ef6\u53ca\u590d\u5370\u4ef6", "\u88ab\u6267\u884c\u4eba\u8d22\u4ea7\u7ebf\u7d22\uff08\u5982\u6709\uff09"], "estimated_time": "\u6267\u884c\u65f6\u95f4\u4e0d\u786e\u5b9a\uff0c\u53d6\u51b3\u4e8e\u8d22\u4ea7\u67e5\u627e\u60c5\u51b5", "estimated_cost": "\u7533\u8bf7\u6267\u884c\u8d39\uff08\u6700\u7ec8\u7531\u88ab\u6267\u884c\u4eba\u627f\u62c5\uff09"}]', 0, NULL, NULL, NULL, NULL, 85, '2026-03-26 22:17:32.649276+08', '2026-03-26 22:17:32.649276+08');
INSERT INTO "public"."rights_protection_paths" VALUES ('6c8b0e3c-667c-4f10-a3c1-f60d649e73c8', '78813e0b-40b3-4514-9ca9-be44d6e76a45', '劳务合同纠纷/追索劳动报酬纠纷', '[{"step": 1, "action": "\u6b63\u5f0f\u4e66\u9762\u50ac\u544a", "description": "\u5411\u88ab\u544a\u5434\u67d0\u53d1\u9001\u6b63\u5f0f\u7684\u300a\u50ac\u6b3e\u51fd\u300b\u6216\u300a\u5f8b\u5e08\u51fd\u300b\uff0c\u660e\u786e\u5217\u51fa\u62d6\u6b20\u7684\u52b3\u52a1\u62a5\u916c\u91d1\u989d\u3001\u8ba1\u7b97\u4f9d\u636e\u3001\u7ea6\u5b9a\u7684\u4ed8\u6b3e\u671f\u9650\u3001\u903e\u671f\u5929\u6570\uff0c\u5e76\u8bbe\u5b9a\u4e00\u4e2a\u5408\u7406\u7684\u6700\u540e\u4ed8\u6b3e\u671f\u9650\uff08\u59823-5\u4e2a\u5de5\u4f5c\u65e5\uff09\u3002\u6b64\u6b65\u9aa4\u65e8\u5728\u56fa\u5b9a\u88ab\u544a\u8fdd\u7ea6\u4e8b\u5b9e\uff0c\u5e76\u4f5c\u4e3a\u540e\u7eed\u8bc9\u8bbc\u7684\u8bc1\u636e\u3002", "required_materials": ["\u53cc\u65b9\u7ea6\u5b9a\u7684\u62a5\u916c\u6807\u51c6\u8bc1\u660e\uff08\u5982\u5408\u540c\u3001\u5fae\u4fe1\u804a\u5929\u8bb0\u5f55\u3001\u5f55\u97f3\u7b49\uff09", "\u539f\u544a\u5b8c\u6210\u5de5\u4f5c\u7684\u8bc1\u660e\uff08\u5982\u5b8c\u5de5\u7167\u7247\u3001\u9a8c\u6536\u8bb0\u5f55\u3001\u8bc1\u4eba\u8bc1\u8a00\u7b49\uff09", "\u88ab\u544a\u8eab\u4efd\u4fe1\u606f\uff08\u59d3\u540d\u3001\u4f4f\u5740\u3001\u8eab\u4efd\u8bc1\u53f7\uff09"], "estimated_time": "1-2\u5468", "estimated_cost": "\u514d\u8d39\uff08\u81ea\u884c\u53d1\u9001\uff09\u6216 500-2000\u5143\uff08\u59d4\u6258\u5f8b\u5e08\u53d1\u51fd\uff09"}, {"step": 2, "action": "\u7533\u8bf7\u652f\u4ed8\u4ee4", "description": "\u82e5\u50ac\u544a\u65e0\u6548\uff0c\u4e14\u503a\u6743\u503a\u52a1\u5173\u7cfb\u660e\u786e\u3001\u5408\u6cd5\uff0c\u65e0\u5176\u4ed6\u7ea0\u7eb7\uff0c\u53ef\u5411\u6709\u7ba1\u8f96\u6743\u7684\u4eba\u6c11\u6cd5\u9662\uff08\u901a\u5e38\u662f\u88ab\u544a\u4f4f\u6240\u5730\u6216\u5408\u540c\u5c65\u884c\u5730\u6cd5\u9662\uff09\u7533\u8bf7\u652f\u4ed8\u4ee4\u3002\u8fd9\u662f\u4e00\u79cd\u5feb\u6377\u7684\u975e\u8bc9\u7a0b\u5e8f\u3002\u6cd5\u9662\u5ba1\u67e5\u540e\u5411\u503a\u52a1\u4eba\u53d1\u51fa\u652f\u4ed8\u4ee4\uff0c\u82e5\u5176\u572815\u65e5\u5185\u4e0d\u63d0\u51fa\u5f02\u8bae\u53c8\u4e0d\u5c65\u884c\uff0c\u503a\u6743\u4eba\u53ef\u7533\u8bf7\u5f3a\u5236\u6267\u884c\u3002", "required_materials": ["\u652f\u4ed8\u4ee4\u7533\u8bf7\u4e66", "\u539f\u544a\u8eab\u4efd\u8bc1\u660e", "\u88ab\u544a\u8eab\u4efd\u4fe1\u606f", "\u8bc1\u660e\u503a\u6743\u503a\u52a1\u5173\u7cfb\u660e\u786e\u7684\u8bc1\u636e\u6750\u6599\uff08\u540c\u6b65\u9aa41\uff09"], "estimated_time": "1-2\u4e2a\u6708", "estimated_cost": "\u8bc9\u8bbc\u8d39\u7ea6\u4e3a\u8bc9\u8bbc\u8bf7\u6c42\u91d1\u989d\u76841/3\uff0c\u4e14\u6bd4\u8bc9\u8bbc\u7a0b\u5e8f\u4f4e\u3002\u82e5\u8fdb\u5165\u6267\u884c\uff0c\u9700\u9884\u4ea4\u7533\u8bf7\u6267\u884c\u8d39\u3002"}, {"step": 3, "action": "\u63d0\u8d77\u6c11\u4e8b\u8bc9\u8bbc", "description": "\u5982\u679c\u652f\u4ed8\u4ee4\u56e0\u88ab\u544a\u63d0\u51fa\u5f02\u8bae\u800c\u5931\u6548\uff0c\u6216\u76f4\u63a5\u9009\u62e9\u8bc9\u8bbc\uff0c\u5e94\u7acb\u5373\u5411\u6709\u7ba1\u8f96\u6743\u7684\u4eba\u6c11\u6cd5\u9662\u63d0\u8d77\u8bc9\u8bbc\u3002\u8bc9\u8bbc\u8bf7\u6c42\u5e94\u660e\u786e\uff1a1. \u8bf7\u6c42\u5224\u4ee4\u88ab\u544a\u652f\u4ed8\u62d6\u6b20\u52b3\u52a1\u62a5\u916cX\u5143\uff1b2. \u8bf7\u6c42\u5224\u4ee4\u88ab\u544a\u652f\u4ed8\u903e\u671f\u4ed8\u6b3e\u5229\u606f\u635f\u5931\uff08\u53ef\u53c2\u7167\u5168\u56fd\u94f6\u884c\u95f4\u540c\u4e1a\u62c6\u501f\u4e2d\u5fc3\u516c\u5e03\u7684\u8d37\u6b3e\u5e02\u573a\u62a5\u4ef7\u5229\u7387LPR\u8ba1\u7b97\uff09\u3002", "required_materials": ["\u6c11\u4e8b\u8d77\u8bc9\u72b6", "\u539f\u544a\u8eab\u4efd\u8bc1\u590d\u5370\u4ef6", "\u88ab\u544a\u8eab\u4efd\u4fe1\u606f\u6750\u6599", "\u8bc1\u636e\u6e05\u5355\u53ca\u6240\u6709\u8bc1\u636e\u6750\u6599\u590d\u5370\u4ef6\uff08\u5305\u62ec\uff1a\u8bc1\u660e\u5408\u540c\u5173\u7cfb\u7684\u8bc1\u636e\u3001\u8bc1\u660e\u5df2\u5c65\u884c\u4e49\u52a1\u7684\u8bc1\u636e\u3001\u8bc1\u660e\u88ab\u544a\u8fdd\u7ea6\u7684\u8bc1\u636e\u3001\u8bc1\u660e\u635f\u5931\u7684\u8ba1\u7b97\u4f9d\u636e\u7b49\uff09"], "estimated_time": "3-6\u4e2a\u6708\uff08\u4e00\u5ba1\u7b80\u6613\u7a0b\u5e8f\uff09\u6216\u66f4\u957f", "estimated_cost": "\u6848\u4ef6\u53d7\u7406\u8d39\uff08\u6839\u636e\u8bc9\u8bbc\u6807\u7684\u989d\u8ba1\u7b97\uff0c\u7531\u539f\u544a\u9884\u4ea4\uff0c\u80dc\u8bc9\u540e\u53ef\u8981\u6c42\u88ab\u544a\u627f\u62c5\uff09\u3001\u53ef\u80fd\u7684\u5f8b\u5e08\u4ee3\u7406\u8d39\uff08\u5982\u59d4\u6258\uff09\u3001\u4ea4\u901a\u8d39\u7b49\u3002"}, {"step": 4, "action": "\u7533\u8bf7\u8d22\u4ea7\u4fdd\u5168", "description": "\uff08\u53ef\u9009\u4f46\u5efa\u8bae\u6b65\u9aa4\uff0c\u53ef\u5728\u8d77\u8bc9\u65f6\u6216\u8bc9\u524d\u8fdb\u884c\uff09\u4e3a\u9632\u6b62\u88ab\u544a\u8f6c\u79fb\u8d22\u4ea7\u5bfc\u81f4\u5224\u51b3\u96be\u4ee5\u6267\u884c\uff0c\u53ef\u6839\u636e\u60c5\u51b5\u5411\u6cd5\u9662\u7533\u8bf7\u5bf9\u88ab\u544a\u7684\u94f6\u884c\u5b58\u6b3e\u3001\u623f\u4ea7\u3001\u8f66\u8f86\u7b49\u8d22\u4ea7\u8fdb\u884c\u67e5\u5c01\u3001\u51bb\u7ed3\u3002\u901a\u5e38\u9700\u8981\u63d0\u4f9b\u62c5\u4fdd\uff08\u5982\u4fdd\u9669\u516c\u53f8\u4fdd\u51fd\u3001\u73b0\u91d1\u6216\u5b9e\u7269\uff09\u3002", "required_materials": ["\u8d22\u4ea7\u4fdd\u5168\u7533\u8bf7\u4e66", "\u62c5\u4fdd\u6750\u6599", "\u88ab\u7533\u8bf7\u4eba\u8d22\u4ea7\u7ebf\u7d22"], "estimated_time": "\u4e0e\u8bc9\u8bbc\u7a0b\u5e8f\u5e76\u884c", "estimated_cost": "\u4fdd\u5168\u7533\u8bf7\u8d39\uff08\u6709\u4e0a\u9650\uff0c\u80dc\u8bc9\u540e\u53ef\u8981\u6c42\u88ab\u544a\u627f\u62c5\uff09\u3001\u62c5\u4fdd\u8d39\u7528\u3002"}, {"step": 5, "action": "\u7533\u8bf7\u5f3a\u5236\u6267\u884c", "description": "\u83b7\u5f97\u751f\u6548\u7684\u652f\u4ed8\u4ee4\u6216\u80dc\u8bc9\u5224\u51b3\u540e\uff0c\u5982\u679c\u88ab\u544a\u5728\u6cd5\u5b9a\u671f\u9650\u5185\u4ecd\u4e0d\u5c65\u884c\uff0c\u539f\u544a\u5e94\u5728\u6cd5\u5b9a\u671f\u9650\u5185\uff08\u901a\u5e38\u4e3a2\u5e74\uff09\u5411\u7b2c\u4e00\u5ba1\u4eba\u6c11\u6cd5\u9662\u6216\u540c\u7ea7\u7684\u88ab\u6267\u884c\u8d22\u4ea7\u6240\u5728\u5730\u6cd5\u9662\u7533\u8bf7\u5f3a\u5236\u6267\u884c\u3002", "required_materials": ["\u5f3a\u5236\u6267\u884c\u7533\u8bf7\u4e66", "\u751f\u6548\u6cd5\u5f8b\u6587\u4e66\uff08\u652f\u4ed8\u4ee4\u3001\u5224\u51b3\u4e66\u7b49\uff09", "\u88ab\u6267\u884c\u4eba\u8d22\u4ea7\u7ebf\u7d22"], "estimated_time": "\u6267\u884c\u671f\u9650\u901a\u5e38\u4e3a6\u4e2a\u6708\uff0c\u4f46\u5b9e\u9645\u53d6\u51b3\u4e8e\u8d22\u4ea7\u67e5\u627e\u548c\u5904\u7f6e\u96be\u5ea6\u3002", "estimated_cost": "\u7533\u8bf7\u6267\u884c\u8d39\uff08\u65e0\u9700\u9884\u4ea4\uff0c\u4ece\u6267\u884c\u6b3e\u4e2d\u4f18\u5148\u6263\u9664\uff09\u3002"}]', 0, NULL, NULL, NULL, NULL, 85, '2026-04-01 14:52:41.48186+08', '2026-04-01 14:52:41.48186+08');

-- ----------------------------
-- Table structure for risk_warnings
-- ----------------------------
DROP TABLE IF EXISTS "public"."risk_warnings";
CREATE TABLE "public"."risk_warnings" (
  "id" varchar COLLATE "pg_catalog"."default" NOT NULL,
  "dispute_id" varchar COLLATE "pg_catalog"."default",
  "risk_summary" text COLLATE "pg_catalog"."default" NOT NULL,
  "lessons_learned" json,
  "prevention_suggestions" json,
  "future_check_items" json,
  "created_at" timestamptz(6) DEFAULT now(),
  "updated_at" timestamptz(6) DEFAULT now()
)
;

